const DIAS_SEMANA = ["Segunda", "Terça", "Quarta", "Quinta", "Sexta", "Sábado", "Domingo"];
const MESES_ABREV = ["jan", "fev", "mar", "abr", "mai", "jun", "jul", "ago", "set", "out", "nov", "dez"];
const INDICE_DIA_SEMANA = { "Domingo": 0, "Segunda": 1, "Terça": 2, "Quarta": 3, "Quinta": 4, "Sexta": 5, "Sábado": 6 };

const MESES_COMPLETOS = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"];

function gerarHorariosComData(datas, horas) {
  if (!datas.length || !horas.length) return [];
  const resultado = [];
  const datasOrdenadas = [...datas].sort();
  datasOrdenadas.forEach((dataIso) => {
    const [ano, mes, dia] = dataIso.split("-").map(Number);
    if (!ano) return;
    const data = new Date(ano, mes - 1, dia);
    const nomeDia = DIAS_SEMANA.find((d) => INDICE_DIA_SEMANA[d] === data.getDay());
    const dataFormatada = `${nomeDia}, ${dia} ${MESES_ABREV[mes - 1]} ${ano}`;
    horas.forEach((hora) => {
      resultado.push({
        chave: `${dataIso} ${hora}`,
        label: `${dataFormatada} · ${hora}`,
      });
    });
  });
  return resultado;
}

function formatarChaveHorario(chave) {
  const [dataParte, hora] = (chave || "").split(" ");
  if (!dataParte) return chave;
  const [ano, mes, dia] = dataParte.split("-").map(Number);
  if (!ano) return chave;
  const data = new Date(ano, mes - 1, dia);
  const nomeDia = DIAS_SEMANA.find((d) => INDICE_DIA_SEMANA[d] === data.getDay());
  return `${nomeDia}, ${dia} ${MESES_ABREV[mes - 1]} ${ano} · ${hora}`;
}



