function EnviarPerfilEmail({ titulo, seccoes }) {
  const [outro, setOutro] = useState("");
  const [estado, setEstado] = useState(""); // "" | a_enviar | ok | erro
  const [msg, setMsg] = useState("");
  const enviar = async () => {
    setEstado("a_enviar"); setMsg("");
    try {
      const { data: s } = await supabase.auth.getSession();
      const token = s?.session?.access_token;
      if (!token) throw new Error("Entra na tua conta para receberes o perfil.");
      const resp = await fetch("https://hspekqrhttxeckghtryi.supabase.co/functions/v1/enviar-perfil", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({ titulo, seccoes, outro: outro.trim() || null }),
      });
      const d = await resp.json().catch(() => ({}));
      if (!resp.ok || d.erro) throw new Error(d.erro || "Não foi possível enviar agora.");
      setEstado("ok"); setMsg(`Enviado para ${d.para || "o teu correio eletrónico"}. Vê também a pasta de spam.`);
    } catch (e) { setEstado("erro"); setMsg(e.message || "Não foi possível enviar agora."); }
  };
  return (
    <div className="rounded-2xl px-4 py-4" style={{ backgroundColor: palette.card, border: `1.5px solid ${palette.gold}` }}>
      <p className="text-[11px] tracking-[0.2em] font-semibold" style={{ color: palette.gold }}>GUARDAR O TEU PERFIL</p>
      <p className="font-serif text-lg leading-tight mt-1" style={{ color: palette.navy }}>Recebe o relatório no teu correio eletrónico</p>
      <input value={outro} onChange={(e) => setOutro(e.target.value)} type="email" placeholder="Enviar também para (opcional)" className="w-full mt-3 rounded-xl px-3 py-2.5 text-sm outline-none" style={{ backgroundColor: "#fff", border: `1px solid ${palette.goldSoft}`, color: palette.ink }} />
      <button onClick={enviar} disabled={estado === "a_enviar"} className="w-full mt-3 rounded-full py-3 text-sm font-medium" style={{ backgroundColor: palette.navy, color: palette.creamSoft, opacity: estado === "a_enviar" ? 0.6 : 1 }}>{estado === "a_enviar" ? "A enviar…" : "Enviar o meu perfil por correio eletrónico"}</button>
      {msg && <p className="text-[13px] mt-2 text-center" style={{ color: estado === "erro" ? "#9B3B2E" : palette.navySoft }}>{msg}</p>}
    </div>
  );
}

function Escala({ valor, onEscolher, max = 5 }) {
  return (
    <div className="flex gap-1">
      {Array.from({ length: max }, (_, i) => i + 1).map((v) => (
        <button key={v} onClick={() => onEscolher(v)} className="flex-1 rounded-lg py-1.5 text-[13px] font-medium" style={valor === v ? { backgroundColor: palette.navy, color: palette.creamSoft } : { border: `1px solid ${palette.goldSoft}`, color: palette.navy, backgroundColor: "#fff" }}>{v}</button>
      ))}
    </div>
  );
}

function PerfilVidaScreen({ guardado, onGuardar, onBack, onMarcar }) {
  const [passo, setPasso] = useState(guardado ? 99 : 0);
  const [d, setD] = useState(() => guardado || { proposito: [], frase: { talento: "", impacto: "", quem: "" }, valores: [], viver: {}, crencas: {}, areas: {}, feridas: {} });
  const set = (k, v) => setD((x) => ({ ...x, [k]: v }));
  const PASSOS = ["Propósito", "Valores", "Viver os valores", "Crenças", "Dores", "Feridas emocionais", "Experiências difíceis"];
  const topo = (titulo, sub) => (
    <div className="mb-4">
      <p className="text-[11px] tracking-[0.2em] font-semibold" style={{ color: palette.gold }}>PERFIL DE VIDA · {passo + 1} DE {PASSOS.length}</p>
      <p className="font-serif text-2xl leading-tight mt-1" style={{ color: palette.navy }}>{titulo}</p>
      {sub && <p className="text-sm mt-1 leading-relaxed" style={{ color: palette.navySoft }}>{sub}</p>}
      <div className="h-1.5 rounded-full mt-3 overflow-hidden" style={{ backgroundColor: `${palette.navy}14` }}><div className="h-full" style={{ width: `${(passo / PASSOS.length) * 100}%`, backgroundColor: palette.gold }} /></div>
    </div>
  );
  const caixa = { backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}66` };
  const inp = "w-full rounded-xl px-3 py-2.5 text-sm outline-none";
  const inpS = { backgroundColor: "#fff", border: `1px solid ${palette.goldSoft}`, color: palette.ink };
  const podeAvancar = [
    () => (d.atividades || []).length >= 3 && Boolean(d.frase.talento && d.frase.impacto),
    () => d.valores.length >= 3,
    () => d.valores.every((v) => d.viver[v]),
    () => CRENCAS.every((_, i) => d.crencas[i]),
    () => AREAS_VIDA.every((a) => d.areas[a]),
    () => PERGUNTAS_FERIDAS.every((_, i) => d.feridas[i]),
    () => true,
  ];
  const pode = () => (podeAvancar[passo] ? podeAvancar[passo]() : true);
  const avancar = () => { if (passo + 1 >= PASSOS.length) { const final = { ...d, data: new Date().toISOString() }; onGuardar(final); setPasso(99); } else setPasso(passo + 1); window.scrollTo(0, 0); };
  const navegacao = (
    <div className="flex gap-3 pt-4">
      {passo > 0 && <button onClick={() => setPasso(passo - 1)} className="rounded-full px-5 py-3 text-sm font-medium" style={{ border: `1px solid ${palette.navy}`, color: palette.navy }}>Anterior</button>}
      <button disabled={!pode()} onClick={avancar} className="flex-1 rounded-full py-3 text-sm font-medium" style={{ backgroundColor: palette.navy, color: palette.creamSoft, opacity: pode() ? 1 : 0.5 }}>{passo + 1 >= PASSOS.length ? "Ver o meu Perfil de Vida" : "Seguinte"}</button>
    </div>
  );

  if (passo === 99) {
    // ---- Relatório
    const frase = d.frase.talento || d.frase.impacto ? `Quero usar ${d.frase.talento || "o que tenho de melhor"} para ${d.frase.impacto || "fazer a diferença"}${d.frase.quem ? ` na vida de ${d.frase.quem}` : ""}.` : null;
    const voc = sugerirProfissoes(d.atividades || [], [...(d.proposito || []), d.frase.talento, d.frase.impacto, d.frase.quem]);
    const valoresOrd = [...d.valores].sort((a, b) => (d.viver[a] || 0) - (d.viver[b] || 0));
    const crencasTop = CRENCAS.map((c, i) => ({ c, v: d.crencas[i] || 0 })).filter((x) => x.v >= 3).sort((a, b) => b.v - a.v).slice(0, 3);
    const areasOrd = Object.entries(d.areas).sort((a, b) => a[1] - b[1]);
    const dores = areasOrd.filter(([, v]) => v <= 5).slice(0, 3);
    const fortes = areasOrd.filter(([, v]) => v >= 8).slice(-3).reverse();
    const fer = Object.keys(FERIDAS).map((k) => ({ k, v: PERGUNTAS_FERIDAS.reduce((s, [f], i) => s + (f === k ? d.feridas[i] || 0 : 0), 0) })).sort((a, b) => b.v - a.v);
    const ferPrincipal = fer[0].v >= 6 ? FERIDAS[fer[0].k] : null;
    const plano = [
      PLANO_VIDA.proposito,
      valoresOrd[0] && PLANO_VIDA.valores(valoresOrd[0]),
      crencasTop[0] && PLANO_VIDA.crenca(crencasTop[0].c),
      dores[0] && PLANO_VIDA.dor(dores[0][0]),
      ferPrincipal && PLANO_VIDA.ferida(ferPrincipal),
    ].filter(Boolean).slice(0, 4).map((t, i) => `Semana ${i + 1}: ${t}`);
    const bloco = (eyebrow, titulo, conteudo) => (
      <div className="rounded-2xl px-4 py-4" style={caixa}>
        <p className="text-[11px] tracking-[0.2em] font-semibold" style={{ color: palette.gold }}>{eyebrow}</p>
        {titulo && <p className="font-serif text-xl leading-tight mt-1" style={{ color: palette.navy }}>{titulo}</p>}
        <div className="mt-2">{conteudo}</div>
      </div>
    );
    const p_ = (t) => <p className="text-sm leading-relaxed" style={{ color: palette.ink }}>{t}</p>;
    const li = (arr) => <div className="space-y-1.5">{arr.map((t, i) => <p key={i} className="text-sm leading-snug flex gap-2" style={{ color: palette.ink }}><span style={{ color: palette.gold }}>•</span>{t}</p>)}</div>;
    return (
      <div className="pb-28">
        <SectionHeader eyebrow="O TEU RELATÓRIO" title="Perfil de Vida" onBack={onBack} backLabel="Laboratório" />
        <div className="px-6 space-y-3">
          <div className="rounded-2xl px-5 py-5" style={{ background: "linear-gradient(150deg, #E4C98C 0%, #C6A253 100%)" }}>
            <p className="text-[11px] tracking-[0.25em] font-semibold" style={{ color: palette.navy }}>O TEU PROPÓSITO</p>
            <p className="font-serif text-xl leading-snug mt-2" style={{ color: palette.navy }}>{frase || "Ainda por escrever: volta ao questionário e completa a tua frase."}</p>
          </div>
          {voc && bloco("PROPÓSITO E PROFISSÃO", `Perfil ${TIPOS_VOCACIONAIS[voc.t1].nome}${voc.t2 ? " e " + TIPOS_VOCACIONAIS[voc.t2].nome : ""}`, (
            <>
              {p_(`${TIPOS_VOCACIONAIS[voc.t1].frase}${voc.t2 ? " " + TIPOS_VOCACIONAIS[voc.t2].frase : ""}`)}
              {voc.combinacao && <><p className="text-[13px] font-semibold mt-3 mb-1" style={{ color: palette.navy }}>Profissões que juntam os dois lados</p>{li(voc.combinacao)}</>}
              <p className="text-[13px] font-semibold mt-3 mb-1" style={{ color: palette.navy }}>Profissões ligadas ao perfil {TIPOS_VOCACIONAIS[voc.t1].nome}</p>
              {li(TIPOS_VOCACIONAIS[voc.t1].profissoes)}
              {voc.t2 && <><p className="text-[13px] font-semibold mt-3 mb-1" style={{ color: palette.navy }}>Profissões ligadas ao perfil {TIPOS_VOCACIONAIS[voc.t2].nome}</p>{li(TIPOS_VOCACIONAIS[voc.t2].profissoes.slice(0, 4))}</>}
              <p className="text-xs mt-3" style={{ color: palette.navySoft }}>Com base no modelo de interesses vocacionais de John Holland. São pistas para explorar, não uma decisão: o propósito pode viver-se em muitas profissões.</p>
            </>
          ))}
          {bloco("VALORES A SEGUIR", "Os teus valores", li(valoresOrd.map((v) => `${v} — vives este valor ${d.viver[v]} em 5${d.viver[v] <= 3 ? " · dar-lhe mais espaço" : ""}`)))}
          {bloco("CRENÇAS", crencasTop.length ? "Crenças que te limitam" : "Sem crenças limitantes fortes", crencasTop.length ? <div className="space-y-2.5">{crencasTop.map(({ c }) => <div key={c[0]}><p className="text-sm line-through" style={{ color: palette.navySoft }}>{c[0]}</p><p className="text-sm font-medium" style={{ color: palette.navy }}>→ {c[1]}</p></div>)}</div> : p_("Nenhuma das crenças avaliadas parece pesar muito em ti neste momento."))}
          {bloco("DORES", dores.length ? "Áreas que pedem atenção" : "Sem áreas em sofrimento", <>{dores.length ? li(dores.map(([a, v]) => `${a}: ${v} em 10`)) : p_("Nenhuma área ficou abaixo de 6.")}{fortes.length > 0 && <p className="text-[13px] mt-2" style={{ color: palette.navySoft }}>Onde estás bem: {fortes.map(([a]) => a).join(", ")}.</p>}</>)}
          {bloco("FERIDAS EMOCIONAIS", ferPrincipal ? `Ferida de ${ferPrincipal.nome.toLowerCase()}` : "Nenhuma ferida se destaca", ferPrincipal ? <>{p_(ferPrincipal.frase)}<p className="text-[13px] mt-1.5" style={{ color: palette.navySoft }}><b>Como pode aparecer:</b> {ferPrincipal.sinais}</p><p className="text-[13px] mt-1.5" style={{ color: palette.navySoft }}><b>Caminho de cuidado:</b> {ferPrincipal.cuidado}</p></> : p_("As tuas respostas não mostram nenhuma ferida com muito peso neste momento."))}
          {bloco("PLANO DE 4 SEMANAS", "Os teus próximos passos", li(plano))}
          <div className="rounded-2xl px-4 py-3" style={{ backgroundColor: "#F6EDD8" }}>
            <p className="text-[13px] leading-relaxed" style={{ color: palette.navy }}>Este perfil é uma ferramenta de autoconhecimento e não é um diagnóstico. Se algum destes temas te pesa muito, falar com um/a psicólogo/a pode ajudar. Em Portugal, a linha SNS 24 (808 24 24 24) tem aconselhamento psicológico. Em emergência, liga 112.</p>
          </div>
          <EnviarPerfilEmail titulo="Perfil de Vida" seccoes={[
            frase && { titulo: "O teu propósito", texto: frase },
            voc && { titulo: `Propósito e profissão: perfil ${TIPOS_VOCACIONAIS[voc.t1].nome}${voc.t2 ? " e " + TIPOS_VOCACIONAIS[voc.t2].nome : ""}`, itens: [...(voc.combinacao || []), ...TIPOS_VOCACIONAIS[voc.t1].profissoes, ...(voc.t2 ? TIPOS_VOCACIONAIS[voc.t2].profissoes.slice(0, 4) : [])].filter((x, i, a) => a.indexOf(x) === i) },
            { titulo: "Valores a seguir", itens: valoresOrd.map((v) => `${v}: vives este valor ${d.viver[v]} em 5`) },
            crencasTop.length && { titulo: "Crenças que te limitam (e a alternativa)", itens: crencasTop.map(({ c }) => `${c[0]} → ${c[1]}`) },
            dores.length && { titulo: "Áreas que pedem atenção", itens: dores.map(([a, v]) => `${a}: ${v} em 10`) },
            ferPrincipal && { titulo: `Ferida emocional: ${ferPrincipal.nome}`, texto: `${ferPrincipal.frase} Caminho de cuidado: ${ferPrincipal.cuidado}` },
            { titulo: "Plano de 4 semanas", itens: plano },
          ].filter(Boolean)} />
          <button onClick={onMarcar} className="w-full rounded-full py-3.5 text-sm font-medium" style={{ backgroundColor: palette.gold, color: palette.navy }}>Marcar sessão de Life Coaching</button>
          <button onClick={() => setPasso(0)} className="w-full text-[13px] underline pt-1" style={{ color: palette.navySoft }}>Rever as minhas respostas</button>
        </div>
      </div>
    );
  }

  return (
    <div className="pb-28">
      <SectionHeader eyebrow="LIFE COACHING 3S" title="Perfil de Vida" onBack={onBack} backLabel="Laboratório" />
      <div className="px-6">
        {passo === 0 && (<>
          {topo("O teu propósito", "Escolhe o que mais se parece contigo. Não há respostas certas.")}
          <div className="space-y-3">
            <div className="rounded-2xl px-4 py-4" style={caixa}>
              <p className="text-sm font-medium" style={{ color: palette.navy }}>Que atividades te dão mais energia?</p>
              <p className="text-[13px] mb-2.5" style={{ color: palette.navySoft }}>Escolhe entre 3 e 6. Vamos ligá-las a profissões.</p>
              <div className="flex flex-wrap gap-2">
                {ATIVIDADES.map(([, t], i) => { const esc = d.atividades || []; const on = esc.includes(i); return (
                  <button key={i} onClick={() => set("atividades", on ? esc.filter((x) => x !== i) : esc.length < 6 ? [...esc, i] : esc)} className="rounded-full px-3 py-1.5 text-[13.5px] text-left" style={on ? { backgroundColor: palette.navy, color: palette.creamSoft } : { border: `1px solid ${palette.goldSoft}`, color: palette.navy, backgroundColor: "#fff" }}>{t}</button>
                ); })}
              </div>
            </div>
            <div className="rounded-2xl px-4 py-4" style={caixa}>
              <p className="text-sm font-medium mb-2" style={{ color: palette.navy }}>Agora, a tua frase de propósito:</p>
              <div className="space-y-3">
                <EscolherOuEscrever rotulo="Quero usar…" opcoes={OPCOES_PROPOSITO.talento} valor={d.frase.talento} onMudar={(v) => set("frase", { ...d.frase, talento: v })} />
                <EscolherOuEscrever rotulo="para…" opcoes={OPCOES_PROPOSITO.impacto} valor={d.frase.impacto} onMudar={(v) => set("frase", { ...d.frase, impacto: v })} />
                <EscolherOuEscrever rotulo="na vida de… (opcional)" opcoes={OPCOES_PROPOSITO.quem} valor={d.frase.quem} onMudar={(v) => set("frase", { ...d.frase, quem: v })} />
              </div>
            </div>
            <details className="rounded-2xl px-4 py-3" style={caixa}>
              <summary className="text-sm font-medium cursor-pointer" style={{ color: palette.navy }}>Queres aprofundar? Perguntas para escrever (opcional)</summary>
              <div className="space-y-3 mt-3">
                {PERGUNTAS_PROPOSITO.map((q, i) => (
                  <div key={i}><p className="text-sm font-medium mb-1.5" style={{ color: palette.navy }}>{q}</p>
                    <textarea rows={2} value={d.proposito[i] || ""} onChange={(e) => { const a = [...d.proposito]; a[i] = e.target.value; set("proposito", a); }} className={inp} style={inpS} placeholder="Escreve aqui…" /></div>
                ))}
              </div>
            </details>
          </div>
        </>)}
        {passo === 1 && (<>
          {topo("Os teus valores", "Escolhe entre 3 e 5 valores que queres que guiem a tua vida.")}
          <div className="flex flex-wrap gap-2">
            {VALORES.map((v) => { const on = d.valores.includes(v); return (
              <button key={v} onClick={() => set("valores", on ? d.valores.filter((x) => x !== v) : d.valores.length < 5 ? [...d.valores, v] : d.valores)} className="rounded-full px-3.5 py-2 text-sm" style={on ? { backgroundColor: palette.navy, color: palette.creamSoft } : { border: `1px solid ${palette.goldSoft}`, color: palette.navy, backgroundColor: "#fff" }}>{v}</button>
            ); })}
          </div>
          <p className="text-[13px] mt-3" style={{ color: palette.navySoft }}>{d.valores.length} de 5 escolhidos</p>
        </>)}
        {passo === 2 && (<>
          {topo("Quanto vives hoje cada valor?", "1 = quase nada, 5 = totalmente.")}
          <div className="space-y-2.5">{d.valores.map((v) => <div key={v} className="rounded-2xl px-4 py-3" style={caixa}><p className="text-sm font-medium mb-2" style={{ color: palette.navy }}>{v}</p><Escala valor={d.viver[v]} onEscolher={(n) => set("viver", { ...d.viver, [v]: n })} /></div>)}</div>
        </>)}
        {passo === 3 && (<>
          {topo("As tuas crenças", "Até que ponto sentes que cada frase é verdade para ti? 1 = nada, 5 = muito.")}
          <div className="space-y-2.5">{CRENCAS.map((c, i) => <div key={i} className="rounded-2xl px-4 py-3" style={caixa}><p className="text-sm mb-2" style={{ color: palette.navy }}>“{c[0]}”</p><Escala valor={d.crencas[i]} onEscolher={(n) => set("crencas", { ...d.crencas, [i]: n })} /></div>)}</div>
        </>)}
        {passo === 4 && (<>
          {topo("Onde te dói", "Avalia a tua satisfação em cada área da vida. 1 = muito insatisfeito/a, 10 = plenamente satisfeito/a.")}
          <div className="space-y-2.5">{AREAS_VIDA.map((a) => <div key={a} className="rounded-2xl px-4 py-3" style={caixa}><div className="flex justify-between mb-2"><p className="text-sm font-medium" style={{ color: palette.navy }}>{a}</p><span className="text-sm font-serif" style={{ color: palette.gold }}>{d.areas[a] || "–"}</span></div><Escala max={10} valor={d.areas[a]} onEscolher={(n) => set("areas", { ...d.areas, [a]: n })} /></div>)}</div>
        </>)}
        {passo === 5 && (<>
          {topo("Feridas emocionais", "Como te reconheces em cada frase? 1 = nada, 5 = muito. Responde pelo que sentes, não pelo que achas que devias sentir.")}
          <div className="space-y-2.5">{PERGUNTAS_FERIDAS.map(([, f], i) => <div key={i} className="rounded-2xl px-4 py-3" style={caixa}><p className="text-sm mb-2" style={{ color: palette.navy }}>{f}</p><Escala valor={d.feridas[i]} onEscolher={(n) => set("feridas", { ...d.feridas, [i]: n })} /></div>)}</div>
        </>)}
        {passo === 6 && (<>
          {topo("Experiências difíceis", null)}
          <div className="rounded-2xl px-4 py-4 space-y-3" style={caixa}>
            <p className="text-[14px] leading-relaxed" style={{ color: palette.ink }}>Algumas experiências marcam-nos de forma profunda: perdas, situações de medo, violência ou abandono. Quando isso acontece, é normal que ainda hoje influenciem o que sentimos, as nossas reações e as nossas relações.</p>
            <p className="text-[14px] leading-relaxed" style={{ color: palette.ink }}>Esta aplicação não avalia traumas, porque é um tema que merece acompanhamento especializado e um espaço seguro. O coaching pode ajudar-te a avançar no presente, mas não substitui a psicoterapia.</p>
            <p className="text-sm font-medium" style={{ color: palette.navy }}>Procura apoio de um/a psicólogo/a se:</p>
            <div className="space-y-1">{["memórias difíceis voltam muitas vezes ou de forma intensa;", "evitas pessoas, lugares ou situações por causa do que viveste;", "sentes ansiedade, tristeza ou irritação que não passam;", "tens dificuldade em dormir, concentrar-te ou sentir prazer."].map((t) => <p key={t} className="text-sm flex gap-2" style={{ color: palette.ink }}><span style={{ color: palette.gold }}>•</span>{t}</p>)}</div>
            <p className="text-sm leading-relaxed" style={{ color: palette.navy }}>Em Portugal, a linha SNS 24 (808 24 24 24) tem aconselhamento psicológico. Em emergência, liga 112.</p>
          </div>
        </>)}
        {navegacao}
      </div>
    </div>
  );
}

function LaboratorioScreen({ cfg, onBack, resultados = {}, onGuardar, onMarcar, inicial }) {
  const { perfis: PERFIS_LIDER, perguntasPerfil: PERGUNTAS_PERFIL, competencias: COMPETENCIAS_3S, dicasPilar: DICAS_PILAR, modelos: MODELOS_LIDERANCA, reflexao: PERGUNTAS_REFLEXAO, quizzes: QUIZZES_LIDERANCA, planoPerfil: PLANO_PERFIL, planoPilar: PLANO_PILAR, treinos: TREINOS_LIDERANCA, grupos: GRUPOS_TREINO, t: TX } = cfg;
  const [vista, setVista] = useState(inicial ? "treino" : null); // null | perfil | competencias | modelos | perguntas | quizzes | quiz | treinos | treino
  const [treinoId, setTreinoId] = useState(inicial || null);
  const [passo, setPasso] = useState(0);
  const [respostas, setRespostas] = useState([]);
  const [modeloAberto, setModeloAberto] = useState(null);
  const [iPergunta, setIPergunta] = useState(() => Math.floor(Math.random() * PERGUNTAS_REFLEXAO.length));
  const [textoReflexao, setTextoReflexao] = useState("");
  const [guardadoMsg, setGuardadoMsg] = useState("");
  const [quizId, setQuizId] = useState(null);

  const voltarLab = () => { setVista(null); setPasso(0); setRespostas([]); setQuizId(null); };
  const criarPlano = (titulo, origem, textos, etiquetas) => ({
    titulo, origem, data: new Date().toISOString(),
    passos: textos.map((t, i) => ({ etiqueta: etiquetas ? etiquetas[i] : null, texto: t, feito: false })),
  });
  const guardarPlano = (plano) => { onGuardar("plano", plano); };
  const alternarPasso = (i) => {
    const p = resultados.plano;
    if (!p) return;
    onGuardar("plano", { ...p, passos: p.passos.map((x, j) => (j === i ? { ...x, feito: !x.feito } : x)) });
  };
  const SEMANAS = ["Semana 1", "Semana 2", "Semana 3", "Semana 4"];
  const DIAS = ["Dia 1", "Dia 2", "Dia 4", "Dia 5", "Dia 7"];
  const cartao = (titulo, desc, extra, onClick) => (
    <button onClick={onClick} className="w-full text-left rounded-xl px-4 py-3 transition active:scale-[0.99]" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}66`, boxShadow: "0 3px 10px -8px rgba(27,51,85,0.25)" }}>
      <div className="flex items-center gap-3">
        <div className="flex-1 min-w-0">
          <p className="font-serif text-base leading-snug" style={{ color: palette.navy }}>{titulo}</p>
          <p className="text-xs mt-0.5 leading-snug" style={{ color: palette.navySoft }}>{desc}</p>
          {extra && <p className="text-xs mt-1.5 font-medium" style={{ color: palette.gold }}>{extra}</p>}
        </div>
        <ChevronRight size={18} style={{ color: palette.gold }} />
      </div>
    </button>
  );
  const cabecalho = (eyebrow, titulo, voltar, rotuloVoltar) => (
    <SectionHeader eyebrow={eyebrow} title={titulo} onBack={voltar} backLabel={rotuloVoltar} />
  );
  const botaoPrincipal = (texto, onClick, desativado) => (
    <button onClick={onClick} disabled={desativado} className="w-full rounded-full py-3.5 font-medium text-sm" style={{ backgroundColor: palette.navy, color: palette.creamSoft, opacity: desativado ? 0.5 : 1 }}>{texto}</button>
  );

  // ---- Teste: perfil de liderança
  if (vista === "perfil") {
    if (passo < PERGUNTAS_PERFIL.length) {
      const [pergunta, opcoes] = PERGUNTAS_PERFIL[passo];
      return (
        <div className="pb-28">
          {cabecalho(`PERGUNTA ${passo + 1} DE ${PERGUNTAS_PERFIL.length}`, TX.perfilTitulo, voltarLab, "Laboratório")}
          <div className="px-6">
            <div className="h-1.5 rounded-full mb-5 overflow-hidden" style={{ backgroundColor: `${palette.navy}14` }}>
              <div className="h-full" style={{ width: `${(passo / PERGUNTAS_PERFIL.length) * 100}%`, backgroundColor: palette.gold }} />
            </div>
            <p className="font-serif text-xl leading-snug mb-4" style={{ color: palette.navy }}>{pergunta}</p>
            <div className="space-y-2.5">
              {[...opcoes.slice(passo % 4), ...opcoes.slice(0, passo % 4)].map(([perfil, texto]) => (
                <button key={texto} onClick={() => { setRespostas((r) => [...r, perfil]); setPasso((p) => p + 1); }} className="w-full text-left rounded-2xl px-4 py-3.5 text-sm transition active:scale-[0.99]" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}66`, color: palette.ink }}>
                  {texto}
                </button>
              ))}
            </div>
          </div>
        </div>
      );
    }
    const contagem = Object.fromEntries(Object.keys(PERFIS_LIDER).map((k) => [k, 0]));
    respostas.forEach((r) => { contagem[r] += 1; });
    const ordenados = Object.keys(contagem).sort((a, b) => contagem[b] - contagem[a]);
    const principal = PERFIS_LIDER[ordenados[0]];
    const segundo = PERFIS_LIDER[ordenados[1]];
    const planoPerfil = criarPlano(`Plano de 4 semanas: ${TX.perfilPlano} ${principal.nome}`, "perfil", PLANO_PERFIL[ordenados[0]], SEMANAS);
    const guardar = () => {
      onGuardar("perfil", { perfil: ordenados[0], contagem, data: new Date().toISOString() });
      guardarPlano(planoPerfil);
      setGuardadoMsg("Resultado e plano guardados. Encontras o plano no Laboratório.");
    };
    return (
      <div className="pb-28">
        {cabecalho("O TEU RESULTADO", TX.perfilTitulo, voltarLab, "Laboratório")}
        <div className="px-6 space-y-4">
          <div className="rounded-3xl px-5 py-6 text-center" style={{ background: `linear-gradient(150deg, ${palette.navy} 0%, #24436E 100%)` }}>
            <p className="text-[11px] tracking-[0.25em] font-semibold" style={{ color: palette.gold }}>O TEU PERFIL PRINCIPAL</p>
            <p className="font-serif text-4xl mt-2" style={{ color: palette.creamSoft }}>{principal.nome}</p>
            <p className="text-sm mt-1" style={{ color: palette.goldSoft }}>{principal.frase}</p>
            {contagem[ordenados[1]] > 0 && <p className="text-xs mt-3" style={{ color: palette.creamSoft, opacity: 0.8 }}>Segundo perfil: {segundo.nome}</p>}
          </div>
          <div className="rounded-2xl px-5 py-4" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
            {ordenados.map((k) => <BarraPct key={k} rotulo={PERFIS_LIDER[k].nome} pct={Math.round((contagem[k] / PERGUNTAS_PERFIL.length) * 100)} destaque={k === ordenados[0]} />)}
          </div>
          {[["A tua força", principal.forca], ["Atenção a", principal.risco], ["Funciona melhor com", principal.quando], ["Para crescer", principal.crescer]].map(([t, d]) => (
            <div key={t}>
              <p className="text-[11px] tracking-[0.2em] font-semibold" style={{ color: palette.gold }}>{t.toUpperCase()}</p>
              <p className="text-sm mt-1 leading-relaxed" style={{ color: palette.ink }}>{d}</p>
            </div>
          ))}
          <p className="text-[13px] leading-relaxed rounded-xl px-4 py-3" style={{ backgroundColor: `${palette.gold}1F`, color: palette.navy }}>{TX.notaPerfil}</p>
          <PlanoCartao plano={planoPerfil} compacto />
          {botaoPrincipal("Guardar resultado e plano", guardar)}
          {guardadoMsg && <p className="text-[13px] text-center" style={{ color: palette.navySoft }}>{guardadoMsg}</p>}
          <button onClick={onMarcar} className="w-full rounded-full py-3 text-sm font-medium" style={{ border: `1px solid ${palette.navy}`, color: palette.navy }}>Falar sobre o meu perfil numa sessão</button>
          <button onClick={() => { setPasso(0); setRespostas([]); setGuardadoMsg(""); }} className="w-full text-[13px] underline" style={{ color: palette.navySoft }}>Repetir o teste</button>
        </div>
      </div>
    );
  }

  // ---- Teste: competências 3S
  if (vista === "competencias") {
    if (passo < COMPETENCIAS_3S.length) {
      const item = COMPETENCIAS_3S[passo];
      return (
        <div className="pb-28">
          {cabecalho(`${item.pilar.toUpperCase()} · ${passo + 1} DE ${COMPETENCIAS_3S.length}`, "Competências 3S", voltarLab, "Laboratório")}
          <div className="px-6">
            <div className="h-1.5 rounded-full mb-5 overflow-hidden" style={{ backgroundColor: `${palette.navy}14` }}>
              <div className="h-full" style={{ width: `${(passo / COMPETENCIAS_3S.length) * 100}%`, backgroundColor: palette.gold }} />
            </div>
            <p className="font-serif text-2xl leading-snug mb-5" style={{ color: palette.navy }}>{item.frase}</p>
            <div className="space-y-2">
              {ESCALA.map((rotulo, i) => (
                <button key={rotulo} onClick={() => { setRespostas((r) => [...r, i + 1]); setPasso((p) => p + 1); }} className="w-full flex items-center gap-3 text-left rounded-2xl px-4 py-3 text-sm" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}66`, color: palette.ink }}>
                  <span className="w-7 h-7 rounded-full flex items-center justify-center text-[13px] font-semibold shrink-0" style={{ backgroundColor: palette.navy, color: palette.gold }}>{i + 1}</span>
                  {rotulo}
                </button>
              ))}
            </div>
          </div>
        </div>
      );
    }
    const pilares = ["Saber", "Sentir", "Ser"].map((p) => {
      const vals = COMPETENCIAS_3S.map((c, i) => (c.pilar === p ? respostas[i] : null)).filter((v) => v != null);
      const pct = Math.round(((vals.reduce((a, b) => a + b, 0) - vals.length) / (vals.length * 4)) * 100);
      return { pilar: p, pct };
    });
    const forte = [...pilares].sort((a, b) => b.pct - a.pct)[0];
    const fraco = [...pilares].sort((a, b) => a.pct - b.pct)[0];
    const planoPilar = criarPlano(`Plano de 4 semanas: crescer no ${fraco.pilar}`, "competencias", PLANO_PILAR[fraco.pilar], SEMANAS);
    const guardar = () => {
      onGuardar("competencias", { pilares, data: new Date().toISOString() });
      guardarPlano(planoPilar);
      setGuardadoMsg("Resultado e plano guardados. Encontras o plano no Laboratório.");
    };
    return (
      <div className="pb-28">
        {cabecalho("O TEU RESULTADO", "Competências 3S", voltarLab, "Laboratório")}
        <div className="px-6 space-y-4">
          <div className="rounded-2xl px-5 py-5" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
            {pilares.map((p) => <BarraPct key={p.pilar} rotulo={p.pilar} pct={p.pct} destaque={p.pilar === forte.pilar} />)}
          </div>
          <div>
            <p className="text-[11px] tracking-[0.2em] font-semibold" style={{ color: palette.gold }}>O TEU PONTO FORTE</p>
            <p className="font-serif text-xl mt-1" style={{ color: palette.navy }}>{forte.pilar}</p>
          </div>
          <div>
            <p className="text-[11px] tracking-[0.2em] font-semibold" style={{ color: palette.gold }}>ONDE CRESCER: {fraco.pilar.toUpperCase()}</p>
            <p className="text-sm mt-1 leading-relaxed" style={{ color: palette.ink }}>{DICAS_PILAR[fraco.pilar]}</p>
          </div>
          <PlanoCartao plano={planoPilar} compacto />
          {botaoPrincipal("Guardar resultado e plano", guardar)}
          {guardadoMsg && <p className="text-[13px] text-center" style={{ color: palette.navySoft }}>{guardadoMsg}</p>}
          <button onClick={onMarcar} className="w-full rounded-full py-3 text-sm font-medium" style={{ border: `1px solid ${palette.navy}`, color: palette.navy }}>Trabalhar isto numa sessão</button>
          <button onClick={() => { setPasso(0); setRespostas([]); setGuardadoMsg(""); }} className="w-full text-[13px] underline" style={{ color: palette.navySoft }}>Repetir o teste</button>
        </div>
      </div>
    );
  }

  // ---- Treinos de competências
  if (vista === "treino") {
    const treino = TREINOS_LIDERANCA.find((t) => t.id === treinoId);
    if (treino) return <TreinoScreen key={treino.id} treino={treino} onVoltar={() => setVista("treinos")} resultados={resultados} onGuardar={onGuardar} onMarcar={onMarcar} />;
  }
  if (vista === "treinos" || vista === "treino") {
    const feitos = resultados.treinos || {};
    return (
      <div className="pb-28">
        {cabecalho("PARA TRABALHAR", "Treinos de competências", voltarLab, "Laboratório")}
        <p className="px-6 -mt-2 mb-5 text-sm leading-relaxed" style={{ color: palette.navySoft }}>Cada treino tem o essencial, situações para praticar, uma frase construída por ti e um plano de 7 dias.</p>
        {GRUPOS_TREINO.map((g) => (
          <div key={g} className="px-6 mb-6">
            <p className="text-[11px] tracking-[0.2em] font-semibold mb-3" style={{ color: palette.gold }}>{g.toUpperCase()}</p>
            <div className="space-y-3">
              {TREINOS_LIDERANCA.filter((t) => t.grupo === g).map((t) => cartao(t.titulo, t.desc, feitos[t.id] ? "Já treinaste · a tua frase está guardada" : null, () => { setTreinoId(t.id); setVista("treino"); }))}
            </div>
          </div>
        ))}
      </div>
    );
  }

  // ---- Quizzes
  if (vista === "quizzes") {
    const feitos = resultados.quizzes || {};
    return (
      <div className="pb-28">
        {cabecalho("TESTA O QUE SABES", TX.quizzesTitulo, voltarLab, "Laboratório")}
        <p className="px-6 -mt-2 mb-5 text-sm leading-relaxed" style={{ color: palette.navySoft }}>5 perguntas cada. No fim recebes a explicação das respostas e um plano de 7 dias feito para ti.</p>
        <div className="px-6 space-y-3">
          {QUIZZES_LIDERANCA.map((q) => cartao(q.titulo, q.desc, feitos[q.id] ? `Última vez: ${feitos[q.id].pontos} de ${feitos[q.id].total}` : null, () => { setQuizId(q.id); setVista("quiz"); setPasso(0); setRespostas([]); setGuardadoMsg(""); }))}
        </div>
      </div>
    );
  }
  if (vista === "quiz") {
    const quiz = QUIZZES_LIDERANCA.find((q) => q.id === quizId);
    const voltarQuizzes = () => { setVista("quizzes"); setPasso(0); setRespostas([]); };
    if (passo < quiz.perguntas.length) {
      const q = quiz.perguntas[passo];
      const respondida = respostas.length > passo;
      const escolha = respostas[passo];
      return (
        <div className="pb-28">
          {cabecalho(`PERGUNTA ${passo + 1} DE ${quiz.perguntas.length}`, quiz.titulo, voltarQuizzes, "Questionários")}
          <div className="px-6">
            <div className="h-1.5 rounded-full mb-5 overflow-hidden" style={{ backgroundColor: `${palette.navy}14` }}>
              <div className="h-full" style={{ width: `${(passo / quiz.perguntas.length) * 100}%`, backgroundColor: palette.gold }} />
            </div>
            <p className="font-serif text-xl leading-snug mb-4" style={{ color: palette.navy }}>{q.p}</p>
            <div className="space-y-2.5">
              {(() => { const n = q.o.length; const k = (passo * 3 + quiz.id.length) % n; return q.o.map((_, j) => (j + k) % n); })().map((i) => {
                const texto = q.o[i];
                const certa = respondida && i === q.c;
                const errada = respondida && i === escolha && i !== q.c;
                return (
                  <button key={i} disabled={respondida} onClick={() => setRespostas((r) => [...r, i])} className="w-full text-left rounded-2xl px-4 py-3.5 text-sm" style={{ backgroundColor: certa ? "#E3F1E7" : errada ? "#F8E1DE" : palette.card, border: `1px solid ${certa ? "#3C8D5A" : errada ? "#C0392B" : `${palette.goldSoft}66`}`, color: palette.ink }}>
                    {certa ? "✓ " : errada ? "✗ " : ""}{texto}
                  </button>
                );
              })}
            </div>
            {respondida && (
              <div className="mt-4 space-y-3">
                <p className="text-sm leading-relaxed rounded-xl px-4 py-3" style={{ backgroundColor: `${palette.gold}1F`, color: palette.navy }}>
                  <span className="font-semibold">{escolha === q.c ? "Certo! " : "Não é bem assim. "}</span>{q.e}
                </p>
                {botaoPrincipal(passo + 1 < quiz.perguntas.length ? "Próxima pergunta" : "Ver resultado e plano", () => setPasso((p) => p + 1))}
              </div>
            )}
          </div>
        </div>
      );
    }
    const pontos = quiz.perguntas.filter((q, i) => respostas[i] === q.c).length;
    const total = quiz.perguntas.length;
    const textos = planoDoQuiz(quiz, respostas);
    const planoQuiz = criarPlano(`Plano de 7 dias: ${quiz.titulo}`, "quiz-" + quiz.id, textos, DIAS.slice(0, textos.length));
    const mensagem = pontos === total ? "Excelente! Dominas este tema." : pontos >= 3 ? "Bom caminho. Há pormenores a afinar." : "Este tema merece a tua atenção. O plano ajuda.";
    const guardar = () => {
      onGuardar("quizzes", { ...(resultados.quizzes || {}), [quiz.id]: { pontos, total, data: new Date().toISOString() } });
      guardarPlano(planoQuiz);
      setGuardadoMsg("Plano guardado. Encontras o plano no Laboratório.");
    };
    return (
      <div className="pb-28">
        {cabecalho("O TEU RESULTADO", quiz.titulo, voltarQuizzes, "Questionários")}
        <div className="px-6 space-y-4">
          <div className="rounded-3xl px-5 py-6 text-center" style={{ background: `linear-gradient(150deg, ${palette.navy} 0%, #24436E 100%)` }}>
            <p className="font-serif text-5xl" style={{ color: palette.gold }}>{pontos}<span className="text-2xl" style={{ color: palette.creamSoft }}> / {total}</span></p>
            <p className="text-sm mt-2" style={{ color: palette.creamSoft }}>{mensagem}</p>
          </div>
          <PlanoCartao plano={planoQuiz} compacto />
          {botaoPrincipal("Guardar este plano", guardar)}
          {guardadoMsg && <p className="text-[13px] text-center" style={{ color: palette.navySoft }}>{guardadoMsg}</p>}
          <button onClick={onMarcar} className="w-full rounded-full py-3 text-sm font-medium" style={{ border: `1px solid ${palette.navy}`, color: palette.navy }}>Treinar isto numa sessão</button>
          <button onClick={() => { setPasso(0); setRespostas([]); setGuardadoMsg(""); }} className="w-full text-[13px] underline" style={{ color: palette.navySoft }}>Repetir o questionário</button>
        </div>
      </div>
    );
  }

  // ---- Modelos
  if (vista === "modelos") {
    return (
      <div className="pb-28">
        {cabecalho(TX.modelosEyebrow, TX.modelosTitulo, voltarLab, "Laboratório")}
        <div className="px-6 space-y-3">
          {MODELOS_LIDERANCA.map((m) => {
            const aberto = modeloAberto === m.nome;
            return (
              <div key={m.nome} className="rounded-2xl overflow-hidden" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}66` }}>
                <button onClick={() => setModeloAberto(aberto ? null : m.nome)} className="w-full flex items-center gap-3 text-left px-5 py-4">
                  <div className="flex-1">
                    <p className="font-serif text-lg" style={{ color: palette.navy }}>{m.nome}</p>
                    <p className="text-[13px]" style={{ color: palette.navySoft }}>{m.para}</p>
                  </div>
                  {aberto ? <ChevronDown size={18} style={{ color: palette.gold }} /> : <ChevronRight size={18} style={{ color: palette.gold }} />}
                </button>
                {aberto && (
                  <div className="px-5 pb-5 space-y-2.5">
                    {m.passos.map(([t, d], i) => (
                      <div key={t} className="flex gap-3">
                        <span className="w-7 h-7 rounded-full flex items-center justify-center text-[13px] font-semibold shrink-0" style={{ backgroundColor: palette.navy, color: palette.gold }}>{i + 1}</span>
                        <div>
                          <p className="text-sm font-semibold" style={{ color: palette.navy }}>{t}</p>
                          <p className="text-[13px] leading-relaxed" style={{ color: palette.navySoft }}>{d}</p>
                        </div>
                      </div>
                    ))}
                    {m.exemplo && <p className="text-[13px] italic rounded-xl px-3 py-2.5 mt-1" style={{ backgroundColor: `${palette.gold}1F`, color: palette.navy }}>Exemplo: {m.exemplo}</p>}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  // ---- Perguntas para líderes
  if (vista === "perguntas") {
    const pergunta = PERGUNTAS_REFLEXAO[iPergunta];
    const minhas = (resultados.reflexoes || []);
    const guardar = () => {
      if (!textoReflexao.trim()) return;
      onGuardar("reflexoes", [{ pergunta, resposta: textoReflexao.trim(), data: new Date().toISOString() }, ...minhas].slice(0, 50));
      setTextoReflexao("");
      setGuardadoMsg("Guardado no teu diário.");
    };
    return (
      <div className="pb-28">
        {cabecalho(TX.perguntasEyebrow, "Pergunta do dia", voltarLab, "Laboratório")}
        <div className="px-6 space-y-4">
          <div className="rounded-3xl px-5 py-7 text-center" style={{ background: `linear-gradient(150deg, ${palette.navy} 0%, #24436E 100%)` }}>
            <p className="text-[11px] tracking-[0.25em] font-semibold" style={{ color: palette.gold }}>PENSA NISTO</p>
            <p className="font-serif text-2xl leading-snug mt-3" style={{ color: palette.creamSoft }}>{pergunta}</p>
          </div>
          <button onClick={() => { setIPergunta((i) => (i + 1) % PERGUNTAS_REFLEXAO.length); setGuardadoMsg(""); }} className="w-full text-sm font-medium rounded-full py-2.5" style={{ border: `1px solid ${palette.gold}`, color: palette.navy }}>Outra pergunta</button>
          <textarea value={textoReflexao} onChange={(e) => setTextoReflexao(e.target.value)} rows={4} placeholder="Escreve aqui a tua resposta (só tu vês)…" className="w-full rounded-2xl px-4 py-3 text-sm resize-none" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}66`, color: palette.ink }} />
          {botaoPrincipal("Guardar no meu diário", guardar, !textoReflexao.trim())}
          {guardadoMsg && <p className="text-[13px] text-center" style={{ color: palette.navySoft }}>{guardadoMsg}</p>}
          {minhas.length > 0 && (
            <div>
              <p className="text-[11px] tracking-[0.2em] font-semibold mb-2" style={{ color: palette.gold }}>{TX.diario}</p>
              <div className="space-y-2">
                {minhas.slice(0, 10).map((r, i) => (
                  <div key={i} className="rounded-xl px-4 py-3" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}44` }}>
                    <p className="text-[13px] font-semibold" style={{ color: palette.navy }}>{r.pergunta}</p>
                    <p className="text-[13px] mt-1 leading-relaxed" style={{ color: palette.navySoft }}>{r.resposta}</p>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  // ---- Perfil de Vida (só no Life Coaching)
  const temPerfilVida = cfg === LAB_VIDA;
  if (vista === "vida") return <PerfilVidaScreen guardado={resultados.perfilVida} onGuardar={(v) => onGuardar("perfilVida", v)} onBack={voltarLab} onMarcar={onMarcar} />;
  // ---- Perfil Geral de Líder (só no Laboratório de Liderança)
  const temPerfilGeral = cfg === LAB_LIDERANCA;
  const PERGUNTAS_GERAL = [
    ...PERGUNTAS_PERFIL.map(([q, ops]) => ({ parte: "Tipo de liderança", q, ops })),
    ...PERGUNTAS_PERSONALIDADE.map(([q, ops]) => ({ parte: "Personalidade", q, ops: ops.map(([, v, t]) => [v, t]) })),
    ...PERGUNTAS_COMUNICACAO.map(([q, ops]) => ({ parte: "Comunicação", q, ops })),
    ...PERGUNTAS_ARQUETIPO.map(([q, ops]) => ({ parte: "Arquétipo", q, ops })),
    ...COMPETENCIAS_LIDER.map((c) => ({ parte: `Competências · ${c.nome}`, q: c.frase, ops: ESCALA_COMPETENCIAS, fixa: true })),
  ];
  const montarRelatorio = (g) => {
    if (!g) return null;
    const pers = PERSONALIDADES[g.personalidade];
    const com = COMUNICACOES[g.comunicacao];
    const arq = ARQUETIPOS[g.arquetipo];
    const arq2 = g.arquetipo2 ? ARQUETIPOS[g.arquetipo2] : null;
    const lid = resultados.perfil && PERFIS_LIDER[resultados.perfil.perfil];
    const comp = resultados.competencias && resultados.competencias.pilares;
    const compOrd = comp ? [...comp].sort((a, b) => b.pct - a.pct) : null;
    const cl = g.competenciasLider ? COMPETENCIAS_LIDER.map((c) => ({ ...c, v: g.competenciasLider[c.id] || 0 })).sort((a, b) => b.v - a.v) : null;
    const assertivo = g.comunicacao === "AS";
    const fortes = [lid && lid.forca, cl && cl.filter((c) => c.v >= 4).length > 0 && `Competências mais fortes: ${cl.filter((c) => c.v >= 4).slice(0, 3).map((c) => c.nome.toLowerCase()).join(", ")}.`, ...pers.fortes.slice(0, 2), arq.forte, assertivo ? "Comunicação assertiva: dizes o que pensas e sentes, com respeito por ti e pelos outros." : com.fortes[0], compOrd && `Pilar mais forte: ${compOrd[0].pilar} (${compOrd[0].pct}%).`].filter(Boolean);
    // Coerência: quem tem comunicação assertiva não recebe pontos a desenvolver sobre comunicação
    const ligadasComunicacao = ["comunicacao", "escuta", "conflitos"];
    const fracas = cl ? [...cl].reverse().filter((c) => c.v <= 3 && !(assertivo && ligadasComunicacao.includes(c.id))).slice(0, 2) : [];
    const persDev = pers.desenvolver.filter((t) => !(assertivo && /tom|ouvir|comunica/i.test(t)));
    const desenvolver = [...fracas.map((c) => `${c.nome}: ${c.dica}`), lid && !(assertivo && /ouvi/i.test(lid.crescer) && cl && (cl.find((c) => c.id === "escuta") || {}).v >= 4) && lid.crescer, ...persDev.slice(0, 2), arq.desenvolver, !assertivo && com.desenvolver[0], compOrd && compOrd[compOrd.length - 1].pct < 70 && `Pilar a desenvolver: ${compOrd[compOrd.length - 1].pilar} (${compOrd[compOrd.length - 1].pct}%).`].filter(Boolean);
    return {
      lideranca: lid ? { nome: lid.nome, frase: lid.frase, quando: lid.quando, risco: lid.risco, contagem: resultados.perfil.contagem } : null,
      arquetipo: { nome: arq.nome, frase: arq.frase, secundario: arq2 ? arq2.nome : null },
      personalidade: { nome: pers.nome, frase: pers.frase, comunicarComigo: pers.comunicarComigo, eixos: g.eixos },
      comunicacao: { nome: com.nome, frase: com.frase, contagem: g.comunicacaoContagem },
      competencias: comp || null,
      fortes, desenvolver,
      competenciasLider: cl,
      equipas: encaixeEquipas({ ...g, lideranca: g.lideranca || (resultados.perfil && resultados.perfil.perfil) }),
      plano: desenvolver.slice(0, 4).map((d, i) => `Semana ${i + 1}: ${d}`),
    };
  };
  if (vista === "geral") {
    if (passo < PERGUNTAS_GERAL.length) {
      const item = PERGUNTAS_GERAL[passo];
      const ops = item.fixa ? item.ops : [...item.ops.slice(passo % item.ops.length), ...item.ops.slice(0, passo % item.ops.length)];
      return (
        <div className="pb-28">
          {cabecalho(`${item.parte.toUpperCase()} · ${passo + 1} DE ${PERGUNTAS_GERAL.length}`, "Perfil Geral de Líder", voltarLab, "Laboratório")}
          <div className="px-6">
            <div className="h-1.5 rounded-full mb-5 overflow-hidden" style={{ backgroundColor: `${palette.navy}14` }}>
              <div className="h-full" style={{ width: `${(passo / PERGUNTAS_GERAL.length) * 100}%`, backgroundColor: palette.gold }} />
            </div>
            <p className="font-serif text-xl leading-snug mb-4" style={{ color: palette.navy }}>{item.q}</p>
            <div className="space-y-2.5">
              {ops.map(([v, t]) => (
                <button key={t} onClick={() => {
                  const novas = [...respostas, v];
                  if (passo + 1 === PERGUNTAS_GERAL.length) {
                    const nL = PERGUNTAS_PERFIL.length, nP = PERGUNTAS_PERSONALIDADE.length, nC = PERGUNTAS_COMUNICACAO.length, nA = PERGUNTAS_ARQUETIPO.length;
                    const resL = novas.slice(0, nL), resto = novas.slice(nL);
                    const contagemL = Object.fromEntries(Object.keys(PERFIS_LIDER).map((k) => [k, 0]));
                    resL.forEach((x) => { if (contagemL[x] !== undefined) contagemL[x] += 1; });
                    const ordL = Object.keys(contagemL).sort((a, b) => contagemL[b] - contagemL[a]);
                    onGuardar("perfil", { perfil: ordL[0], contagem: contagemL, data: new Date().toISOString() });
                    const resComp = resto.slice(nP + nC + nA);
                    onGuardar("perfilGeral", { ...calcularPerfilGeral(resto.slice(0, nP), resto.slice(nP, nP + nC), resto.slice(nP + nC, nP + nC + nA)), lideranca: ordL[0], competenciasLider: Object.fromEntries(COMPETENCIAS_LIDER.map((c, i) => [c.id, resComp[i] || 0])) });
                    setVista("relatorio"); setPasso(0); setRespostas([]); setTimeout(() => window.scrollTo(0, 0), 30);
                  } else { setRespostas(novas); setPasso(passo + 1); }
                }} className="w-full text-left rounded-2xl px-4 py-3.5 text-sm transition active:scale-[0.99]" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}66`, color: palette.ink }}>{t}</button>
              ))}
            </div>
            {passo > 0 && <button onClick={() => { setPasso(passo - 1); setRespostas(respostas.slice(0, -1)); }} className="mt-4 text-[13px] underline" style={{ color: palette.navySoft }}>Voltar à pergunta anterior</button>}
          </div>
        </div>
      );
    }
  }
  if (vista === "equipas") {
    const meu = resultados.perfilGeral ? encaixeEquipas({ ...resultados.perfilGeral, lideranca: resultados.perfilGeral.lideranca || (resultados.perfil && resultados.perfil.perfil) }) : null;
    const LIDS = Object.entries(PERFIS_LIDER);
    return (
      <div className="pb-28">
        {cabecalho("GUIA", "Tipos de equipa", voltarLab, "Laboratório")}
        <p className="px-6 -mt-2 mb-4 text-sm leading-relaxed" style={{ color: palette.navySoft }}>Cada equipa precisa de uma liderança diferente. Vê o que cada uma precisa{meu ? " e como o teu perfil se encaixa" : ""}.</p>
        {!meu && <div className="px-6 mb-4"><button onClick={() => { setVista("geral"); setPasso(0); setRespostas([]); }} className="w-full rounded-full py-3 text-sm font-medium" style={{ backgroundColor: palette.navy, color: palette.creamSoft }}>Fazer o Perfil Geral de Líder para ver o teu encaixe</button></div>}
        <div className="px-6 space-y-3">
          {TIPOS_EQUIPA.map((t) => {
            const m = meu && meu.find((x) => x.id === t.id);
            const melhor = LIDS.filter(([k]) => (t.lid[k] || 0) === 3).map(([, v]) => v.nome).join(" ou ");
            return (
              <div key={t.id} className="rounded-2xl px-4 py-4" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}66` }}>
                <div className="flex items-start justify-between gap-2">
                  <p className="font-serif text-lg leading-tight" style={{ color: palette.navy }}>{t.nome}</p>
                  {m && <span className="text-[11px] font-semibold px-2 py-0.5 rounded-full shrink-0" style={{ border: `1px solid ${palette.gold}`, color: m.nivel === "Exige mais de ti" ? palette.navySoft : palette.gold }}>{m.nivel}</span>}
                </div>
                <p className="text-sm mt-1" style={{ color: palette.ink }}>{t.frase}</p>
                <p className="text-[13.5px] mt-2" style={{ color: palette.navy }}><b>O que precisa:</b> {t.precisa}</p>
                {melhor && <p className="text-[13.5px] mt-1" style={{ color: palette.navy }}><b>Estilo que funciona melhor:</b> {melhor}</p>}
                {m && <p className="text-[13.5px] mt-1.5" style={{ color: palette.ink }}><b style={{ color: palette.navy }}>Para liderares esta equipa:</b> {m.melhorar}</p>}
              </div>
            );
          })}
        </div>
      </div>
    );
  }
  if (vista === "relatorio" && resultados.perfilGeral) {
    const r = montarRelatorio(resultados.perfilGeral);
    const bloco = (eyebrow, titulo, frase, extra) => (
      <div className="rounded-2xl px-4 py-4" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}66` }}>
        <p className="text-[11px] tracking-[0.2em] font-semibold" style={{ color: palette.gold }}>{eyebrow}</p>
        <p className="font-serif text-xl leading-tight mt-1" style={{ color: palette.navy }}>{titulo}</p>
        {frase && <p className="text-sm mt-1 leading-relaxed" style={{ color: palette.ink }}>{frase}</p>}
        {extra}
      </div>
    );
    const lista = (itens, cor) => (
      <div className="space-y-1.5 mt-2">{itens.map((t, i) => <p key={i} className="text-sm leading-snug flex gap-2" style={{ color: palette.ink }}><span style={{ color: cor }}>{cor === palette.gold ? "★" : "→"}</span>{t}</p>)}</div>
    );
    const e = r.personalidade.eixos;
    const totCom = Object.values(r.comunicacao.contagem).reduce((a, b) => a + b, 0) || 1;
    return (
      <div className="pb-28">
        {cabecalho("O TEU RELATÓRIO", "Perfil Geral de Líder", voltarLab, "Laboratório")}
        <div className="px-6 space-y-3">
          <div className="rounded-2xl px-5 py-5" style={{ background: `linear-gradient(160deg, ${palette.navy} 0%, #24436E 100%)` }}>
            <p className="text-[11px] tracking-[0.25em] font-semibold" style={{ color: palette.gold }}>EM RESUMO</p>
            <div className="grid grid-cols-2 gap-2 mt-3">
              {[["Liderança", r.lideranca ? r.lideranca.nome : "Por fazer"], ["Arquétipo", r.arquetipo.nome], ["Personalidade", r.personalidade.nome], ["Comunicação", r.comunicacao.nome], ["Equipa ideal", r.equipas[0].nome]].map(([k, v]) => (
                <div key={k} className={`rounded-xl px-3 py-2.5 ${k === "Equipa ideal" ? "col-span-2" : ""}`} style={{ backgroundColor: "rgba(255,255,255,0.07)", border: `1px solid ${palette.gold}44` }}>
                  <p className="text-[11px]" style={{ color: palette.goldSoft }}>{k}</p>
                  <p className="font-serif text-base leading-tight" style={{ color: palette.creamSoft }}>{v}</p>
                </div>
              ))}
            </div>
          </div>
          {r.lideranca
            ? bloco("TIPO DE LIDERANÇA", r.lideranca.nome, r.lideranca.frase, (
              <div className="mt-2">
                <p className="text-[13px]" style={{ color: palette.navySoft }}><b>Funciona melhor em:</b> {r.lideranca.quando}</p>
                <p className="text-[13px] mt-1" style={{ color: palette.navySoft }}><b>Cuidado com:</b> {r.lideranca.risco}</p>
                {r.lideranca.contagem && <div className="mt-3">{Object.entries(r.lideranca.contagem).sort((a, b) => b[1] - a[1]).map(([k, v]) => <BarraPct key={k} rotulo={PERFIS_LIDER[k].nome} pct={Math.round((v / Math.max(Object.values(r.lideranca.contagem).reduce((a, b) => a + b, 0), 1)) * 100)} destaque={PERFIS_LIDER[k].nome === r.lideranca.nome} />)}</div>}
                <p className="text-xs mt-1" style={{ color: palette.navySoft }}>Os bons líderes usam os quatro estilos conforme a pessoa e a situação. O teu estilo principal é aquele a que recorres com mais naturalidade.</p>
              </div>
            ))
            : bloco("TIPO DE LIDERANÇA", "Ainda por descobrir", "Faz o teste de perfil de liderança (2 minutos) para completares o relatório.", <button onClick={() => { setVista("perfil"); setPasso(0); setRespostas([]); }} className="mt-3 rounded-full px-4 py-2 text-[13px] font-medium" style={{ backgroundColor: palette.navy, color: palette.creamSoft }}>Fazer agora</button>)}
          {bloco("ARQUÉTIPO DE LÍDER", r.arquetipo.nome, r.arquetipo.frase, r.arquetipo.secundario && <p className="text-[13px] mt-2" style={{ color: palette.navySoft }}>Arquétipo secundário: {r.arquetipo.secundario}</p>)}
          {bloco("TIPO DE PERSONALIDADE", r.personalidade.nome, r.personalidade.frase, (
            <div className="mt-3">
              <BarraPct rotulo={`Ação ${e.acao} · Reflexão ${e.reflexao}`} pct={Math.round((e.acao / Math.max(e.acao + e.reflexao, 1)) * 100)} />
              <BarraPct rotulo={`Tarefas ${e.tarefas} · Pessoas ${e.pessoas}`} pct={Math.round((e.tarefas / Math.max(e.tarefas + e.pessoas, 1)) * 100)} />
              <p className="text-[13px]" style={{ color: palette.navySoft }}><b>Como comunicar contigo:</b> {r.personalidade.comunicarComigo}</p>
            </div>
          ))}
          {bloco("TIPO DE COMUNICAÇÃO", r.comunicacao.nome, r.comunicacao.frase, (
            <div className="mt-3">{Object.entries(r.comunicacao.contagem).map(([k, v]) => <BarraPct key={k} rotulo={COMUNICACOES[k].nome} pct={Math.round((v / totCom) * 100)} destaque={COMUNICACOES[k].nome === r.comunicacao.nome} />)}</div>
          ))}
          {r.competenciasLider && bloco("COMPETÊNCIAS DE LIDERANÇA", "As tuas 10 competências", "Autoavaliação de 1 a 5. A mais forte no topo.", (
            <div className="mt-3">{r.competenciasLider.map((c, i) => <BarraPct key={c.id} rotulo={`${c.nome} · ${c.v}/5`} pct={c.v * 20} destaque={i < 3 && c.v >= 4} />)}</div>
          ))}
          {r.competencias
            ? bloco("COMPETÊNCIAS 3S", "Saber · Sentir · Ser", null, <div className="mt-3">{r.competencias.map((c) => <BarraPct key={c.pilar} rotulo={c.pilar} pct={c.pct} />)}</div>)
            : bloco("COMPETÊNCIAS 3S", "Ainda por medir", "Faz o teste de competências 3S para veres os teus três pilares.", <button onClick={() => { setVista("competencias"); setPasso(0); setRespostas([]); }} className="mt-3 rounded-full px-4 py-2 text-[13px] font-medium" style={{ backgroundColor: palette.navy, color: palette.creamSoft }}>Fazer agora</button>)}
          {bloco("ONDE ÉS FORTE", "Os teus pontos fortes", null, lista(r.fortes, palette.gold))}
          {bloco("TIPOS DE EQUIPA", `A tua equipa ideal: ${r.equipas[0].nome}`, "Como o teu perfil se encaixa em cada tipo de equipa e o que tens de melhorar para a liderar.", (
            <div className="space-y-2.5 mt-3">
              {r.equipas.map((q, i) => {
                const cor = q.nivel === "Encaixe natural" ? palette.gold : q.nivel === "Bom encaixe" ? palette.navy : palette.navySoft;
                return (
                  <div key={q.id} className="rounded-xl px-3 py-3" style={{ backgroundColor: i === 0 ? "#F6EDD8" : "#fff", border: `1px solid ${palette.goldSoft}66` }}>
                    <div className="flex items-start justify-between gap-2">
                      <p className="text-sm font-semibold leading-snug" style={{ color: palette.navy }}>{q.nome}</p>
                      <span className="text-[11px] font-semibold px-2 py-0.5 rounded-full shrink-0" style={{ border: `1px solid ${cor}`, color: cor }}>{q.nivel}</span>
                    </div>
                    <p className="text-[13px] mt-1" style={{ color: palette.navySoft }}>{q.frase} Precisa de: {q.precisa}</p>
                    <p className="text-[13.5px] mt-1.5 leading-snug" style={{ color: palette.ink }}><b style={{ color: palette.navy }}>Para liderares esta equipa:</b> {q.melhorar}</p>
                  </div>
                );
              })}
            </div>
          ))}
          {bloco("PONTOS A DESENVOLVER", "Onde podes crescer", null, lista(r.desenvolver, palette.navy))}
          {bloco("PLANO DE 4 SEMANAS", "Os teus próximos passos", null, lista(r.plano, palette.navy))}
          <EnviarPerfilEmail titulo="Perfil Geral de Líder" seccoes={[
            { titulo: "Em resumo", itens: [`Liderança: ${r.lideranca ? r.lideranca.nome : "por fazer"}`, `Arquétipo: ${r.arquetipo.nome}${r.arquetipo.secundario ? " (secundário: " + r.arquetipo.secundario + ")" : ""}`, `Personalidade: ${r.personalidade.nome}`, `Comunicação: ${r.comunicacao.nome}`] },
            r.lideranca && { titulo: `Tipo de liderança: ${r.lideranca.nome}`, texto: `${r.lideranca.frase} Funciona melhor em: ${r.lideranca.quando} Cuidado com: ${r.lideranca.risco}`, itens: r.lideranca.contagem ? Object.entries(r.lideranca.contagem).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${PERFIS_LIDER[k].nome}: ${v}`) : undefined },
            { titulo: `Arquétipo: ${r.arquetipo.nome}`, texto: r.arquetipo.frase },
            { titulo: `Personalidade: ${r.personalidade.nome}`, texto: `${r.personalidade.frase} Como comunicar contigo: ${r.personalidade.comunicarComigo}` },
            { titulo: `Comunicação: ${r.comunicacao.nome}`, texto: r.comunicacao.frase },
            r.competenciasLider && { titulo: "Competências de liderança (1 a 5)", itens: r.competenciasLider.map((c) => `${c.nome}: ${c.v}/5`) },
            r.competencias && { titulo: "Competências 3S", itens: r.competencias.map((c) => `${c.pilar}: ${c.pct}%`) },
            { titulo: "Onde és forte", itens: r.fortes },
            { titulo: `Tipos de equipa · a tua equipa ideal: ${r.equipas[0].nome}`, itens: r.equipas.map((q) => `${q.nome} (${q.nivel}): ${q.melhorar}`) },
            { titulo: "Pontos a desenvolver", itens: r.desenvolver },
            { titulo: "Plano de 4 semanas", itens: r.plano },
          ].filter(Boolean)} />
          <button onClick={onMarcar} className="w-full rounded-full py-3.5 text-sm font-medium" style={{ backgroundColor: palette.gold, color: palette.navy }}>Marcar sessão para trabalhar o meu perfil</button>
          <button onClick={() => { setVista("geral"); setPasso(0); setRespostas([]); }} className="w-full text-[13px] underline pt-1" style={{ color: palette.navySoft }}>Repetir o questionário</button>
        </div>
      </div>
    );
  }

  // ---- Entrada do laboratório
  const perfilGuardado = resultados.perfil && PERFIS_LIDER[resultados.perfil.perfil];
  const compGuardadas = resultados.competencias && resultados.competencias.pilares;
  return (
    <div className="pb-28">
      {cabecalho(TX.eyebrow, TX.titulo, onBack, TX.voltar)}
      <p className="px-6 -mt-2 mb-5 text-sm leading-relaxed" style={{ color: palette.navySoft }}>{TX.intro}</p>
      {resultados.plano && (
        <div className="px-6 mb-5">
          <PlanoCartao plano={resultados.plano} onAlternar={alternarPasso} />
        </div>
      )}
      <div className="px-6 space-y-3">
        {temPerfilVida && (
          <button onClick={() => setVista("vida")} className="w-full text-left rounded-2xl px-4 py-4" style={{ background: "linear-gradient(150deg, #E4C98C 0%, #C6A253 100%)" }}>
            <p className="text-[11px] tracking-[0.2em] font-semibold" style={{ color: palette.navy }}>{resultados.perfilVida ? "O TEU RELATÓRIO" : "NOVO · 10 MINUTOS"}</p>
            <p className="font-serif text-xl mt-1" style={{ color: palette.navy }}>Perfil de Vida</p>
            <p className="text-[13px] mt-1 leading-snug" style={{ color: palette.navy, opacity: 0.85 }}>Propósito, valores, crenças, dores e feridas emocionais. Recebe-o no teu correio eletrónico.</p>
          </button>
        )}
        {temPerfilGeral && (
          <button onClick={() => { if (resultados.perfilGeral) setVista("relatorio"); else { setVista("geral"); setPasso(0); setRespostas([]); } }} className="w-full text-left rounded-2xl px-4 py-4" style={{ background: `linear-gradient(160deg, ${palette.navy} 0%, #24436E 100%)` }}>
            <p className="text-[11px] tracking-[0.2em] font-semibold" style={{ color: palette.gold }}>{resultados.perfilGeral ? "O TEU RELATÓRIO" : "NOVO · 8 MINUTOS"}</p>
            <p className="font-serif text-xl mt-1" style={{ color: palette.creamSoft }}>Perfil Geral de Líder</p>
            <p className="text-[13px] mt-1 leading-snug" style={{ color: palette.goldSoft }}>Tipo de liderança, arquétipo, personalidade, comunicação, pontos fortes e a desenvolver. Recebe-o no teu correio eletrónico.</p>
          </button>
        )}
        {temPerfilGeral && cartao("Tipos de equipa", "Equipas seniores, juniores, conflituosas, com dificuldade em manter processos e outras: o que cada uma precisa e como lideras melhor cada uma.", resultados.perfilGeral ? "Com o teu encaixe em cada equipa" : "11 tipos de equipa", () => setVista("equipas"))}
        {cartao("Treinos de competências", TX.treinosDesc, Object.keys(resultados.treinos || {}).length ? `${Object.keys(resultados.treinos).length} de ${TREINOS_LIDERANCA.length} feitos` : "7 treinos · frase e plano no fim", () => setVista("treinos"))}
        {cartao(TX.perfilTitulo, TX.perfilDesc, perfilGuardado ? `O teu perfil: ${perfilGuardado.nome}` : null, () => { setVista("perfil"); setPasso(0); setRespostas([]); setGuardadoMsg(""); })}
        {cartao("Competências 3S", TX.compDesc, compGuardadas ? compGuardadas.map((p) => `${p.pilar} ${p.pct}%`).join(" · ") : null, () => { setVista("competencias"); setPasso(0); setRespostas([]); setGuardadoMsg(""); })}
        {cartao(TX.quizzesTitulo, TX.quizzesDesc, Object.keys(resultados.quizzes || {}).length ? `${Object.keys(resultados.quizzes).length} de ${QUIZZES_LIDERANCA.length} feitos` : "5 questionários · plano automático no fim", () => setVista("quizzes"))}
        {cartao(TX.modelosTitulo, TX.modelosDesc, null, () => setVista("modelos"))}
        {cartao(TX.perguntasTitulo, TX.perguntasDesc, (resultados.reflexoes || []).length ? `${resultados.reflexoes.length} resposta(s) no teu diário` : null, () => { setVista("perguntas"); setGuardadoMsg(""); })}
      </div>
    </div>
  );
}

// Coach responsável por cada área (a dona pode mudar no Painel quando a tabela areas_coach existir).
const COACH_POR_AREA_PADRAO = {
  lideranca: "1306b6b7-c562-4cdc-b284-2b9d293d8795", // Conceição
  desenvolvimento: "1306b6b7-c562-4cdc-b284-2b9d293d8795", // Conceição
  desporto: "1b36a35d-b14d-4ed4-a4f2-e7d0fb58801d", // coach desportivo
};
const TITULO_COACH_PADRAO = { desporto: "Coach desportivo certificado" };

async function coachIdDaArea(area) {
  const { data: ac, error } = await supabase.from("areas_coach").select("mentor_user_id").eq("area", area).maybeSingle();
  if (error || !ac) return COACH_POR_AREA_PADRAO[area] || null;
  return ac.mentor_user_id || null;
}

