/* ---------------------------------------------------------
   Podcast
--------------------------------------------------------- */
function PodcastScreen({ onBack, souDona }) {
  const [escolaId, setEscolaId] = useState(escolas[0].id);
  const [episodios, setEpisodios] = useState([]);
  const [carregando, setCarregando] = useState(true);
  const [aAdicionar, setAAdicionar] = useState(false);
  const [novoTitulo, setNovoTitulo] = useState("");
  const [novaDescricao, setNovaDescricao] = useState("");
  const [novaDuracao, setNovaDuracao] = useState("");
  const [novoUrl, setNovoUrl] = useState("");
  const [aGuardar, setAGuardar] = useState(false);

  const spotifyUrl = podcastPorEscola[escolaId]?.spotifyUrl;

  const carregarEpisodios = () => {
    setCarregando(true);
    supabase
      .from("podcast_episodios")
      .select("*")
      .eq("escola_id", escolaId)
      .order("criado_em", { ascending: false })
      .then(({ data }) => {
        setEpisodios(data || []);
        setCarregando(false);
      })
      .catch(() => setCarregando(false));
  };

  useEffect(() => { carregarEpisodios(); }, [escolaId]);

  const adicionarEpisodio = async () => {
    if (!novoTitulo.trim() || !novoUrl.trim()) return;
    setAGuardar(true);
    await supabase.from("podcast_episodios").insert({
      escola_id: escolaId,
      titulo: novoTitulo.trim(),
      descricao: novaDescricao.trim(),
      duracao: novaDuracao.trim(),
      url: novoUrl.trim(),
    });
    setNovoTitulo(""); setNovaDescricao(""); setNovaDuracao(""); setNovoUrl("");
    setAAdicionar(false);
    setAGuardar(false);
    carregarEpisodios();
  };

  const apagarEpisodio = async (id) => {
    await supabase.from("podcast_episodios").delete().eq("id", id);
    carregarEpisodios();
  };

  return (
    <div className="pb-28">
      <SectionHeader eyebrow="EPISÓDIOS" title="Podcast" onBack={onBack} />

      <div className="px-6 mb-5 flex gap-2">
        {escolas.map((e) => {
          const ativo = e.id === escolaId;
          return (
            <button
              key={e.id}
              onClick={() => setEscolaId(e.id)}
              className="flex-1 rounded-full py-2 text-xs font-medium tracking-wide transition"
              style={
                ativo
                  ? { backgroundColor: palette.navy, color: palette.creamSoft }
                  : { backgroundColor: palette.card, color: palette.navySoft, border: `1px solid ${palette.goldSoft}55` }
              }
            >
              {e.nome}
            </button>
          );
        })}
      </div>

      <div className="px-6 mb-5">
        {spotifyUrl ? (
          <a
            href={spotifyUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="w-full rounded-2xl px-5 py-4 flex items-center gap-4 transition active:scale-[0.98]"
            style={{ backgroundColor: palette.navy }}
          >
            <div
              className="w-11 h-11 rounded-full flex items-center justify-center shrink-0"
              style={{ border: `1.5px solid ${palette.gold}` }}
            >
              <Headphones size={18} strokeWidth={1.6} style={{ color: palette.gold }} />
            </div>
            <div className="flex-1">
              <p className="font-serif text-lg leading-tight" style={{ color: palette.creamSoft }}>Ouvir no Spotify</p>
              <p className="text-[13px] mt-0.5" style={{ color: palette.goldSoft }}>Todos os episódios do programa</p>
            </div>
            <ArrowRight size={18} style={{ color: palette.gold }} />
          </a>
        ) : (
          <div
            className="w-full rounded-2xl px-5 py-4 flex items-center gap-4"
            style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}
          >
            <div
              className="w-11 h-11 rounded-full flex items-center justify-center shrink-0"
              style={{ border: `1.5px solid ${palette.goldSoft}` }}
            >
              <Headphones size={18} strokeWidth={1.6} style={{ color: palette.navySoft }} />
            </div>
            <div className="flex-1">
              <p className="font-serif text-lg leading-tight" style={{ color: palette.navy }}>Programa a chegar</p>
              <p className="text-[13px] mt-0.5" style={{ color: palette.navySoft }}>Ainda sem ligação do Spotify</p>
            </div>
          </div>
        )}
      </div>

      {souDona && (
        <div className="px-6 mb-5">
          {!aAdicionar ? (
            <button
              onClick={() => setAAdicionar(true)}
              className="w-full rounded-2xl px-5 py-3.5 flex items-center justify-center gap-2 text-sm font-medium"
              style={{ backgroundColor: palette.card, border: `1.5px dashed ${palette.gold}` }}
            >
              <Plus size={16} style={{ color: palette.gold }} />
              <span style={{ color: palette.navy }}>Adicionar episódio novo</span>
            </button>
          ) : (
            <div className="rounded-2xl px-5 py-4 space-y-2.5" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
              <p className="text-[11px] tracking-[0.2em] font-medium mb-1" style={{ color: palette.gold }}>NOVO EPISÓDIO — {escolas.find(e => e.id === escolaId)?.nome}</p>
              <input
                value={novoTitulo}
                onChange={(e) => setNovoTitulo(e.target.value)}
                placeholder="Título do episódio"
                className="w-full rounded-xl px-3.5 py-2.5 text-sm"
                style={{ backgroundColor: palette.creamSoft, color: palette.ink }}
              />
              <input
                value={novaDescricao}
                onChange={(e) => setNovaDescricao(e.target.value)}
                placeholder="Descrição curta (opcional)"
                className="w-full rounded-xl px-3.5 py-2.5 text-sm"
                style={{ backgroundColor: palette.creamSoft, color: palette.ink }}
              />
              <input
                value={novaDuracao}
                onChange={(e) => setNovaDuracao(e.target.value)}
                placeholder="Duração (ex.: 15 min)"
                className="w-full rounded-xl px-3.5 py-2.5 text-sm"
                style={{ backgroundColor: palette.creamSoft, color: palette.ink }}
              />
              <input
                value={novoUrl}
                onChange={(e) => setNovoUrl(e.target.value)}
                placeholder="Ligação do episódio no Spotify"
                className="w-full rounded-xl px-3.5 py-2.5 text-sm"
                style={{ backgroundColor: palette.creamSoft, color: palette.ink }}
              />
              <div className="flex gap-2 pt-1">
                <button
                  onClick={() => setAAdicionar(false)}
                  className="flex-1 rounded-xl py-2.5 text-sm font-medium"
                  style={{ backgroundColor: palette.creamSoft, color: palette.navySoft }}
                >
                  Cancelar
                </button>
                <button
                  onClick={adicionarEpisodio}
                  disabled={aGuardar || !novoTitulo.trim() || !novoUrl.trim()}
                  className="flex-1 rounded-xl py-2.5 text-sm font-medium disabled:opacity-50"
                  style={{ backgroundColor: palette.navy, color: palette.creamSoft }}
                >
                  {aGuardar ? "A guardar…" : "Guardar episódio"}
                </button>
              </div>
            </div>
          )}
        </div>
      )}

      <div className="px-6 space-y-3">
        {carregando ? (
          <p className="text-sm text-center py-6" style={{ color: palette.navySoft }}>A carregar episódios…</p>
        ) : episodios.length === 0 ? (
          <p className="text-sm text-center py-6" style={{ color: palette.navySoft }}>Ainda sem episódios aqui.</p>
        ) : (
          episodios.map((ep) => (
            <div key={ep.id} className="flex items-center gap-4 rounded-2xl px-4 py-4" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
              <div className="flex-1 min-w-0">
                <p className="text-[15px] font-medium" style={{ color: palette.ink }}>{ep.titulo}</p>
                {ep.descricao && <p className="text-[13px] mt-1 leading-relaxed" style={{ color: palette.navySoft }}>{ep.descricao}</p>}
                {ep.duracao && <p className="text-[13px] mt-1" style={{ color: palette.navySoft }}>{ep.duracao}</p>}
              </div>
              {souDona && (
                <button onClick={() => apagarEpisodio(ep.id)} className="shrink-0 p-1">
                  <Trash2 size={15} style={{ color: palette.navySoft, opacity: 0.6 }} />
                </button>
              )}
              {ep.url ? (
                <a
                  href={ep.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="w-11 h-11 rounded-full flex items-center justify-center shrink-0"
                  style={{ backgroundColor: palette.navy }}
                >
                  <Play size={16} style={{ color: palette.creamSoft }} />
                </a>
              ) : (
                <span
                  className="w-11 h-11 rounded-full flex items-center justify-center shrink-0"
                  style={{ border: `1.5px solid ${palette.goldSoft}`, opacity: 0.6 }}
                >
                  <Play size={16} style={{ color: palette.navySoft }} />
                </span>
              )}
            </div>
          ))
        )}
      </div>
    </div>
  );
}

