          <video key={`${curso.id}-${numero}`} src={`/videos/aula-${curso.id}-${numero}.mp4`} poster={`/videos/aula-${curso.id}-${numero}.jpg`} controls playsInline preload="metadata" className="w-full block" style={{ aspectRatio: "16 / 9" }} />
