function CartaoLivroLeitor({ material }) {
  const abrir = () => window.dispatchEvent(new CustomEvent("escola3s:abrir", { detail: "leitor-" + material.id }));
  return (
    <button onClick={abrir} className="w-full text-left rounded-xl px-4 py-3.5 flex gap-3.5 items-center" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
      {material.capa && <img src={material.capa} alt="" className="w-24 rounded-md shadow-md shrink-0" style={{ aspectRatio: "2 / 3", objectFit: "cover" }} />}
      <div className="flex-1 min-w-0">
        <p className="font-serif text-lg leading-snug" style={{ color: palette.navy }}>{material.titulo}</p>
        {material.desc && <p className="text-[13px] mt-0.5 leading-snug" style={{ color: palette.navySoft }}>{material.desc}</p>}
        <p className="text-[13px] mt-1.5 font-medium" style={{ color: palette.gold }}>Ler o início grátis · na app {material.preco}{material.precoFisico ? ` · impresso ${material.precoFisico}` : ""}</p>
      </div>
      <ChevronRight size={16} style={{ color: palette.navySoft }} />
    </button>
  );
}

function MaterialCard({ material, desbloqueado, onDesbloquear, desbloqueadoFisico, onDesbloquearFisico }) {
  if (material.leitor) return <CartaoLivroLeitor material={material} />;
  const [estado, setEstado] = useState("fechado");
  const [codigo, setCodigo] = useState("");
  const [telemovel, setTelemovel] = useState("");
  const [estadoFisico, setEstadoFisico] = useState("fechado");
  const [telemovelFisico, setTelemovelFisico] = useState("");
  const [aDescarregar, setADescarregar] = useState(false);
  const [codigoDesconto, setCodigoDesconto] = useState("");
  const [estadoPagamento, setEstadoPagamento] = useState(null);
  const [erroPagamento, setErroPagamento] = useState("");
  const [estadoPagamentoFisico, setEstadoPagamentoFisico] = useState(null);
  const [erroPagamentoFisico, setErroPagamentoFisico] = useState("");

  const CODIGO_DESCONTO_COMUNIDADE = "COMUNIDADE10";
  const descontoValido = codigoDesconto.trim().toUpperCase() === CODIGO_DESCONTO_COMUNIDADE;
  const precoComDesconto = (precoTexto) => {
    const valor = parseFloat(precoTexto.replace("€", "").replace(",", "."));
    if (isNaN(valor)) return precoTexto;
    const comDesconto = valor * 0.9;
    return `${comDesconto.toFixed(2).replace(".", ",")}€`;
  };

  const comprarMaterial = async () => {
    if (!telemovel.trim()) return;
    setErroPagamento("");
    setEstadoPagamento("a_enviar");
    try {
      guardarTelefone(telemovel.trim());
      const precoFinal = descontoValido ? precoComDesconto(material.preco) : material.preco;
      const resultado = await iniciarPagamentoMBWay("material", material.titulo, precoFinal, telemovel.trim());
      setEstadoPagamento("a_confirmar");
      const pago = await aguardarConfirmacaoPagamento(resultado.pagamento_id);
      if (pago) {
        onDesbloquear();
      } else {
        setEstadoPagamento("falhou");
        setErroPagamento("Não recebemos a confirmação a tempo. Se já pagaste, aguarda mais um pouco.");
      }
    } catch (e) {
      setEstadoPagamento("falhou");
      setErroPagamento(e.message || "Não foi possível iniciar o pagamento.");
    }
  };

  const comprarMaterialFisico = async () => {
    if (!telemovelFisico.trim()) return;
    setErroPagamentoFisico("");
    setEstadoPagamentoFisico("a_enviar");
    try {
      guardarTelefone(telemovelFisico.trim());
      const resultado = await iniciarPagamentoMBWay("material_fisico", `${material.titulo} (versão física)`, material.precoFisico, telemovelFisico.trim());
      setEstadoPagamentoFisico("a_confirmar");
      const pago = await aguardarConfirmacaoPagamento(resultado.pagamento_id);
      if (pago) {
        onDesbloquearFisico();
      } else {
        setEstadoPagamentoFisico("falhou");
        setErroPagamentoFisico("Não recebemos a confirmação a tempo. Se já pagaste, aguarda mais um pouco.");
      }
    } catch (e) {
      setEstadoPagamentoFisico("falhou");
      setErroPagamentoFisico(e.message || "Não foi possível iniciar o pagamento.");
    }
  };

  const descarregarFicheiro = async () => {
    if (!material.url) return;
    setADescarregar(true);
    try {
      const resposta = await fetch(material.url);
      const blob = await resposta.blob();
      const urlBlob = window.URL.createObjectURL(blob);
      const nomeFicheiro = material.url.split("/").pop() || "documento.pdf";
      const link = document.createElement("a");
      link.href = urlBlob;
      link.download = nomeFicheiro;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(urlBlob);
    } catch {
      window.open(material.url, "_blank", "noopener,noreferrer");
    }
    setADescarregar(false);
  };

  const urlCompleto = material.url ? new URL(material.url, window.location.origin).href : "";
  const imprimir = () => {
    const w = window.open(urlCompleto, "_blank", "noopener,noreferrer");
    if (w) { try { w.addEventListener("load", () => w.print()); } catch (e) {} }
  };
  const enviar = async () => {
    const texto = `${material.titulo} · Escola 3S`;
    try {
      if (navigator.share) { await navigator.share({ title: texto, text: texto, url: urlCompleto }); return; }
    } catch (e) { if (e && e.name === "AbortError") return; }
    window.open(`https://wa.me/?text=${encodeURIComponent(texto + "\n" + urlCompleto)}`, "_blank", "noopener,noreferrer");
  };

  const blocoFisico = material.tambemFisico && (
    <div className="mt-3 pt-3" style={{ borderTop: `1px solid ${palette.goldSoft}40` }}>
      {desbloqueadoFisico ? (
        <div className="flex items-center gap-1.5 text-[13px] font-medium" style={{ color: palette.gold }}>
          <CheckCircle2 size={14} />
          Versão física encomendada
        </div>
      ) : estadoFisico === "fechado" ? (
        <BotaoCarrinho pequeno rotulo="Encomendar versão física" item={{ chave: `fisico-${material.id}`, tipo: "material_fisico", materialId: material.id, titulo: `${material.titulo} (versão física)`, valor: precoNumero(material.precoFisico) }} />
      ) : estadoPagamentoFisico === "a_confirmar" ? (
        <div className="text-center py-3">
          <p className="text-[13px] font-medium" style={{ color: palette.navy }}>Confirma no teu telemóvel</p>
          <p className="text-xs" style={{ color: palette.navySoft }}>Abre a aplicação MB WAY e aprova.</p>
        </div>
      ) : (
        <div className="space-y-2">
          <input
            type="tel"
            value={telemovelFisico}
            onChange={(e) => setTelemovelFisico(e.target.value)}
            placeholder="Número de telemóvel (MB WAY)"
            className="w-full rounded-lg px-3 py-2 text-sm outline-none"
            style={{ backgroundColor: palette.creamSoft, border: `1px solid ${palette.goldSoft}55`, color: palette.ink }}
          />
          <button
            onClick={comprarMaterialFisico}
            disabled={estadoPagamentoFisico === "a_enviar"}
            className="w-full rounded-lg py-2 text-xs font-medium tracking-wide transition active:scale-[0.98] disabled:opacity-60"
            style={{ backgroundColor: palette.navy, color: palette.creamSoft }}
          >
            {estadoPagamentoFisico === "a_enviar" ? "A enviar pedido…" : `Pagar ${material.precoFisico} e encomendar`}
          </button>
          {erroPagamentoFisico && <p className="text-xs text-center" style={{ color: "#B23A3A" }}>{erroPagamentoFisico}</p>}
        </div>
      )}
    </div>
  );

  if (desbloqueado) {
    return (
      <div className="rounded-xl px-4 py-3" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
        <div className="flex items-center gap-3">
          {material.capa ? <img src={material.capa} alt="" className="w-10 rounded-sm shrink-0 shadow" style={{ aspectRatio: "2 / 3", objectFit: "cover" }} /> : <FileIcon size={16} style={{ color: palette.gold }} />}
          <p className="text-sm flex-1" style={{ color: palette.ink }}>{material.titulo}</p>
          {material.fisico ? (
            <span className="flex items-center gap-1.5 text-[13px] font-medium" style={{ color: palette.gold }}>
              <CheckCircle2 size={14} />
              Encomendado
            </span>
          ) : material.url ? (
            <button
              onClick={descarregarFicheiro}
              disabled={aDescarregar}
              className="flex items-center gap-1.5 text-[13px] font-medium"
              style={{ color: palette.navy, opacity: aDescarregar ? 0.6 : 1 }}
            >
              <Download size={14} />
              {aDescarregar ? "A descarregar…" : "Descarregar"}
            </button>
          ) : (
            <span className="flex items-center gap-1.5 text-[13px] font-medium" style={{ color: palette.navySoft, opacity: 0.6 }}>
              <Download size={14} />
              Em breve
            </span>
          )}
        </div>
        {material.url && !material.fisico && (
          <div className="flex gap-2 mt-2.5">
            <button onClick={imprimir} className="flex-1 rounded-lg py-1.5 text-[13px] font-medium" style={{ border: `1px solid ${palette.goldSoft}88`, color: palette.navy }}>🖨 Imprimir</button>
            <button onClick={enviar} className="flex-1 rounded-lg py-1.5 text-[13px] font-medium" style={{ backgroundColor: palette.navy, color: palette.creamSoft }}>Enviar a um cliente</button>
          </div>
        )}
        {blocoFisico}
      </div>
    );
  }

  return (
    <div className="rounded-xl px-4 py-3.5" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
      <div className="flex items-center gap-3">
        {material.capa ? <img src={material.capa} alt="" className="w-10 rounded-sm shrink-0 shadow" style={{ aspectRatio: "2 / 3", objectFit: "cover" }} /> : <FileIcon size={16} style={{ color: palette.gold }} />}
        <div className="flex-1 min-w-0">
          <p className="text-sm" style={{ color: palette.ink }}>{material.titulo}</p>
          <p className="text-[13px] mt-0.5" style={{ color: palette.navySoft }}>{material.formato}</p>
        </div>
        <p className="font-serif text-base shrink-0" style={{ color: palette.gold }}>{material.preco}</p>
      </div>

      {estado === "fechado" && (
        <div className="mt-3">
          <BotaoCarrinho pequeno item={{ chave: `material-${material.id}`, tipo: "material", materialId: material.id, titulo: material.titulo, valor: precoNumero(material.preco) }} />
        </div>
      )}

      {estado === "codigo" && (
        <div className="mt-3 space-y-2">
          <input
            type="text"
            value={codigo}
            onChange={(e) => setCodigo(e.target.value)}
            placeholder="Código de acesso"
            className="w-full rounded-lg px-3 py-2 text-sm outline-none"
            style={{ backgroundColor: palette.creamSoft, border: `1px solid ${palette.goldSoft}55`, color: palette.ink }}
          />
          <button
            onClick={() => codigo.trim() && onDesbloquear()}
            className="w-full rounded-lg py-2 text-xs font-medium tracking-wide transition active:scale-[0.98]"
            style={{ backgroundColor: palette.navy, color: palette.creamSoft }}
          >
            Desbloquear
          </button>
        </div>
      )}

      {estado === "pagar" && (
        <div className="mt-3 space-y-2">
          {estadoPagamento === "a_confirmar" ? (
            <div className="text-center py-3">
              <p className="text-[13px] font-medium" style={{ color: palette.navy }}>Confirma no teu telemóvel</p>
              <p className="text-xs" style={{ color: palette.navySoft }}>Abre a aplicação MB WAY e aprova.</p>
            </div>
          ) : (
            <>
              <input
                type="tel"
                value={telemovel}
                onChange={(e) => setTelemovel(e.target.value)}
                placeholder="Número de telemóvel (MB WAY)"
                className="w-full rounded-lg px-3 py-2 text-sm outline-none"
                style={{ backgroundColor: palette.creamSoft, border: `1px solid ${palette.goldSoft}55`, color: palette.ink }}
              />
              {false && <input
                type="text"
                value={codigoDesconto}
                onChange={(e) => setCodigoDesconto(e.target.value)}
                placeholder="Código de desconto (opcional)"
                className="w-full rounded-lg px-3 py-2 text-sm outline-none"
                style={{ backgroundColor: palette.creamSoft, border: `1px solid ${palette.goldSoft}55`, color: palette.ink }}
              />}
              {descontoValido && (
                <p className="text-[13px] text-center" style={{ color: palette.gold }}>
                  Código aplicado — 10% de desconto
                </p>
              )}
              <button
                onClick={comprarMaterial}
                disabled={estadoPagamento === "a_enviar"}
                className="w-full rounded-lg py-2 text-xs font-medium tracking-wide transition active:scale-[0.98] disabled:opacity-60"
                style={{ backgroundColor: palette.navy, color: palette.creamSoft }}
              >
                {estadoPagamento === "a_enviar" ? "A enviar pedido…" : `Pagar ${descontoValido ? precoComDesconto(material.preco) : material.preco} e desbloquear`}
              </button>
              {erroPagamento && <p className="text-xs text-center" style={{ color: "#B23A3A" }}>{erroPagamento}</p>}
            </>
          )}
        </div>
      )}
      {blocoFisico}
    </div>
  );
}

/* ---------------------------------------------------------
   Marcar Sessão
--------------------------------------------------------- */
function MarcarSessaoScreen({ onBack, onConfirmar, creditos = {}, descontoCiclo = 0, onUsouCredito, area, descontoAluno = false }) {
  const [passo, setPasso] = useState(1); // 1: serviço, 2: profissional, 3: horário
  const [servicoEscolhido, setServicoEscolhido] = useState(null);
  const [mentoras, setMentoras] = useState([]);
  const [mentoraEscolhida, setMentoraEscolhida] = useState(null);
  const [ocupados, setOcupados] = useState([]);
  const [aCarregar, setACarregar] = useState(true);
  const [horario, setHorario] = useState(null);
  const [telemovel, setTelemovel] = useState("");
  const [erro, setErro] = useState("");
  const [aConfirmar, setAConfirmar] = useState(false);
  const [confirmado, setConfirmado] = useState(false);
  const [codigoDesconto, setCodigoDesconto] = useState("");
  const [estadoPagamento, setEstadoPagamento] = useState(null);
  const [nomeCompleto, setNomeCompleto] = useState("");
  const [aceitouConsentimento, setAceitouConsentimento] = useState(false);

  const TEXTO_CONSENTIMENTO = "Aceito fornecer os meus dados pessoais (nome, correio eletrónico e telemóvel) à Escola 3S, para fins de marcação e contacto sobre esta sessão.";

  const CODIGO_DESCONTO_COMUNIDADE = "COMUNIDADE10";
  const descontoValido = codigoDesconto.trim().toUpperCase() === CODIGO_DESCONTO_COMUNIDADE;
  const precoComDesconto = (precoTexto) => {
    const valor = parseFloat(precoTexto.replace("€", "").replace(",", "."));
    if (isNaN(valor)) return precoTexto;
    const comDesconto = valor * 0.9;
    return `${comDesconto.toFixed(2).replace(".", ",")}€`;
  };

  const carregarMentoras = async () => {
    setACarregar(true);
    const { data } = await supabase.from("mentores_disponibilidade").select("*").order("nome", { ascending: true });
    let lista = data || [];
    if (area) {
      // Cada área tem um coach responsável: só esse aparece.
      const id = await coachIdDaArea(area);
      lista = lista.filter((m) => id && m.user_id === id);
    }
    setMentoras(lista);
    setACarregar(false);
  };

  const carregarOcupados = async (mentorUserId) => {
    if (!mentorUserId) { setOcupados([]); return; }
    const { data } = await supabase
      .from("marcacoes")
      .select("horario")
      .in("estado", ["confirmada", "pendente_pagamento"])
      .eq("mentor_user_id", mentorUserId);
    setOcupados((data || []).map((m) => m.horario));
  };

  useEffect(() => { carregarMentoras(); }, []);

  const escolherMentora = (m) => {
    setMentoraEscolhida(m);
    carregarOcupados(m.user_id);
    setPasso(3);
  };

  const horariosDisponiveis = mentoraEscolhida
    ? gerarHorariosComData(mentoraEscolhida.dias, mentoraEscolhida.horas)
    : [];
  const horariosLivres = horariosDisponiveis.filter((h) => !ocupados.includes(h.chave));

  const usaCiclo = Boolean(servicoEscolhido && (creditos[servicoEscolhido.tipo] || 0) > 0);
  const eGratis = Boolean(servicoEscolhido && servicoEscolhido.gratis);
  const [jaUsouExperiencia, setJaUsouExperiencia] = useState(false);
  useEffect(() => {
    (async () => {
      const { data: s } = await supabase.auth.getSession();
      const uid = s?.session?.user?.id;
      if (!uid) return;
      const { data } = await supabase.from("marcacoes").select("id").eq("user_id", uid).eq("tipo", "Experiência").neq("estado", "cancelada").limit(1);
      setJaUsouExperiencia(Boolean(data && data.length));
    })();
  }, []);

  const confirmarMarcacao = async () => {
    if (!telemovel.trim() || !horario || !nomeCompleto.trim() || !aceitouConsentimento) return;
    setErro("");
    setAConfirmar(true);
    try {
      const { data: sessaoAtual } = await supabase.auth.getSession();
      const userId = sessaoAtual.session.user.id;
      const emailAtual = sessaoAtual.session.user.email;

      await supabase
        .from("clientes")
        .upsert(
          { user_id: userId, email: emailAtual, nome: nomeCompleto.trim(), telefone: telemovel.trim(), atualizado_em: new Date().toISOString() },
          { onConflict: "user_id" }
        )
        .then(() => {})
        .catch(() => {});

      await supabase
        .from("consentimentos_dados")
        .insert({ user_id: userId, email: emailAtual, nome: nomeCompleto.trim(), telefone: telemovel.trim(), texto_aceite: TEXTO_CONSENTIMENTO })
        .then(() => {})
        .catch(() => {});

      const { data: novaMarcacao, error } = await supabase
        .from("marcacoes")
        .insert({
          user_id: userId,
          mentor_user_id: mentoraEscolhida.user_id,
          tipo: servicoEscolhido.tipo,
          titulo: usaCiclo ? `${servicoEscolhido.titulo} (ciclo de 4 sessões)` : descontoValido ? `${servicoEscolhido.titulo} (desconto de aluno 3S — 10%)` : servicoEscolhido.titulo,
          horario: horario.chave,
          estado: usaCiclo || eGratis ? "confirmada" : "pendente_pagamento",
          pago_com_ciclo: usaCiclo,
        })
        .select("id")
        .single();
      if (error && eGratis && /experiencia/i.test(error.message || "")) {
        setErro("Já usaste a tua sessão de experiência gratuita.");
        setAConfirmar(false);
        return;
      }
      if (error) {
        setErro("Esse horário acabou de ser reservado por outra pessoa. Escolhe outro.");
        await carregarOcupados(mentoraEscolhida.user_id);
        setHorario(null);
        setAConfirmar(false);
        return;
      }
      guardarTelefone(telemovel.trim());
      if (usaCiclo || eGratis) {
        setConfirmado(true);
        onConfirmar({ tipo: servicoEscolhido.tipo, titulo: servicoEscolhido.titulo, horario: horario.label, data: horario.chave });
        if (onUsouCredito) onUsouCredito();
        return;
      }
      const precoFinal = descontoValido ? precoComDesconto(servicoEscolhido.preco) : servicoEscolhido.preco;
      setEstadoPagamento("a_enviar");
      const resultado = await iniciarPagamentoMBWay("sessao", `${servicoEscolhido.titulo} — ${horario.label}`, precoFinal, telemovel.trim(), novaMarcacao?.id);
      setEstadoPagamento("a_confirmar");
      const pago = await aguardarConfirmacaoPagamento(resultado.pagamento_id);
      if (!pago) {
        setErro("O horário fica reservado durante 20 minutos. Se aprovares o pagamento na aplicação MB WAY nesse tempo, a marcação fica confirmada automaticamente e recebes a ligação por correio eletrónico.");
        setAConfirmar(false);
        return;
      }
      setConfirmado(true);
      onConfirmar({ tipo: servicoEscolhido.tipo, titulo: servicoEscolhido.titulo, horario: horario.label, data: horario.chave });
    } catch (e) {
      setErro(e.message || "Não foi possível confirmar. Tenta novamente.");
    } finally {
      setAConfirmar(false);
    }
  };

  if (confirmado) {
    return (
      <div className="pb-28">
        <SectionHeader eyebrow="MARCAR SESSÃO" title="Confirmado" onBack={onBack} />
        <div className="px-6">
          <div className="rounded-2xl px-5 py-6 flex flex-col items-center text-center" style={{ backgroundColor: palette.navy }}>
            <CheckCircle2 size={32} style={{ color: palette.gold }} />
            <p className="font-serif text-xl mt-3" style={{ color: palette.creamSoft }}>Sessão marcada!</p>
            <p className="text-sm mt-2" style={{ color: palette.goldSoft }}>
              {servicoEscolhido.titulo} com {mentoraEscolhida.nome || mentoraEscolhida.email}
            </p>
            <p className="text-sm mt-1" style={{ color: palette.goldSoft }}>{horario.label}</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="pb-28">
      <SectionHeader eyebrow="COACHING E MENTORIA · 30€" title="Marcar sessão" onBack={passo === 1 ? onBack : () => setPasso(passo - 1)} />

      <div className="px-6 mb-6 flex items-center gap-2">
        {[1, 2, 3].map((n) => (
          <div key={n} className="flex-1 h-1 rounded-full" style={{ backgroundColor: n <= passo ? palette.navy : `${palette.navy}22` }} />
        ))}
      </div>

      {passo === 1 && (
        <div className="px-6 mb-6 space-y-3">
          {Object.entries(creditos).filter(([, n]) => n > 0).map(([tipo, n]) => (
            <div key={tipo} className="rounded-2xl px-4 py-3" style={{ backgroundColor: palette.gold }}>
              <p className="text-sm font-medium" style={{ color: palette.navy }}>Tens {n} sess{n === 1 ? "ão" : "ões"} de {tipo} do teu ciclo por marcar.</p>
              <p className="text-[13px]" style={{ color: palette.navy }}>Escolhe {tipo} em baixo — não pagas nada.</p>
            </div>
          ))}
        </div>
      )}

      {passo === 1 && (
        <div className="px-6">
          <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>1. O QUE QUERES?</p>

          <div className="space-y-3">
            {servicosSessao.filter((s) => !(s.gratis && jaUsouExperiencia)).map((s) => (
              <button
                key={s.id}
                onClick={() => { setServicoEscolhido(s); setPasso(2); }}
                className="w-full text-left rounded-2xl px-5 py-4 transition active:scale-[0.98]"
                style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}
              >
                <div className="flex items-start justify-between gap-2">
                  <span className="inline-block text-[11px] tracking-[0.15em] font-medium px-2.5 py-1 rounded-full mb-2" style={{ backgroundColor: `${palette.gold}1F`, color: palette.gold }}>
                    {s.tipo.toUpperCase()}
                  </span>
                  <p className="font-serif text-lg shrink-0 text-right" style={{ color: palette.gold }}>{descontoAluno && !s.gratis ? <><span className="text-[13px] line-through mr-1" style={{ color: palette.navySoft }}>{s.preco}</span>{precoComDesconto(s.preco)}</> : s.preco}</p>
                </div>
                <p className="font-serif text-lg leading-snug" style={{ color: palette.navy }}>{s.titulo}</p>
                <p className="text-sm mt-1 leading-relaxed" style={{ color: palette.navySoft }}>{s.descricao}</p>
                <p className="text-[13px] mt-2" style={{ color: palette.navySoft }}>{s.duracao}</p>
              </button>
            ))}
          </div>
        </div>
      )}

      {passo === 2 && (
        <div className="px-6">
          <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>2. O PROFISSIONAL</p>
          {aCarregar ? (
            <p className="text-sm" style={{ color: palette.navySoft }}>A carregar…</p>
          ) : mentoras.length === 0 ? (
            <p className="text-sm" style={{ color: palette.navySoft }}>{area ? "O coach desta área ainda não tem horários. Volta em breve." : "Ainda não há profissionais com horários definidos."}</p>
          ) : (
            <div className="space-y-3">
              {mentoras.map((m) => (
                <button
                  key={m.user_id}
                  onClick={() => escolherMentora(m)}
                  className="w-full flex items-center gap-3 text-left rounded-2xl px-5 py-4 transition active:scale-[0.98]"
                  style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}
                >
                  <div className="w-11 h-11 rounded-full flex items-center justify-center shrink-0 font-serif text-base" style={{ backgroundColor: palette.navy, color: palette.creamSoft }}>
                    {(m.nome || m.email).slice(0, 1).toUpperCase()}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="font-serif text-lg leading-snug" style={{ color: palette.navy }}>{m.nome || m.email}</p>
                    {m.titulo && <p className="text-[13px] mt-0.5" style={{ color: palette.navySoft }}>{m.titulo}</p>}
                  </div>
                  <ChevronRight size={18} style={{ color: palette.navySoft }} />
                </button>
              ))}
            </div>
          )}
        </div>
      )}

      {passo === 3 && mentoraEscolhida && (
        <div className="px-6">
          <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>3. DIAS E HORAS LIVRES</p>
          {!horario ? (
            <div className="flex flex-wrap gap-2">
              {horariosLivres.length === 0 && (
                <p className="text-sm" style={{ color: palette.navySoft }}>
                  Não há horários livres neste momento. Fala connosco para combinar.
                </p>
              )}
              {horariosLivres.map((h) => (
                <button
                  key={h.chave}
                  onClick={() => setHorario(h)}
                  className="rounded-full px-3.5 py-2 text-[13px] font-medium transition active:scale-[0.97]"
                  style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}`, color: palette.navy }}
                >
                  {h.label}
                </button>
              ))}
            </div>
          ) : (
            <div className="space-y-3">
              <div className="rounded-2xl px-5 py-4" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
                <p className="text-[13px] mb-1" style={{ color: palette.navySoft }}>{servicoEscolhido.titulo} com {mentoraEscolhida.nome || mentoraEscolhida.email}</p>
                <p className="font-serif text-lg" style={{ color: palette.navy }}>{horario.label}</p>
                <button onClick={() => setHorario(null)} className="text-[13px] underline mt-1" style={{ color: palette.navySoft }}>Escolher outro horário</button>
              </div>
              <input
                type="text"
                value={nomeCompleto}
                onChange={(e) => setNomeCompleto(e.target.value)}
                placeholder="Nome completo"
                className="w-full rounded-xl px-4 py-2.5 text-sm outline-none"
                style={{ backgroundColor: palette.creamSoft, border: `1px solid ${palette.goldSoft}55`, color: palette.ink }}
              />
              <input
                type="tel"
                value={telemovel}
                onChange={(e) => setTelemovel(e.target.value)}
                placeholder={eGratis || usaCiclo ? "Número de telemóvel" : "Número de telemóvel (MB WAY)"}
                className="w-full rounded-xl px-4 py-2.5 text-sm outline-none"
                style={{ backgroundColor: palette.creamSoft, border: `1px solid ${palette.goldSoft}55`, color: palette.ink }}
              />
              {false && <input
                type="text"
                value={codigoDesconto}
                onChange={(e) => setCodigoDesconto(e.target.value)}
                placeholder="Código de desconto (opcional)"
                className="w-full rounded-xl px-4 py-2.5 text-sm outline-none"
                style={{ backgroundColor: palette.creamSoft, border: `1px solid ${palette.goldSoft}55`, color: palette.ink }}
              />}
              {descontoValido && (
                <p className="text-[13px] text-center" style={{ color: palette.gold }}>
                  {descontoAluno ? "Desconto de aluno 3S: 10% nesta sessão" : "Código aplicado: 10% de desconto"}
                </p>
              )}
              <label className="flex items-start gap-2.5 px-1">
                <input
                  type="checkbox"
                  checked={aceitouConsentimento}
                  onChange={(e) => setAceitouConsentimento(e.target.checked)}
                  className="mt-0.5 shrink-0"
                />
                <span className="text-[13px] leading-relaxed" style={{ color: palette.navySoft }}>{TEXTO_CONSENTIMENTO}</span>
              </label>
              {estadoPagamento === "a_confirmar" ? (
                <div className="text-center py-4">
                  <p className="text-sm font-medium mb-1" style={{ color: palette.navy }}>Confirma o pagamento no teu telemóvel</p>
                  <p className="text-[13px]" style={{ color: palette.navySoft }}>Abre a notificação da aplicação MB WAY e aprova — pode demorar até 90 segundos.</p>
                </div>
              ) : (
                <button
                  onClick={confirmarMarcacao}
                  disabled={aConfirmar || !telemovel.trim() || !nomeCompleto.trim() || !aceitouConsentimento}
                  className="w-full rounded-full py-3 font-medium text-sm tracking-wide disabled:opacity-60"
                  style={{ backgroundColor: palette.navy, color: palette.creamSoft }}
                >
                  {aConfirmar ? "A enviar pedido…" : usaCiclo ? `Confirmar · usar 1 sessão do ciclo (restam ${creditos[servicoEscolhido.tipo]})` : eGratis ? "Confirmar sessão gratuita" : `Confirmar e pagar · ${descontoValido ? precoComDesconto(servicoEscolhido.preco) : servicoEscolhido.preco}`}
                </button>
              )}
              {!aConfirmar && estadoPagamento !== "a_confirmar" && (!nomeCompleto.trim() || !telemovel.trim() || !aceitouConsentimento) && (
                <p className="text-[13px] text-center rounded-lg px-3 py-2" style={{ backgroundColor: `${palette.gold}1F`, color: palette.navy }}>
                  Para avançar, falta: {[!nomeCompleto.trim() && "o teu nome", !telemovel.trim() && "o número de telemóvel (MB WAY)", !aceitouConsentimento && "aceitar a caixa dos dados pessoais"].filter(Boolean).join(", ")}.
                </p>
              )}
              {erro && <p className="text-[13px] text-center" style={{ color: "#B23A3A" }}>{erro}</p>}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/* ---------------------------------------------------------
   Agenda — tudo o que o utilizador marcou
--------------------------------------------------------- */
function CalendarioMes({ eventosPorDia, mesAtual, setMesAtual, diaSelecionado, setDiaSelecionado }) {
  const ano = mesAtual.getFullYear();
  const mes = mesAtual.getMonth();
  const primeiroDia = new Date(ano, mes, 1);
  const ultimoDia = new Date(ano, mes + 1, 0);
  const offsetInicial = (primeiroDia.getDay() + 6) % 7; // semana começa em Segunda
  const diasNoMes = ultimoDia.getDate();

  const celulas = [];
  for (let i = 0; i < offsetInicial; i++) celulas.push(null);
  for (let d = 1; d <= diasNoMes; d++) celulas.push(d);

  const chaveDia = (d) => `${ano}-${String(mes + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
  const hoje = new Date();
  const hojeChave = `${hoje.getFullYear()}-${String(hoje.getMonth() + 1).padStart(2, "0")}-${String(hoje.getDate()).padStart(2, "0")}`;

  return (
    <div className="rounded-2xl px-4 py-4 mb-6" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
      <div className="flex items-center justify-between mb-4">
        <button onClick={() => setMesAtual(new Date(ano, mes - 1, 1))} className="p-1">
          <ChevronLeft size={18} style={{ color: palette.navySoft }} />
        </button>
        <p className="font-serif text-lg" style={{ color: palette.navy }}>
          {mesAtual.toLocaleDateString("pt-PT", { month: "long", year: "numeric" })}
        </p>
        <button onClick={() => setMesAtual(new Date(ano, mes + 1, 1))} className="p-1">
          <ChevronRight size={18} style={{ color: palette.navySoft }} />
        </button>
      </div>

      <div className="grid grid-cols-7 gap-1 mb-1.5">
        {["S", "T", "Q", "Q", "S", "S", "D"].map((d, i) => (
          <p key={i} className="text-center text-[11px] font-medium" style={{ color: palette.navySoft }}>{d}</p>
        ))}
      </div>

      <div className="grid grid-cols-7 gap-1">
        {celulas.map((d, i) => {
          if (d === null) return <div key={i} />;
          const chave = chaveDia(d);
          const temEvento = Boolean(eventosPorDia[chave]);
          const ehHoje = chave === hojeChave;
          const selecionado = chave === diaSelecionado;
          return (
            <button
              key={i}
              onClick={() => setDiaSelecionado(selecionado ? null : chave)}
              className="aspect-square rounded-full flex flex-col items-center justify-center relative"
              style={
                selecionado
                  ? { backgroundColor: palette.navy }
                  : ehHoje
                    ? { border: `1.4px solid ${palette.gold}` }
                    : {}
              }
            >
              <span className="text-[13px]" style={{ color: selecionado ? palette.creamSoft : palette.ink }}>{d}</span>
              {temEvento && (
                <span
                  className="w-1 h-1 rounded-full absolute bottom-1.5"
                  style={{ backgroundColor: selecionado ? palette.creamSoft : palette.gold }}
                />
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
}

function AgendaScreen({ inscricoesWorkshops, sessoesMarcadas }) {
  const [mesAtual, setMesAtual] = useState(new Date());
  const [diaSelecionado, setDiaSelecionado] = useState(null);

  const anoAtual = new Date().getFullYear();

  const workshopsInscritos = workshops.filter((w) => inscricoesWorkshops[w.id]);

  // Tenta reconstruir uma data (aaaa-mm-dd) a partir de "3 set"
  const dataWorkshop = (w) => {
    const partes = w.data.split(" ");
    const dia = parseInt(partes[0], 10);
    const idxMes = MESES_ABREV.indexOf(partes[1]);
    if (isNaN(dia) || idxMes === -1) return null;
    return `${anoAtual}-${String(idxMes + 1).padStart(2, "0")}-${String(dia).padStart(2, "0")}`;
  };

  const eventosPorDia = {};
  sessoesMarcadas.forEach((s) => {
    if (!s.data) return;
    const chave = s.data.slice(0, 10);
    (eventosPorDia[chave] = eventosPorDia[chave] || []).push({ tipo: "sessao", titulo: s.titulo, horario: s.horario });
  });
  workshopsInscritos.forEach((w) => {
    const chave = dataWorkshop(w);
    if (!chave) return;
    (eventosPorDia[chave] = eventosPorDia[chave] || []).push({ tipo: "workshop", titulo: w.titulo, horario: `${w.data} · ${w.hora}` });
  });

  const eventosDoDia = diaSelecionado ? eventosPorDia[diaSelecionado] || [] : null;
  const nada = workshopsInscritos.length === 0 && sessoesMarcadas.length === 0;

  return (
    <div className="pb-28">
      <SectionHeader eyebrow="O QUE TENS MARCADO" title="Agenda" />
      <div className="px-6">
        <MinhasSessoesMarcadas />
        <CalendarioMes
          eventosPorDia={eventosPorDia}
          mesAtual={mesAtual}
          setMesAtual={setMesAtual}
          diaSelecionado={diaSelecionado}
          setDiaSelecionado={setDiaSelecionado}
        />

        {diaSelecionado && (
          <div className="mb-7">
            <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>
              {(() => {
                const [ano, mes, dia] = diaSelecionado.split("-").map(Number);
                const data = new Date(ano, mes - 1, dia);
                const nomeDia = DIAS_SEMANA.find((d) => INDICE_DIA_SEMANA[d] === data.getDay());
                return `${nomeDia}, ${dia} ${MESES_ABREV[mes - 1]}`.toUpperCase();
              })()}
            </p>
            {eventosDoDia.length === 0 ? (
              <p className="text-sm" style={{ color: palette.navySoft }}>Nada marcado neste dia.</p>
            ) : (
              <div className="space-y-2">
                {eventosDoDia.map((e, i) => (
                  <div key={i} className="flex items-center gap-3 rounded-xl px-4 py-3" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
                    {e.tipo === "sessao" ? <PenLine size={16} style={{ color: palette.gold }} /> : <Calendar size={16} style={{ color: palette.gold }} />}
                    <div className="flex-1 min-w-0">
                      <p className="text-sm" style={{ color: palette.ink }}>{e.titulo}</p>
                      <p className="text-[13px]" style={{ color: palette.navySoft }}>{e.horario}</p>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {nada && !diaSelecionado && (
          <p className="text-sm" style={{ color: palette.navySoft }}>
            Ainda não tens formações nem sessões marcadas.
          </p>
        )}

        {!diaSelecionado && sessoesMarcadas.length > 0 && (
          <div className="mb-7">
            <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>SESSÕES</p>
            <div className="space-y-2">
              {sessoesMarcadas.map((s, i) => (
                <div key={i} className="flex items-center gap-3 rounded-xl px-4 py-3" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
                  <PenLine size={16} style={{ color: palette.gold }} />
                  <div className="flex-1 min-w-0">
                    <p className="text-sm" style={{ color: palette.ink }}>{s.titulo}</p>
                    <p className="text-[13px]" style={{ color: palette.navySoft }}>{s.horario}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {!diaSelecionado && workshopsInscritos.length > 0 && (
          <div>
            <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>FORMAÇÕES</p>
            <div className="space-y-2">
              {workshopsInscritos.map((w) => (
                <div key={w.id} className="flex items-center gap-3 rounded-xl px-4 py-3" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
                  <Calendar size={16} style={{ color: palette.gold }} />
                  <div className="flex-1 min-w-0">
                    <p className="text-sm" style={{ color: palette.ink }}>{w.titulo}</p>
                    <p className="text-[13px]" style={{ color: palette.navySoft }}>{w.data} · {w.hora}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

