function AgendaMentoraScreen({ onBack, linkVideochamada, onVista }) {
  const [marcacoes, setMarcacoes] = useState([]);
  const [linksPorId, setLinksPorId] = useState({});
  const [clientesPorId, setClientesPorId] = useState({});
  const [aCarregar, setACarregar] = useState(true);

  useEffect(() => {
    const carregar = async () => {
      setACarregar(true);
      const { data: sessaoAtual } = await supabase.auth.getSession();
      const userId = sessaoAtual?.session?.user?.id;
      if (!userId) { setACarregar(false); return; }

      const { data: rMarcacoes } = await supabase
        .from("marcacoes")
        .select("*")
        .eq("mentor_user_id", userId)
        .eq("estado", "confirmada")
        .order("horario", { ascending: true });

      const lista = rMarcacoes || [];
      setMarcacoes(lista);

      if (lista.length > 0) {
        const { data: rLinks } = await supabase.from("marcacoes_links").select("marcacao_id, link").in("marcacao_id", lista.map((m) => m.id));
        const mapaLinks = {};
        (rLinks || []).forEach((l) => { mapaLinks[l.marcacao_id] = l.link; });
        setLinksPorId(mapaLinks);
      }
      await supabase.from("notificacoes").update({ lida: true }).eq("destinatario_id", userId).eq("tipo", "marcacao").eq("lida", false);
      if (onVista) onVista();

      const idsClientes = Array.from(new Set(lista.map((m) => m.user_id)));
      if (idsClientes.length > 0) {
        const { data: rClientes } = await supabase
          .from("clientes")
          .select("user_id, nome, email, telefone")
          .in("user_id", idsClientes);
        const mapa = {};
        (rClientes || []).forEach((c) => { mapa[c.user_id] = c; });
        setClientesPorId(mapa);
      }
      setACarregar(false);
    };
    carregar();
  }, []);

  const agora = new Date();
  const proximas = marcacoes.filter((m) => !sessaoJaAcabou(m.horario));

  const porDia = {};
  proximas.forEach((m) => {
    const chaveDia = String(m.horario).slice(0, 10);
    if (!porDia[chaveDia]) porDia[chaveDia] = [];
    porDia[chaveDia].push(m);
  });
  const diasOrdenados = Object.keys(porDia).sort();

  const formatarDia = (chaveDia) => {
    const [ano, mes, dia] = chaveDia.split("-").map(Number);
    const dataObj = new Date(ano, mes - 1, dia);
    const nomeDia = DIAS_SEMANA.find((n) => INDICE_DIA_SEMANA[n] === dataObj.getDay());
    return `${nomeDia}, ${dia} ${MESES_ABREV[mes - 1]}`;
  };

  return (
    <div className="pb-28">
      <SectionHeader eyebrow="AS TUAS SESSÕES" title="A Minha Agenda" onBack={onBack} />

      <div className="px-6 mb-5">
        <p className="text-[13px] rounded-xl px-4 py-3" style={{ backgroundColor: `${palette.gold}1F`, color: palette.navy }}>
          Cada marcação tem uma ligação de videochamada criada automaticamente, que é também enviada por correio eletrónico ao cliente e a ti.
          {linkVideochamada ? " Estás a usar a tua ligação fixa (definida em Disponibilidade)." : ""}
        </p>
      </div>

      <div className="px-6">
        <EventosOnlineMentora />
        {aCarregar && <p className="text-sm" style={{ color: palette.navySoft }}>A carregar…</p>}
        {!aCarregar && diasOrdenados.length === 0 && (
          <p className="text-sm" style={{ color: palette.navySoft }}>Ainda não tens sessões marcadas.</p>
        )}

        {diasOrdenados.map((chaveDia) => (
          <div key={chaveDia} className="mb-6">
            <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>
              {formatarDia(chaveDia).toUpperCase()}
            </p>
            <div className="space-y-2">
              {porDia[chaveDia].map((m) => {
                const cliente = clientesPorId[m.user_id];
                const hora = String(m.horario).slice(11, 16);
                return (
                  <div key={m.id} className="rounded-xl px-4 py-3" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
                    <div className="flex items-center justify-between mb-1">
                      <p className="text-sm font-medium" style={{ color: palette.ink }}>{hora} · {m.titulo}</p>
                    </div>
                    <p className="text-[13px]" style={{ color: palette.ink }}>
                      {cliente?.nome || "Pessoa sem ficha"}
                    </p>
                    <p className="text-[13px]" style={{ color: palette.navySoft }}>
                      {cliente?.email || "sem correio eletrónico"}
                      {cliente?.telefone ? ` · ${cliente.telefone}` : ""}
                    </p>
                    <BotaoLinkSessao link={linksPorId[m.id] || linkVideochamada} />
                  </div>
                );
              })}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

const DIAS_SEMANA_CURTOS = [["Seg", 1], ["Ter", 2], ["Qua", 3], ["Qui", 4], ["Sex", 5], ["Sáb", 6], ["Dom", 0]];
const HORAS_POSSIVEIS = ["08:00", "09:00", "10:00", "11:00", "12:00", "13:00", "14:00", "15:00", "16:00", "17:00", "18:00", "19:00", "20:00", "21:00"];
function isoLocal(d) { return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`; }

function DisponibilidadeRapida({ disponibilidade, onDefinir }) {
  const hoje = new Date(); hoje.setHours(0, 0, 0, 0);
  const diasAtuais = (disponibilidade.dias || []).filter((d) => d >= isoLocal(hoje));
  const semanaInicial = [...new Set(diasAtuais.map((d) => { const [a, m, dd] = d.split("-").map(Number); return new Date(a, m - 1, dd).getDay(); }))];
  const [diasSemana, setDiasSemana] = useState(semanaInicial);
  const [horas, setHoras] = useState(disponibilidade.horas || []);
  const [semanas, setSemanas] = useState(8);
  const [excecoes, setExcecoes] = useState([]);
  const [msg, setMsg] = useState("");
  const alternar = (lista, setLista, v) => setLista(lista.includes(v) ? lista.filter((x) => x !== v) : [...lista, v]);
  const datasGeradas = [];
  for (let i = 0; i < semanas * 7; i++) {
    const d = new Date(hoje); d.setDate(hoje.getDate() + i);
    if (diasSemana.includes(d.getDay())) datasGeradas.push(isoLocal(d));
  }
  const datasFinais = datasGeradas.filter((d) => !excecoes.includes(d));
  const guardar = () => {
    onDefinir(datasFinais, [...horas].sort());
    setMsg(`Guardado: ${datasFinais.length} dias e ${horas.length} horários por dia.`);
  };
  const chip = (ativo) => ({ backgroundColor: ativo ? palette.navy : palette.card, color: ativo ? palette.creamSoft : palette.navy, border: `1px solid ${ativo ? palette.navy : palette.goldSoft + "88"}` });
  const rotulo = (t) => <p className="text-[11px] tracking-[0.2em] font-semibold mb-2" style={{ color: palette.gold }}>{t}</p>;
  return (
    <div className="rounded-2xl px-4 py-4 mb-8" style={{ backgroundColor: palette.card, border: `1.5px solid ${palette.gold}` }}>
      <p className="font-serif text-lg" style={{ color: palette.navy }}>Forma rápida</p>
      <p className="text-[13px] mb-4" style={{ color: palette.navySoft }}>Escolhe os dias da semana e as horas. A aplicação repete para as próximas semanas.</p>
      {rotulo("1. DIAS DA SEMANA")}
      <div className="grid grid-cols-7 gap-1.5 mb-4">
        {DIAS_SEMANA_CURTOS.map(([n, v]) => (
          <button key={v} onClick={() => alternar(diasSemana, setDiasSemana, v)} className="rounded-md py-2 text-[13px] font-semibold" style={chip(diasSemana.includes(v))}>{n}</button>
        ))}
      </div>
      {rotulo("2. HORAS")}
      <div className="grid grid-cols-4 gap-1.5 mb-4">
        {HORAS_POSSIVEIS.map((h) => (
          <button key={h} onClick={() => alternar(horas, setHoras, h)} className="rounded-md py-2 text-[13px] font-semibold" style={chip(horas.includes(h))}>{h}</button>
        ))}
      </div>
      {rotulo("3. DURANTE")}
      <div className="grid grid-cols-3 gap-1.5 mb-4">
        {[4, 8, 12].map((n) => (
          <button key={n} onClick={() => setSemanas(n)} className="rounded-md py-2 text-[13px] font-semibold" style={chip(semanas === n)}>{n} semanas</button>
        ))}
      </div>
      {datasGeradas.length > 0 && (
        <>
          {rotulo("4. DIAS EM QUE NÃO PODES (TOCA PARA TIRAR)")}
          <div className="flex flex-wrap gap-1.5 mb-4">
            {datasGeradas.map((d) => {
              const [a, m, dd] = d.split("-").map(Number);
              const fora = excecoes.includes(d);
              return (
                <button key={d} onClick={() => alternar(excecoes, setExcecoes, d)} className="rounded-md px-2 py-1 text-xs" style={{ backgroundColor: fora ? "transparent" : `${palette.gold}26`, color: palette.navy, border: `1px solid ${palette.goldSoft}88`, textDecoration: fora ? "line-through" : "none", opacity: fora ? 0.5 : 1 }}>
                  {dd}/{m}
                </button>
              );
            })}
          </div>
        </>
      )}
      <button onClick={guardar} disabled={!datasFinais.length || !horas.length} className="w-full rounded-full py-3 text-sm font-medium" style={{ backgroundColor: palette.navy, color: palette.creamSoft, opacity: !datasFinais.length || !horas.length ? 0.5 : 1 }}>
        Guardar disponibilidade
      </button>
      {msg && <p className="text-[13px] text-center mt-2" style={{ color: palette.navySoft }}>{msg}</p>}
    </div>
  );
}

function DisponibilidadeScreen({ onBack, disponibilidade, onAdicionarData, onRemoverData, onAdicionarHora, onRemoverHora, onGuardarLinkVideochamada, onDefinir }) {
  const [novaHora, setNovaHora] = useState("");
  const [novaData, setNovaData] = useState("");
  const [linkVideo, setLinkVideo] = useState(disponibilidade.linkVideochamada || "");

  const datasOrdenadas = [...disponibilidade.dias].sort();

  return (
    <div className="pb-28">
      <SectionHeader eyebrow="MARCAR SESSÃO" title="Disponibilidade" onBack={onBack} />
      <div className="px-6">
        <p className="text-sm mb-5" style={{ color: palette.navySoft }}>
          É isto que aparece a quem quiser marcar uma sessão contigo.
        </p>
        <DisponibilidadeRapida disponibilidade={disponibilidade} onDefinir={onDefinir} />

        <p className="text-[11px] tracking-[0.2em] font-medium mb-2" style={{ color: palette.gold }}>LIGAÇÃO DA VIDEOCHAMADA</p>
        <p className="text-[13px] mb-3" style={{ color: palette.navySoft }}>
          A tua ligação fixa (Google Meet, Zoom…) — aparece na tua Agenda, em cada sessão marcada contigo.
        </p>
        <div className="flex gap-2 mb-8">
          <input
            type="url"
            value={linkVideo}
            onChange={(e) => setLinkVideo(e.target.value)}
            placeholder="https://meet.google.com/xxx-xxxx-xxx"
            className="flex-1 rounded-xl px-4 py-2.5 text-sm outline-none"
            style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55`, color: palette.ink }}
          />
          <button
            onClick={() => onGuardarLinkVideochamada(linkVideo.trim())}
            className="rounded-xl px-4 py-2.5 text-sm font-medium tracking-wide"
            style={{ backgroundColor: palette.navy, color: palette.creamSoft }}
          >
            Guardar
          </button>
        </div>

        <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>OU AJUSTA DIA A DIA</p>
        <div className="flex flex-wrap gap-2 mb-4">
          {datasOrdenadas.length === 0 && (
            <p className="text-sm" style={{ color: palette.navySoft }}>Ainda não adicionaste nenhuma data.</p>
          )}
          {datasOrdenadas.map((d) => {
            const [ano, mes, dia] = d.split("-").map(Number);
            const dataObj = new Date(ano, mes - 1, dia);
            const nomeDia = DIAS_SEMANA.find((n) => INDICE_DIA_SEMANA[n] === dataObj.getDay());
            const label = `${nomeDia}, ${dia} ${MESES_ABREV[mes - 1]}`;
            return (
              <span
                key={d}
                className="flex items-center gap-2 rounded-full pl-3.5 pr-2 py-2 text-[13px] font-medium"
                style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55`, color: palette.navy }}
              >
                {label}
                <button
                  onClick={() => onRemoverData(d)}
                  className="w-4 h-4 rounded-full flex items-center justify-center"
                  style={{ backgroundColor: `${palette.gold}1F`, color: palette.gold }}
                >
                  ×
                </button>
              </span>
            );
          })}
        </div>
        <div className="flex gap-2 mb-8">
          <input
            type="date"
            value={novaData}
            onChange={(e) => setNovaData(e.target.value)}
            className="flex-1 rounded-xl px-4 py-2.5 text-sm outline-none"
            style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55`, color: palette.ink }}
          />
          <button
            onClick={() => {
              if (novaData) {
                onAdicionarData(novaData);
                setNovaData("");
              }
            }}
            className="rounded-xl px-4 py-2.5 text-sm font-medium tracking-wide"
            style={{ backgroundColor: palette.navy, color: palette.creamSoft }}
          >
            Adicionar
          </button>
        </div>

        <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>HORAS</p>
        <div className="flex flex-wrap gap-2 mb-4">
          {disponibilidade.horas.length === 0 && (
            <p className="text-sm" style={{ color: palette.navySoft }}>Ainda não adicionaste nenhuma hora.</p>
          )}
          {disponibilidade.horas.map((h) => (
            <span
              key={h}
              className="flex items-center gap-2 rounded-full pl-3.5 pr-2 py-2 text-[13px] font-medium"
              style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55`, color: palette.navy }}
            >
              {h}
              <button
                onClick={() => onRemoverHora(h)}
                className="w-4 h-4 rounded-full flex items-center justify-center"
                style={{ backgroundColor: `${palette.gold}1F`, color: palette.gold }}
              >
                ×
              </button>
            </span>
          ))}
        </div>

        <div className="flex gap-2">
          <select
            value={novaHora}
            onChange={(e) => setNovaHora(e.target.value)}
            className="flex-1 rounded-xl px-4 py-2.5 text-sm outline-none"
            style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55`, color: palette.ink }}
          >
            <option value="">Escolhe uma hora</option>
            {Array.from({ length: 14 }, (_, i) => {
              const totalMin = 8 * 60 + i * 60; // das 8:00 às 21:00, de 1 em 1 hora
              const h = String(Math.floor(totalMin / 60)).padStart(2, "0");
              const m = String(totalMin % 60).padStart(2, "0");
              const valor = `${h}:${m}`;
              return <option key={valor} value={valor}>{valor}</option>;
            })}
          </select>
          <button
            onClick={() => {
              if (novaHora) {
                onAdicionarHora(novaHora);
                setNovaHora("");
              }
            }}
            className="rounded-xl px-4 py-2.5 text-sm font-medium tracking-wide"
            style={{ backgroundColor: palette.navy, color: palette.creamSoft }}
          >
            Adicionar
          </button>
        </div>

        {disponibilidade.dias.length > 0 && disponibilidade.horas.length > 0 && (
          <div className="mt-8">
            <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>SESSÕES QUE VÃO FICAR DISPONÍVEIS</p>
            <p className="text-[13px] mb-3" style={{ color: palette.navySoft }}>
              Cada data que adicionaste, com cada hora que escolheste — 1 hora por sessão.
            </p>
            <div className="space-y-2">
              {gerarHorariosComData(disponibilidade.dias, disponibilidade.horas)
                .map((h) => (
                  <div key={h.chave} className="rounded-xl px-4 py-2.5 text-sm" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55`, color: palette.ink }}>
                    {h.label}
                  </div>
                ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

