function NotificacoesScreen({ onBack }) {
  const [notificacoes, setNotificacoes] = useState([]);
  const [aCarregar, setACarregar] = useState(true);

  const ICONE_POR_TIPO = {
    marcacao: Calendar,
    mensagem: Mail,
    pedido_mentora: Users,
    entrada_gratis: Users,
  };

  const carregar = async () => {
    setACarregar(true);
    const { data: sessaoAtual } = await supabase.auth.getSession();
    const userId = sessaoAtual?.session?.user?.id;
    if (!userId) { setACarregar(false); return; }
    const { data } = await supabase
      .from("notificacoes")
      .select("*")
      .eq("destinatario_id", userId)
      .order("criado_em", { ascending: false })
      .limit(50);
    setNotificacoes(data || []);
    setACarregar(false);

    const idsNaoLidas = (data || []).filter((n) => !n.lida).map((n) => n.id);
    if (idsNaoLidas.length > 0) {
      await supabase.from("notificacoes").update({ lida: true }).in("id", idsNaoLidas);
    }
  };

  useEffect(() => { carregar(); }, []);

  return (
    <div className="pb-28">
      <SectionHeader eyebrow="ATIVIDADE RECENTE" title="Notificações" onBack={onBack} />
      <div className="px-6 space-y-2">
        {aCarregar && <p className="text-sm" style={{ color: palette.navySoft }}>A carregar…</p>}
        {!aCarregar && notificacoes.length === 0 && (
          <p className="text-sm" style={{ color: palette.navySoft }}>Ainda não tens notificações.</p>
        )}
        {notificacoes.map((n) => {
          const Icon = ICONE_POR_TIPO[n.tipo] || Bell;
          return (
            <div
              key={n.id}
              className="rounded-xl px-4 py-3 flex items-start gap-3"
              style={{ backgroundColor: n.lida ? palette.creamSoft : palette.card, border: `1px solid ${palette.goldSoft}55` }}
            >
              <div className="w-8 h-8 rounded-full flex items-center justify-center shrink-0" style={{ backgroundColor: `${palette.gold}1F` }}>
                <Icon size={14} style={{ color: palette.gold }} />
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium" style={{ color: palette.ink }}>{n.titulo}</p>
                {n.detalhe && <p className="text-[13px] mt-0.5" style={{ color: palette.navySoft }}>{n.detalhe}</p>}
                <p className="text-[11px] mt-1" style={{ color: palette.goldSoft }}>
                  {new Date(n.criado_em).toLocaleString("pt-PT", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" })}
                </p>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function NotificacoesSino({ onAbrir, papel }) {
  const [contagem, setContagem] = useState(0);

  const atualizarContagem = async () => {
    const { data: sessaoAtual } = await supabase.auth.getSession();
    const userId = sessaoAtual?.session?.user?.id;
    if (!userId) return;
    const { count } = await supabase
      .from("notificacoes")
      .select("id", { count: "exact", head: true })
      .eq("destinatario_id", userId)
      .eq("lida", false);
    setContagem(count || 0);
  };

  useEffect(() => {
    if (papel !== "dona" && papel !== "mentora") return;
    atualizarContagem();
    const intervalo = setInterval(atualizarContagem, 30000);
    return () => clearInterval(intervalo);
  }, [papel]);

  if (papel !== "dona" && papel !== "mentora") return null;

  return (
    <button
      onClick={() => { onAbrir(); atualizarContagem(); }}
      className="fixed z-20 flex items-center justify-center w-10 h-10 rounded-full shadow-md"
      style={{ top: 16, right: "calc(50% - 224px + 16px)", backgroundColor: palette.navy }}
    >
      <Bell size={17} style={{ color: palette.creamSoft }} />
      {contagem > 0 && (
        <span
          className="absolute -top-1 -right-1 flex items-center justify-center rounded-full text-[11px] font-bold"
          style={{ width: 18, height: 18, backgroundColor: palette.gold, color: palette.navy }}
        >
          {contagem > 9 ? "9+" : contagem}
        </span>
      )}
    </button>
  );
}

