/* ---------- Códigos de oferta e ciclos de sessões ---------- */
const PRECO_SESSAO = 30;
const SESSOES_POR_CICLO = 4;

function ResgatarCodigo({ onAtivado, titulo }) {
  const [codigo, setCodigo] = useState("");
  const [estado, setEstado] = useState(null);
  const [mensagem, setMensagem] = useState("");
  const ativar = async () => {
    if (!codigo.trim()) return;
    setEstado("a_ativar");
    setMensagem("");
    const { data, error } = await supabase.rpc("resgatar_codigo", { p_codigo: codigo.trim() });
    if (error || !data) { setEstado("erro"); setMensagem("Não foi possível ativar o código. Tenta novamente."); return; }
    setEstado(data.ok ? "ok" : "erro");
    let msg = data.mensagem;
    if (data.ok) {
      const partes = [];
      if (Number(data.desconto_ciclo) > 0) partes.push(`${Number(data.desconto_ciclo)}% de desconto no ciclo de 4 sessões`);
      if (partes.length) msg += " Tens: " + partes.join(" e ") + ".";
      if (onAtivado) onAtivado(data);
    }
    setMensagem(msg);
  };
  return (
    <div className="rounded-2xl px-4 py-4" style={{ backgroundColor: palette.card, border: `1px dashed ${palette.gold}` }}>
      <p className="text-sm font-medium mb-2" style={{ color: palette.navy }}>{titulo || "Tens um código de oferta?"}</p>
      <div className="flex gap-2">
        <input
          type="text"
          value={codigo}
          onChange={(e) => setCodigo(e.target.value.toUpperCase())}
          placeholder="Ex.: WHATSAPP3S"
          className="flex-1 min-w-0 rounded-xl px-3 py-2.5 text-sm outline-none"
          style={{ backgroundColor: palette.creamSoft, border: `1px solid ${palette.goldSoft}55`, color: palette.ink }}
        />
        <button onClick={ativar} disabled={estado === "a_ativar"} className="rounded-xl px-4 text-sm font-medium disabled:opacity-60" style={{ backgroundColor: palette.navy, color: palette.creamSoft }}>
          {estado === "a_ativar" ? "…" : "Ativar"}
        </button>
      </div>
      {mensagem && <p className="text-[13px] mt-2" style={{ color: estado === "ok" ? palette.gold : "#B23A3A" }}>{mensagem}</p>}
    </div>
  );
}

/* ---------- Carrinho e pagamentos (MB WAY, Multibanco, Payshop) ---------- */
const CarrinhoContext = createContext({ itens: [], adicionar: () => {}, remover: () => {}, limpar: () => {}, abrir: () => {} });

function precoNumero(texto) {
  const v = parseFloat(String(texto || "").replace("€", "").replace(",", ".").trim());
  return isNaN(v) ? null : v;
}
function precoTexto(v) {
  return `${Number(v).toFixed(2).replace(".", ",")}€`;
}
const comunidadeEmDia = (p) => Boolean(p?.comunidadePagaAte && new Date(p.comunidadePagaAte) > new Date());

async function criarPagamento(tipo, valor, descricao, telemovel, itens) {
  const { data: sessaoAtual } = await supabase.auth.getSession();
  const token = sessaoAtual?.session?.access_token;
  if (!token) throw new Error("Sessão inválida — entra na aplicação de novo.");
  const resp = await fetch("https://hspekqrhttxeckghtryi.supabase.co/functions/v1/criar-pagamento", {
    method: "POST",
    headers: { "Content-Type": "application/json", "Authorization": `Bearer ${token}` },
    body: JSON.stringify({ tipo, valor: Number(valor.toFixed(2)), descricao, telemovel: telemovel || "", itens }),
  });
  const data = await resp.json();
  if (!resp.ok || data.erro) throw new Error(data.erro || "Não foi possível iniciar o pagamento.");
  return data;
}

const visualizacoesRegistadas = new Set();
async function registarVisualizacao(curso, indice, aula) {
  const chave = `${curso.id}-${indice}`;
  if (visualizacoesRegistadas.has(chave)) return;
  visualizacoesRegistadas.add(chave);
  try {
    const { data } = await supabase.auth.getSession();
    const uid = data?.session?.user?.id;
    if (!uid) return;
    await supabase.from("visualizacoes_aulas").insert({
      user_id: uid, curso_id: curso.id, curso_titulo: curso.titulo, aula_numero: indice + 1, aula_titulo: aula.titulo,
    });
  } catch (e) {}
}

