                {livre ? (c.gratis && !temTudo ? <span className="text-[11px] font-semibold" style={{ color: palette.gold }}>GRÁTIS</span> : <ChevronRight size={16} style={{ color: palette.navySoft }} />) : <Lock size={14} style={{ color: palette.navySoft }} />}
