/* ---------- Sessões com link e avisos visíveis ---------- */
function formatarHorarioSessao(horario) {
  const d = new Date(String(horario).replace(" ", "T"));
  if (isNaN(d)) return horario;
  const hoje = new Date();
  const amanha = new Date(); amanha.setDate(hoje.getDate() + 1);
  const mesmoDia = (a, b) => a.toDateString() === b.toDateString();
  const hora = d.toLocaleTimeString("pt-PT", { hour: "2-digit", minute: "2-digit" });
  if (mesmoDia(d, hoje)) return `Hoje às ${hora}`;
  if (mesmoDia(d, amanha)) return `Amanhã às ${hora}`;
  return `${d.toLocaleDateString("pt-PT", { weekday: "long", day: "numeric", month: "long" })} às ${hora}`;
}

function dataSessao(horario) {
  return new Date(String(horario).replace(" ", "T"));
}
const sessaoJaAcabou = (horario, minutos = 60) => dataSessao(horario).getTime() + minutos * 60000 < Date.now();

function EventosOnlineMentora({ compacto }) {
  const [eventos, setEventos] = useState([]);
  useEffect(() => {
    (async () => {
      const { data } = await supabase.from("eventos_online").select("*").gte("inicio", new Date(Date.now() - 4 * 3600e3).toISOString()).order("inicio", { ascending: true });
      const ativos = (data || []).filter((e) => new Date(e.inicio).getTime() + (e.duracao_min || 90) * 60000 > Date.now());
      const comContagem = await Promise.all(ativos.map(async (e) => {
        const { count } = await supabase.from("inscricoes_evento").select("id", { count: "exact", head: true }).eq("evento_chave", e.chave);
        return { ...e, inscritos: count || 0 };
      }));
      setEventos(compacto ? comContagem.slice(0, 1) : comContagem);
    })();
  }, []);
  if (eventos.length === 0) return null;
  return (
    <div className={compacto ? "" : "mb-6"}>
      {!compacto && <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>EVENTOS À DISTÂNCIA</p>}
      <div className="space-y-2">
        {eventos.map((e) => (
          <div key={e.id} className="rounded-2xl px-4 py-4" style={{ backgroundColor: palette.navy }}>
            {compacto && <p className="text-[11px] tracking-[0.2em] font-medium" style={{ color: palette.gold }}>PRÓXIMO EVENTO À DISTÂNCIA</p>}
            <p className="font-serif text-lg mt-1 leading-snug" style={{ color: palette.creamSoft }}>{e.titulo}</p>
            <p className="text-[13px] mt-0.5" style={{ color: palette.goldSoft }}>
              {formatarHorarioSessao(new Date(e.inicio).toISOString())} · {e.inscritos} inscrito{e.inscritos === 1 ? "" : "s"}
            </p>
            <BotaoLinkSessao link={e.link} />
          </div>
        ))}
      </div>
    </div>
  );
}

function BotaoLinkSessao({ link }) {
  const [copiado, setCopiado] = useState(false);
  if (!link) return null;
  return (
    <div className="flex gap-2 mt-2">
      <a href={link} target="_blank" rel="noopener noreferrer" className="flex-1 flex items-center justify-center rounded-lg py-2 text-xs font-medium tracking-wide" style={{ backgroundColor: palette.navy, color: palette.creamSoft }}>
        Entrar na videochamada
      </a>
      <button
        onClick={() => { try { navigator.clipboard.writeText(link); setCopiado(true); setTimeout(() => setCopiado(false), 2000); } catch (e) {} }}
        className="rounded-lg px-3 py-2 text-[13px] font-medium"
        style={{ backgroundColor: palette.creamSoft, color: palette.navy, border: `1px solid ${palette.goldSoft}55` }}
      >
        {copiado ? "Copiado ✓" : "Copiar ligação"}
      </button>
    </div>
  );
}

function MinhasSessoesMarcadas() {
  const [sessoes, setSessoes] = useState([]);
  useEffect(() => {
    (async () => {
      const { data: s } = await supabase.auth.getSession();
      const uid = s?.session?.user?.id;
      if (!uid) return;
      const hojeTxt = new Date().toISOString().slice(0, 10);
      const { data: ms } = await supabase.from("marcacoes").select("id, titulo, horario").eq("user_id", uid).eq("estado", "confirmada").gte("horario", hojeTxt).order("horario", { ascending: true });
      const lista = ms || [];
      if (lista.length === 0) { setSessoes([]); return; }
      const { data: ls } = await supabase.from("marcacoes_links").select("marcacao_id, link").in("marcacao_id", lista.map((m) => m.id));
      const mapa = {};
      (ls || []).forEach((l) => { mapa[l.marcacao_id] = l.link; });
      setSessoes(lista.filter((m) => !sessaoJaAcabou(m.horario)).map((m) => ({ ...m, link: mapa[m.id] })));
    })();
  }, []);
  if (sessoes.length === 0) return null;
  return (
    <div className="mb-6">
      <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>AS TUAS SESSÕES</p>
      <div className="space-y-2">
        {sessoes.map((m) => (
          <div key={m.id} className="rounded-xl px-4 py-3" style={{ backgroundColor: palette.card, border: `1px solid ${palette.gold}` }}>
            <p className="text-sm font-medium" style={{ color: palette.navy }}>{m.titulo}</p>
            <p className="text-[13px]" style={{ color: palette.navySoft }}>{formatarHorarioSessao(m.horario)}</p>
            <BotaoLinkSessao link={m.link} />
          </div>
        ))}
      </div>
    </div>
  );
}

/* ---------- Janela com as marcações do dia (dona e mentoras) ---------- */
function PopupMarcacoesDoDia({ papel }) {
  const [sessoes, setSessoes] = useState(null);
  const [amanha, setAmanha] = useState(0);
  const [aberto, setAberto] = useState(false);
  useEffect(() => {
    (async () => {
      const { data: s } = await supabase.auth.getSession();
      const uid = s?.session?.user?.id;
      if (!uid) return;
      const d = (offset) => {
        const x = new Date(); x.setDate(x.getDate() + offset);
        return `${x.getFullYear()}-${String(x.getMonth() + 1).padStart(2, "0")}-${String(x.getDate()).padStart(2, "0")}`;
      };
      const hoje = d(0), depois = d(1);
      const chave = `escola3s:popup-marcacoes:${uid}:${hoje}`;
      try { if (window.localStorage.getItem(chave)) return; } catch (e) {}
      let q = supabase.from("marcacoes").select("id, titulo, horario, user_id").eq("estado", "confirmada").gte("horario", hoje).lt("horario", d(2)).order("horario", { ascending: true });
      if (papel !== "dona") q = q.eq("mentor_user_id", uid);
      const { data: ms } = await q;
      const lista = ms || [];
      const deHoje = lista.filter((m) => String(m.horario).startsWith(hoje) && !sessaoJaAcabou(m.horario));
      const deAmanha = lista.filter((m) => String(m.horario).startsWith(depois)).length;
      if (deHoje.length === 0 && deAmanha === 0) return;
      const ids = deHoje.map((m) => m.id);
      const uids = [...new Set(deHoje.map((m) => m.user_id))];
      const [{ data: ls }, { data: cs }] = await Promise.all([
        ids.length ? supabase.from("marcacoes_links").select("marcacao_id, link").in("marcacao_id", ids) : Promise.resolve({ data: [] }),
        uids.length ? supabase.from("clientes").select("user_id, nome, email, telefone").in("user_id", uids) : Promise.resolve({ data: [] }),
      ]);
      setSessoes(deHoje.map((m) => {
        const c = (cs || []).find((x) => x.user_id === m.user_id);
        return { ...m, link: (ls || []).find((l) => l.marcacao_id === m.id)?.link, cliente: c?.nome || c?.email || "", telefone: c?.telefone || "" };
      }));
      setAmanha(deAmanha);
      setAberto(true);
      try { window.localStorage.setItem(chave, "1"); } catch (e) {}
    })();
  }, [papel]);
  if (!aberto || !sessoes) return null;
  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center" style={{ backgroundColor: "rgba(20,30,55,0.55)" }} onClick={() => setAberto(false)}>
      <div className="w-full max-w-md rounded-t-3xl sm:rounded-3xl px-5 pt-6 pb-8 max-h-[85vh] overflow-y-auto" style={{ backgroundColor: palette.creamSoft }} onClick={(e) => e.stopPropagation()}>
        <p className="text-[11px] tracking-[0.25em] font-medium" style={{ color: palette.gold }}>AS TUAS SESSÕES</p>
        <p className="font-serif text-2xl mt-1" style={{ color: palette.navy }}>
          {sessoes.length > 0 ? `Hoje tens ${sessoes.length} sess${sessoes.length === 1 ? "ão" : "ões"}` : "Hoje não tens sessões"}
        </p>
        <div className="mt-4 space-y-3">
          {sessoes.map((m) => (
            <div key={m.id} className="rounded-2xl px-4 py-3" style={{ backgroundColor: palette.card, border: `1px solid ${palette.gold}` }}>
              <p className="font-serif text-lg" style={{ color: palette.navy }}>{String(m.horario).slice(11, 16)} · {m.titulo}</p>
              {m.cliente && <p className="text-[13px]" style={{ color: palette.navySoft }}>{m.cliente}{m.telefone ? ` · ${m.telefone}` : ""}</p>}
              <BotaoLinkSessao link={m.link} />
            </div>
          ))}
        </div>
        {amanha > 0 && (
          <p className="text-sm mt-4 rounded-xl px-4 py-3" style={{ backgroundColor: `${palette.gold}1F`, color: palette.navy }}>
            Amanhã tens {amanha} sess{amanha === 1 ? "ão" : "ões"} marcada{amanha === 1 ? "" : "s"}.
          </p>
        )}
        <button onClick={() => setAberto(false)} className="w-full rounded-full py-3 mt-5 text-sm font-medium" style={{ backgroundColor: palette.navy, color: palette.creamSoft }}>
          Fechar
        </button>
      </div>
    </div>
  );
}

function AvisosMentoraInicio({ naoLidas, onVerAgenda, onVerNotificacoes }) {
  const [proxima, setProxima] = useState(null);
  useEffect(() => {
    (async () => {
      const { data: s } = await supabase.auth.getSession();
      const uid = s?.session?.user?.id;
      if (!uid) return;
      const agoraTxt = new Date(Date.now() - 60 * 60 * 1000).toISOString().slice(0, 16).replace("T", " ");
      const { data: ms } = await supabase.from("marcacoes").select("id, titulo, horario, user_id").eq("mentor_user_id", uid).eq("estado", "confirmada").gte("horario", agoraTxt).order("horario", { ascending: true }).limit(3);
      const m = ms && ms.find((x) => !sessaoJaAcabou(x.horario));
      if (!m) { setProxima(null); return; }
      const [{ data: l }, { data: c }] = await Promise.all([
        supabase.from("marcacoes_links").select("link").eq("marcacao_id", m.id).maybeSingle(),
        supabase.from("clientes").select("nome, correio eletrónico").eq("user_id", m.user_id).maybeSingle(),
      ]);
      setProxima({ ...m, link: l?.link, cliente: c?.nome || c?.email || "" });
    })();
  }, [naoLidas]);
  return (
    <div className="px-6 mb-6 space-y-3">
      {naoLidas > 0 && (
        <button onClick={onVerNotificacoes} className="w-full flex items-center gap-3 rounded-2xl px-4 py-4 text-left" style={{ backgroundColor: palette.gold }}>
          <span className="w-10 h-10 rounded-full flex items-center justify-center shrink-0" style={{ backgroundColor: palette.navy }}>
            <Bell size={18} style={{ color: palette.gold }} />
          </span>
          <div className="flex-1">
            <p className="font-serif text-lg leading-tight" style={{ color: palette.navy }}>{naoLidas === 1 ? "Tens 1 novidade" : `Tens ${naoLidas} novidades`}</p>
            <p className="text-[13px]" style={{ color: palette.navy }}>Novas marcações e avisos — toca para ver</p>
          </div>
          <ChevronRight size={18} style={{ color: palette.navy }} />
        </button>
      )}
      {proxima && (
        <div className="rounded-2xl px-4 py-4" style={{ backgroundColor: palette.navy }}>
          <p className="text-[11px] tracking-[0.2em] font-medium" style={{ color: palette.gold }}>PRÓXIMA SESSÃO</p>
          <p className="font-serif text-lg mt-1" style={{ color: palette.creamSoft }}>{formatarHorarioSessao(proxima.horario)}</p>
          <p className="text-[13px] mt-0.5" style={{ color: palette.goldSoft }}>{proxima.titulo}{proxima.cliente ? ` · ${proxima.cliente}` : ""}</p>
          <BotaoLinkSessao link={proxima.link} />
          <button onClick={onVerAgenda} className="text-[13px] underline underline-offset-2 mt-2" style={{ color: palette.goldSoft }}>Ver a agenda toda</button>
        </div>
      )}
      <EventosOnlineMentora compacto />
    </div>
  );
}

/* ---------- Arquivo da Escola (só a dona) ---------- */
const TEXTO_CONSENTIMENTO_GERAL = "Aceito que a Escola 3S guarde e utilize os meus dados pessoais (correio eletrónico e, sempre que os partilhar, nome, telemóvel e outra informação fornecida nos formulários da aplicação) para gerir a minha conta e o meu percurso na escola.";

function ConsentimentoGate({ session, onAceite }) {
  const [aceitou, setAceitou] = useState(false);
  const [aGuardar, setAGuardar] = useState(false);
  const [erro, setErro] = useState("");
  const guardar = async () => {
    setAGuardar(true);
    setErro("");
    const { error } = await supabase
      .from("consentimentos_dados")
      .insert({ user_id: session.user.id, email: session.user.email, texto_aceite: TEXTO_CONSENTIMENTO_GERAL });
    setAGuardar(false);
    if (error) { setErro("Não foi possível guardar. Tenta novamente."); return; }
    onAceite();
  };
  return (
    <div className="min-h-screen w-full flex justify-center" style={{ backgroundColor: palette.cream, fontFamily: "Inter, sans-serif" }}>
      <div className="w-full max-w-md px-6 pt-16" style={{ backgroundColor: palette.creamSoft }}>
        <p className="text-[11px] tracking-[0.25em] font-medium mb-2" style={{ color: palette.gold }}>PROTEÇÃO DE DADOS</p>
        <h1 className="font-serif text-2xl leading-tight mb-4" style={{ color: palette.navy }}>Antes de continuares</h1>
        <p className="text-sm leading-relaxed mb-5" style={{ color: palette.ink }}>
          Para cumprir o Regulamento Geral de Proteção de Dados (RGPD), precisamos da tua autorização para guardar os teus dados na Escola 3S.
        </p>
        <label className="flex items-start gap-2.5 rounded-2xl px-4 py-4 mb-5" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
          <input type="checkbox" checked={aceitou} onChange={(e) => setAceitou(e.target.checked)} className="mt-0.5 shrink-0" />
          <span className="text-[13px] leading-relaxed" style={{ color: palette.navySoft }}>{TEXTO_CONSENTIMENTO_GERAL}</span>
        </label>
        {erro && <p className="text-[13px] mb-3" style={{ color: "#A33" }}>{erro}</p>}
        <button
          onClick={guardar}
          disabled={!aceitou || aGuardar}
          className="w-full rounded-full py-3.5 font-medium text-sm disabled:opacity-60"
          style={{ backgroundColor: palette.navy, color: palette.creamSoft }}
        >
          {aGuardar ? "A guardar…" : "Aceito e continuar"}
        </button>
        <button onClick={() => supabase.auth.signOut()} className="w-full text-[13px] mt-4 py-2" style={{ color: palette.navySoft }}>
          Não aceito — sair
        </button>
      </div>
    </div>
  );
}

const ARQUIVO_PASTAS = [
  { id: "autorizacoes", nome: "Autorizações (RGPD)" },
  { id: "fichas", nome: "Fichas de clientes" },
  { id: "inscricoes", nome: "Inscrições" },
  { id: "outros", nome: "Outros" },
];

function arquivoData(d) {
  if (!d) return "—";
  return new Date(d).toLocaleDateString("pt-PT", { day: "2-digit", month: "short", year: "numeric" });
}

function exportarCSV(nomeFicheiro, cabecalho, linhas) {
  const esc = (v) => `"${String(v ?? "").replace(/"/g, '""')}"`;
  const texto = "\uFEFF" + [cabecalho, ...linhas].map((l) => l.map(esc).join(";")).join("\n");
  const blob = new Blob([texto], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = nomeFicheiro;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

function numeroWhatsApp(tel) {
  let n = String(tel || "").replace(/\D/g, "");
  if (n.startsWith("00")) n = n.slice(2);
  if (n.length === 9) n = "351" + n;
  return n.length >= 11 ? n : "";
}
function mensagemEvento(nome, ev) {
  const primeiro = String(nome || "").trim().split(" ")[0];
  const quando = new Date(ev.inicio).toLocaleDateString("pt-PT", { weekday: "long", day: "numeric", month: "long" }) + " às " + new Date(ev.inicio).toLocaleTimeString("pt-PT", { hour: "2-digit", minute: "2-digit" });
  return `Olá${primeiro ? " " + primeiro : ""}! 😊 Obrigada pela tua inscrição no ${ev.titulo}.\n\n📅 ${quando}\n🔗 Ligação para entrar: ${ev.link}\n\nAté já!\nConceição Alves · Escola 3S`;
}

function ArquivoCartao({ titulo, linhas }) {
  return (
    <div className="rounded-2xl px-4 py-3.5" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
      <p className="font-serif text-base leading-snug" style={{ color: palette.navy }}>{titulo}</p>
      {linhas.filter(Boolean).map((l, i) => (
        <p key={i} className="text-[13px] leading-relaxed mt-0.5 break-words" style={{ color: palette.navySoft }}>{l}</p>
      ))}
    </div>
  );
}

function ArquivoEscolaScreen({ onBack }) {
  const [tab, setTab] = useState("autorizacoes");
  const [carregando, setCarregando] = useState(true);
  const [consentimentos, setConsentimentos] = useState([]);
  const [clientes, setClientes] = useState([]);
  const [inscricoesEvento, setInscricoesEvento] = useState([]);
  const [progressos, setProgressos] = useState([]);
  const [pagamentos, setPagamentos] = useState([]);
  const [visualizacoes, setVisualizacoes] = useState([]);
  const [eventosOnline, setEventosOnline] = useState([]);
  const [codigosUsados, setCodigosUsados] = useState([]);
  const [pasta, setPasta] = useState("autorizacoes");
  const [ficheiros, setFicheiros] = useState([]);
  const [aCarregarFicheiro, setACarregarFicheiro] = useState(false);
  const [mensagem, setMensagem] = useState("");
  const [pesquisa, setPesquisa] = useState("");

  useEffect(() => {
    (async () => {
      setCarregando(true);
      const [rC, rCl, rI, rP, rPg, rV] = await Promise.all([
        supabase.from("consentimentos_dados").select("*").order("aceite_em", { ascending: false }),
        supabase.from("clientes").select("*").order("criado_em", { ascending: false }),
        supabase.from("inscricoes_evento").select("*").order("criado_em", { ascending: false }),
        supabase.from("user_progress").select("user_id, data"),
        supabase.from("pagamentos").select("*").order("criado_em", { ascending: false }),
        supabase.from("visualizacoes_aulas").select("*").order("visto_em", { ascending: false }),
      ]);
      setVisualizacoes(rV.data || []);
      const rE = await supabase.from("eventos_online").select("*").order("inicio", { ascending: true });
      setEventosOnline(rE.data || []);
      const rCod = await supabase.from("codigos_resgatados").select("*").order("resgatado_em", { ascending: false });
      setCodigosUsados(rCod.data || []);
      setConsentimentos(rC.data || []);
      setClientes(rCl.data || []);
      setInscricoesEvento(rI.data || []);
      setProgressos(rP.data || []);
      setPagamentos(rPg.data || []);
      setCarregando(false);
    })();
  }, []);

  const carregarFicheiros = async (p) => {
    const { data } = await supabase.storage.from("arquivo").list(p, { limit: 200, sortBy: { column: "created_at", order: "desc" } });
    setFicheiros((data || []).filter((f) => f.name && f.name !== ".emptyFolderPlaceholder"));
  };

  useEffect(() => {
    if (tab === "documentos") carregarFicheiros(pasta);
  }, [tab, pasta]);

  const pessoa = (userId) => {
    const c = clientes.find((x) => x.user_id === userId);
    return { nome: c?.nome || "", email: c?.email || "", telefone: c?.telefone || "" };
  };

  const filtro = (texto) => !pesquisa.trim() || String(texto).toLowerCase().includes(pesquisa.trim().toLowerCase());

  const carregarFicheiro = async (e) => {
    const f = e.target.files && e.target.files[0];
    e.target.value = "";
    if (!f) return;
    if (f.size > 20 * 1024 * 1024) { setMensagem("O ficheiro tem mais de 20 MB."); return; }
    setACarregarFicheiro(true);
    setMensagem("");
    const nomeSeguro = f.name.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-zA-Z0-9._-]/g, "_");
    const { error } = await supabase.storage.from("arquivo").upload(`${pasta}/${Date.now()}-${nomeSeguro}`, f, { upsert: false });
    setACarregarFicheiro(false);
    if (error) { setMensagem("Não foi possível carregar o ficheiro."); return; }
    setMensagem("Ficheiro guardado.");
    carregarFicheiros(pasta);
  };

  const abrirFicheiro = async (nome) => {
    const { data } = await supabase.storage.from("arquivo").createSignedUrl(`${pasta}/${nome}`, 300);
    if (data?.signedUrl) window.open(data.signedUrl, "_blank");
  };

  const apagarFicheiro = async (nome) => {
    if (!window.confirm("Apagar este documento? Não é possível recuperar.")) return;
    await supabase.storage.from("arquivo").remove([`${pasta}/${nome}`]);
    carregarFicheiros(pasta);
  };

  // Inscrições em workshops e lives (guardadas no progresso de cada pessoa)
  const inscricoesWorkshop = [];
  workshops.forEach((w) => {
    progressos.forEach((p) => {
      if (p.data?.inscricoesWorkshops?.[w.id]) {
        const pe = pessoa(p.user_id);
        inscricoesWorkshop.push({ acao: w.titulo, data: `${w.data} ${w.hora || ""}`.trim(), ...pe });
      }
    });
  });
  const inscricoesTodas = [
    ...inscricoesEvento.map((i) => ({ acao: i.evento || "Evento", data: arquivoData(i.criado_em), nome: i.nome, email: i.email, telefone: i.telefone, localidade: i.localidade, eventoChave: i.evento_chave })),
    ...inscricoesWorkshop,
  ];

  const totalPago = pagamentos.filter((p) => p.estado === "pago").reduce((s, p) => s + Number(p.valor || 0), 0);

  const separadores = [
    { id: "autorizacoes", nome: "Autorizações", n: consentimentos.length },
    { id: "fichas", nome: "Fichas", n: clientes.length },
    { id: "inscricoes", nome: "Inscrições", n: inscricoesTodas.length },
    { id: "pagamentos", nome: "Pagamentos", n: pagamentos.length },
    { id: "codigos", nome: "Códigos", n: codigosUsados.length },
    { id: "visualizacoes", nome: "Quem viu", n: new Set(visualizacoes.map((v) => v.user_id)).size },
    { id: "documentos", nome: "Documentos", n: null },
  ];

  const botaoExportar = (onClick) => (
    <button onClick={onClick} className="flex items-center gap-1.5 text-[13px] font-medium rounded-full px-3.5 py-2" style={{ backgroundColor: palette.navy, color: palette.creamSoft }}>
      <Download size={14} /> Exportar para Excel
    </button>
  );

  return (
    <div className="pb-28">
      <SectionHeader eyebrow="SÓ PARA A DONA" title="Arquivo da Escola" onBack={onBack} />

      <div className="px-6 mb-4 flex gap-2 overflow-x-auto pb-1">
        {separadores.map((s) => (
          <button
            key={s.id}
            onClick={() => { setTab(s.id); setPesquisa(""); }}
            className="shrink-0 rounded-full px-3.5 py-2 text-[13px] font-medium"
            style={tab === s.id ? { backgroundColor: palette.navy, color: palette.creamSoft } : { backgroundColor: palette.card, color: palette.navySoft, border: `1px solid ${palette.goldSoft}55` }}
          >
            {s.nome}{s.n !== null ? ` (${s.n})` : ""}
          </button>
        ))}
      </div>

      {tab !== "documentos" && (
        <div className="px-6 mb-4">
          <input
            type="text"
            value={pesquisa}
            onChange={(e) => setPesquisa(e.target.value)}
            placeholder="Pesquisar por nome, correio eletrónico ou telefone"
            className="w-full rounded-xl px-4 py-2.5 text-sm outline-none"
            style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55`, color: palette.ink }}
          />
        </div>
      )}

      <div className="px-6 space-y-3">
        {carregando && tab !== "documentos" && <p className="text-sm" style={{ color: palette.navySoft }}>A carregar…</p>}

        {!carregando && tab === "autorizacoes" && (
          <>
            <div className="flex items-center justify-between">
              <p className="text-[13px]" style={{ color: palette.navySoft }}>Autorizações RGPD aceites na aplicação</p>
              {botaoExportar(() => exportarCSV("autorizacoes-rgpd.csv", ["Data", "Nome", "Correio eletrónico", "Telefone", "Texto aceite"],
                consentimentos.map((c) => [arquivoData(c.aceite_em), c.nome, c.email, c.telefone, c.texto_aceite])))}
            </div>
            {consentimentos.length === 0 && <p className="text-sm" style={{ color: palette.navySoft }}>Ainda não há autorizações registadas.</p>}
            {consentimentos.filter((c) => filtro(`${c.nome} ${c.email} ${c.telefone}`)).map((c) => (
              <ArquivoCartao key={c.id} titulo={c.nome || c.email} linhas={[c.nome ? c.email : null, c.telefone, `Aceite em ${arquivoData(c.aceite_em)}`, `«${c.texto_aceite}»`]} />
            ))}
          </>
        )}

        {!carregando && tab === "fichas" && (
          <>
            <div className="flex items-center justify-between">
              <p className="text-[13px]" style={{ color: palette.navySoft }}>Todas as pessoas registadas</p>
              {botaoExportar(() => exportarCSV("fichas-clientes.csv", ["Nome", "Correio eletrónico", "Telefone", "Registo"],
                clientes.map((c) => [c.nome, c.email, c.telefone, arquivoData(c.criado_em)])))}
            </div>
            {clientes.filter((c) => filtro(`${c.nome} ${c.email} ${c.telefone}`)).map((c) => (
              <ArquivoCartao key={c.user_id} titulo={c.nome || c.email} linhas={[c.nome ? c.email : null, c.telefone ? `Tel. ${c.telefone}` : "Sem telefone", `Registo: ${arquivoData(c.criado_em)}`]} />
            ))}
          </>
        )}

        {!carregando && tab === "inscricoes" && (
          <>
            <div className="flex items-center justify-between">
              <p className="text-[13px]" style={{ color: palette.navySoft }}>Ações, formações, encontros e diretos</p>
              {botaoExportar(() => exportarCSV("inscricoes.csv", ["Ação", "Data", "Nome", "Correio eletrónico", "Telefone", "Localidade"],
                inscricoesTodas.map((i) => [i.acao, i.data, i.nome, i.email, i.telefone, i.localidade])))}
            </div>
            {inscricoesTodas.length === 0 && <p className="text-sm" style={{ color: palette.navySoft }}>Ainda não há inscrições.</p>}
            {eventosOnline.filter((e) => new Date(e.inicio).getTime() + (e.duracao_min || 90) * 60000 > Date.now()).map((e) => {
              const n = inscricoesTodas.filter((i) => i.eventoChave === e.chave).length;
              return (
                <div key={e.id} className="rounded-2xl px-4 py-3" style={{ backgroundColor: palette.navy }}>
                  <p className="text-sm font-medium" style={{ color: palette.creamSoft }}>{e.titulo}</p>
                  <p className="text-[13px]" style={{ color: palette.goldSoft }}>{n} inscrito{n === 1 ? "" : "s"} · ligação: {e.link}</p>
                  <button
                    onClick={() => { try { navigator.clipboard.writeText(mensagemEvento("", e)); alert("Mensagem copiada! Cola-a no grupo ou na lista de transmissão do WhatsApp."); } catch (err) {} }}
                    className="mt-2 w-full rounded-lg py-2 text-[13px] font-medium"
                    style={{ backgroundColor: palette.gold, color: palette.navy }}
                  >
                    Copiar mensagem com a ligação (para grupos do WhatsApp)
                  </button>
                </div>
              );
            })}
            {inscricoesTodas.filter((i) => filtro(`${i.acao} ${i.nome} ${i.email} ${i.telefone}`)).map((i, k) => {
              const ev = eventosOnline.find((e) => e.chave === i.eventoChave);
              const num = numeroWhatsApp(i.telefone);
              return (
                <div key={k}>
                  <ArquivoCartao titulo={i.nome || i.email || "Pessoa sem nome"} linhas={[i.acao, i.data, i.nome ? i.email : null, i.telefone, i.localidade]} />
                  {ev && num && (
                    <a
                      href={`https://wa.me/${num}?text=${encodeURIComponent(mensagemEvento(i.nome, ev))}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="mt-1.5 flex items-center justify-center rounded-lg py-2 text-[13px] font-medium"
                      style={{ backgroundColor: "#25D366", color: "#fff" }}
                    >
                      Enviar ligação por WhatsApp
                    </a>
                  )}
                </div>
              );
            })}
          </>
        )}

        {!carregando && tab === "pagamentos" && (
          <>
            <div className="rounded-2xl px-5 py-4" style={{ backgroundColor: palette.navy }}>
              <p className="text-[11px] tracking-[0.2em]" style={{ color: palette.goldSoft }}>TOTAL RECEBIDO</p>
              <p className="font-serif text-3xl" style={{ color: palette.creamSoft }}>{totalPago.toFixed(2).replace(".", ",")} €</p>
            </div>
            <div className="flex items-center justify-between">
              <p className="text-[13px]" style={{ color: palette.navySoft }}>Quem pagou e o quê</p>
              {botaoExportar(() => exportarCSV("pagamentos.csv", ["Data", "Nome", "Correio eletrónico", "O que pagou", "Método", "Valor (€)", "Estado", "Morada de envio"],
                pagamentos.map((p) => { const pe = pessoa(p.user_id); const env = (Array.isArray(p.itens) ? p.itens : []).filter((i) => i && i.envio).map((i) => `${i.envio.nome}, ${i.envio.morada}, ${i.envio.cp} ${i.envio.localidade}`).join(" | "); return [arquivoData(p.pago_em || p.criado_em), pe.nome, pe.email, p.descricao, p.tipo, String(p.valor).replace(".", ","), p.estado, env]; })))}
            </div>
            {pagamentos.length === 0 && <p className="text-sm" style={{ color: palette.navySoft }}>Ainda não há pagamentos.</p>}
            {pagamentos.filter((p) => { const pe = pessoa(p.user_id); return filtro(`${pe.nome} ${pe.email} ${p.descricao}`); }).map((p) => {
              const pe = pessoa(p.user_id);
              return (
                <ArquivoCartao
                  key={p.id}
                  titulo={`${Number(p.valor).toFixed(2).replace(".", ",")} € · ${p.estado === "pago" ? "Pago" : "Pendente"}`}
                  linhas={[p.descricao, pe.nome || pe.email || "Pessoa desconhecida", pe.nome ? pe.email : null, `${p.tipo === "mbway" ? "MB WAY" : p.tipo || ""} · ${arquivoData(p.pago_em || p.criado_em)}`]}
                />
              );
            })}
          </>
        )}


        {!carregando && tab === "visualizacoes" && (
          <>
            <div className="flex items-center justify-between">
              <p className="text-[13px]" style={{ color: palette.navySoft }}>Quem abriu cada aula dos cursos</p>
              {botaoExportar(() => exportarCSV("quem-viu-aulas.csv", ["Data", "Nome", "Correio eletrónico", "Telefone", "Curso", "Aula"],
                visualizacoes.map((v) => { const pe = pessoa(v.user_id); return [arquivoData(v.visto_em), pe.nome, pe.email, pe.telefone, v.curso_titulo, `Aula ${v.aula_numero} — ${v.aula_titulo}`]; })))}
            </div>
            {visualizacoes.length === 0 && <p className="text-sm" style={{ color: palette.navySoft }}>Ainda ninguém abriu aulas.</p>}
            {Object.values(visualizacoes.reduce((acc, v) => {
              const k = `${v.user_id}-${v.curso_id}`;
              if (!acc[k]) acc[k] = { user_id: v.user_id, curso: v.curso_titulo, aulas: {}, ultima: v.visto_em };
              acc[k].aulas[v.aula_numero] = v.aula_titulo;
              if (v.visto_em > acc[k].ultima) acc[k].ultima = v.visto_em;
              return acc;
            }, {})).filter((g) => { const pe = pessoa(g.user_id); return filtro(`${pe.nome} ${pe.email} ${pe.telefone} ${g.curso}`); }).map((g) => {
              const pe = pessoa(g.user_id);
              const nums = Object.keys(g.aulas).map(Number).sort((a, b) => a - b);
              return (
                <ArquivoCartao
                  key={`${g.user_id}-${g.curso}`}
                  titulo={pe.nome || pe.email || "Pessoa sem ficha"}
                  linhas={[pe.nome ? pe.email : null, pe.telefone, `${g.curso}: viu ${nums.length} aula${nums.length === 1 ? "" : "s"} (${nums.map((n) => `Aula ${n}`).join(", ")})`, `Última vez: ${arquivoData(g.ultima)}`]}
                />
              );
            })}
          </>
        )}
        {!carregando && tab === "codigos" && (
          <>
            <div className="flex items-center justify-between">
              <p className="text-[13px]" style={{ color: palette.navySoft }}>Quem usou códigos de oferta</p>
              {botaoExportar(() => exportarCSV("codigos-usados.csv", ["Data", "Código", "Nome", "Correio eletrónico", "Telefone"],
                codigosUsados.map((c) => { const pe = pessoa(c.user_id); return [arquivoData(c.resgatado_em), c.codigo, pe.nome, pe.email, pe.telefone]; })))}
            </div>
            {codigosUsados.length === 0 && <p className="text-sm" style={{ color: palette.navySoft }}>Ainda ninguém usou um código.</p>}
            {[...new Set(codigosUsados.map((c) => c.codigo))].map((cod) => (
              <p key={cod} className="text-[13px] font-medium" style={{ color: palette.gold }}>{cod}: {codigosUsados.filter((c) => c.codigo === cod).length} pessoa(s)</p>
            ))}
            {codigosUsados.filter((c) => { const pe = pessoa(c.user_id); return filtro(`${c.codigo} ${pe.nome} ${pe.email} ${pe.telefone}`); }).map((c) => {
              const pe = pessoa(c.user_id);
              return <ArquivoCartao key={`${c.codigo}-${c.user_id}`} titulo={pe.nome || pe.email || "Pessoa sem ficha"} linhas={[`Código ${c.codigo}`, pe.nome ? pe.email : null, pe.telefone, `Usado em ${arquivoData(c.resgatado_em)}`]} />;
            })}
          </>
        )}

        {tab === "documentos" && (
          <>
            <p className="text-[13px]" style={{ color: palette.navySoft }}>Guarda aqui autorizações assinadas, fichas em papel digitalizadas e listas de presenças (PDF ou foto, até 20 MB). Só tu consegues ver estes documentos.</p>
            <div className="flex gap-2 overflow-x-auto pb-1">
              {ARQUIVO_PASTAS.map((p) => (
                <button
                  key={p.id}
                  onClick={() => setPasta(p.id)}
                  className="shrink-0 rounded-full px-3 py-1.5 text-[13px]"
                  style={pasta === p.id ? { backgroundColor: palette.gold, color: palette.navy } : { backgroundColor: palette.card, color: palette.navySoft, border: `1px solid ${palette.goldSoft}55` }}
                >
                  {p.nome}
                </button>
              ))}
            </div>
            <label className="flex items-center justify-center gap-2 rounded-2xl py-3.5 text-sm font-medium cursor-pointer" style={{ backgroundColor: palette.navy, color: palette.creamSoft }}>
              <Plus size={16} /> {aCarregarFicheiro ? "A carregar…" : "Adicionar documento"}
              <input type="file" accept="application/pdf,image/*" onChange={carregarFicheiro} className="hidden" disabled={aCarregarFicheiro} />
            </label>
            {mensagem && <p className="text-[13px]" style={{ color: palette.navySoft }}>{mensagem}</p>}
            {ficheiros.length === 0 && <p className="text-sm" style={{ color: palette.navySoft }}>Ainda não há documentos nesta pasta.</p>}
            {ficheiros.map((f) => (
              <div key={f.name} className="rounded-2xl px-4 py-3 flex items-center gap-3" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
                <FileText size={18} style={{ color: palette.gold, flexShrink: 0 }} />
                <button onClick={() => abrirFicheiro(f.name)} className="flex-1 min-w-0 text-left">
                  <p className="text-sm truncate" style={{ color: palette.navy }}>{f.name.replace(/^\d+-/, "")}</p>
                  <p className="text-xs" style={{ color: palette.navySoft }}>{arquivoData(f.created_at)}</p>
                </button>
                <button onClick={() => apagarFicheiro(f.name)} aria-label="Apagar">
                  <Trash2 size={16} style={{ color: palette.navySoft }} />
                </button>
              </div>
            ))}
          </>
        )}
      </div>
    </div>
  );
}

function progressoInicial() {
  return {
    inscricoesWorkshops: {},
    sessoesMarcadas: [],
    materiaisDesbloqueados: {},
    cursosConcluidos: {},
    comunidadeDesbloqueada: false,
    disponibilidade: { dias: [], horas: [], meses: [], linkVideochamada: "" },
    papel: "aluno",
    reflexoesComunidade: {},
    fichaGratisPreenchida: false,
  };
}


/* ---------------------------------------------------------
   Convite para instalar a app (iPhone e Android)
--------------------------------------------------------- */
export function InstalarApp() {
  const [evento, setEvento] = useState(null);
  const [mostrar, setMostrar] = useState(false);
  const ua = (typeof navigator !== "undefined" && navigator.userAgent) || "";
  const ios = /iphone|ipad|ipod/i.test(ua) || (/macintosh/i.test(ua) && typeof navigator !== "undefined" && navigator.maxTouchPoints > 1);
  const android = /android/i.test(ua);
  const appInterna = /FBAN|FBAV|Instagram|WhatsApp|Line\//i.test(ua);
  const instalada = typeof window !== "undefined" && ((window.matchMedia && window.matchMedia("(display-mode: standalone)").matches) || window.navigator.standalone === true);
  useEffect(() => {
    if (instalada) return;
    let fechadoEm = 0;
    try { fechadoEm = Number(localStorage.getItem("escola3s:instalar-fechado") || 0); } catch (e) {}
    if (Date.now() - fechadoEm < 3 * 24 * 3600 * 1000) return;
    const antes = (e) => { e.preventDefault(); setEvento(e); setMostrar(true); };
    window.addEventListener("beforeinstallprompt", antes);
    const instalou = () => setMostrar(false);
    window.addEventListener("appinstalled", instalou);
    if (ios || android) { const t = setTimeout(() => setMostrar(true), 1500); return () => { clearTimeout(t); window.removeEventListener("beforeinstallprompt", antes); window.removeEventListener("appinstalled", instalou); }; }
    return () => { window.removeEventListener("beforeinstallprompt", antes); window.removeEventListener("appinstalled", instalou); };
  }, []);
  if (!mostrar || instalada) return null;
  const fechar = () => { setMostrar(false); try { localStorage.setItem("escola3s:instalar-fechado", String(Date.now())); } catch (e) {} };
  const instalar = async () => { if (!evento) return; evento.prompt(); try { await evento.userChoice; } catch (e) {} setEvento(null); setMostrar(false); };
  let instrucoes = null;
  if (!evento) {
    if (appInterna) instrucoes = "Abre esta ligação no Safari (iPhone) ou no Chrome (Android) para instalares a aplicação.";
    else if (ios) instrucoes = "Toca em Partilhar (o quadrado com a seta para cima) e depois em \u201cAdicionar ao ecrã principal\u201d.";
    else if (android) instrucoes = "Toca nos três pontos \u22ee do Chrome e depois em \u201cInstalar aplicação\u201d ou \u201cAdicionar ao ecrã principal\u201d.";
  }
  return (
    <div style={{ position: "fixed", left: 0, right: 0, bottom: 0, zIndex: 9999, display: "flex", justifyContent: "center", padding: "0 10px calc(10px + env(safe-area-inset-bottom, 0px))", pointerEvents: "none" }}>
      <div style={{ pointerEvents: "auto", width: "100%", maxWidth: 440, background: palette.navy, color: palette.creamSoft, borderRadius: 16, padding: "12px 14px", boxShadow: "0 12px 30px -10px rgba(0,0,0,0.45)", fontFamily: "Inter, sans-serif" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <img src="/apple-touch-icon.png" alt="" width={40} height={40} style={{ borderRadius: 10, flexShrink: 0 }} />
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontWeight: 600, fontSize: 14 }}>Instala a aplicação Escola 3S</div>
            <div style={{ fontSize: 11.5, opacity: 0.85, lineHeight: 1.35 }}>{instrucoes || "Fica no teu telemóvel, como uma aplicação normal. É gratuita."}</div>
          </div>
          <button onClick={fechar} aria-label="Fechar" style={{ background: "transparent", border: "none", color: palette.goldSoft, fontSize: 20, lineHeight: 1, padding: 4, cursor: "pointer" }}>×</button>
        </div>
        {evento && (
          <button onClick={instalar} style={{ marginTop: 10, width: "100%", border: "none", borderRadius: 999, padding: "10px 0", fontWeight: 600, fontSize: 13.5, background: palette.gold, color: palette.navy, cursor: "pointer" }}>Instalar agora</button>
        )}
      </div>
    </div>
  );
}

export default function App() {
  const [session, setSession] = useState(null);
  const [sessaoCarregada, setSessaoCarregada] = useState(false);
  const [emailEnviado, setEmailEnviado] = useState(null);
  const [emailRecuperacao, setEmailRecuperacao] = useState(null);
  const [modoNovaPassword, setModoNovaPassword] = useState(false);
  const [tab, setTab] = useState("inicio");
  const [secao, setSecao] = useState(null);
  const antesDoLeitor = useRef(null);
  const [leitorAberto, setLeitorAberto] = useState(null);
  useEffect(() => { if (!secao || !secao.startsWith("leitor-")) antesDoLeitor.current = secao; }, [secao]);
  useEffect(() => {
    const abrir = (e) => { if (typeof e.detail !== "string") return; if (e.detail.startsWith("leitor-")) { setLeitorAberto(e.detail); window.scrollTo(0, 0); } else setSecao(e.detail); };
    window.addEventListener("escola3s:abrir", abrir);
    return () => window.removeEventListener("escola3s:abrir", abrir);
  }, []);
  const [temaFormacao, setTemaFormacao] = useState(null);
  useEffect(() => { if (secao !== "formacao-hub") setTemaFormacao(null); }, [secao]);
  const [cursoAberto, setCursoAberto] = useState(null);
  const [clienteAberto, setClienteAberto] = useState(null);
  const [certificadoAberto, setCertificadoAberto] = useState(null);
  const [conversaAberta, setConversaAberta] = useState(null);

  const [progresso, setProgresso] = useState(progressoInicial);
  const [carregado, setCarregado] = useState(false);
  const [tentativaCarregar, setTentativaCarregar] = useState(0);
  const [formadorAcessoCursos, setFormadorAcessoCursos] = useState([]);
  const [consentimentoEmFalta, setConsentimentoEmFalta] = useState(false);
  const [fichaCliente, setFichaCliente] = useState(null);
  const [ecraPublico, setEcraPublico] = useState("montra"); // "montra" | "entrar" | "criar"
  const [naoLidas, setNaoLidas] = useState(0);
  const [creditosSessoes, setCreditosSessoes] = useState({});
  const [descontoCiclo, setDescontoCiclo] = useState(0);
  const [carrinhoItens, setCarrinhoItens] = useState(() => {
    try { return JSON.parse(window.localStorage.getItem("escola3s:carrinho") || "[]"); } catch (e) { return []; }
  });
  useEffect(() => {
    try { window.localStorage.setItem("escola3s:carrinho", JSON.stringify(carrinhoItens)); } catch (e) {}
  }, [carrinhoItens]);

  // RGPD: confirma se esta pessoa já deu autorização; se não, pede-a
  useEffect(() => {
    if (!session) { setConsentimentoEmFalta(false); return; }
    let cancelado = false;
    supabase
      .from("consentimentos_dados")
      .select("id")
      .eq("user_id", session.user.id)
      .limit(1)
      .then(({ data, error }) => {
        if (!cancelado && !error) setConsentimentoEmFalta(!data || data.length === 0);
      });
    return () => { cancelado = true; };
  }, [session]);

  // Novidades (marcações, avisos) para a dona e mentoras — verificado a cada 30 segundos
  const atualizarNaoLidas = async () => {
    if (!session) return;
    const { count } = await supabase.from("notificacoes").select("id", { count: "exact", head: true }).eq("destinatario_id", session.user.id).eq("lida", false);
    setNaoLidas(count || 0);
  };
  useEffect(() => {
    if (!session || (progresso.papel !== "dona" && progresso.papel !== "mentora")) return;
    atualizarNaoLidas();
    const t = setInterval(atualizarNaoLidas, 30000);
    const aoVoltar = () => { if (document.visibilityState === "visible") atualizarNaoLidas(); };
    document.addEventListener("visibilitychange", aoVoltar);
    return () => { clearInterval(t); document.removeEventListener("visibilitychange", aoVoltar); };
  }, [session, progresso.papel]);
  useEffect(() => {
    try { document.title = naoLidas > 0 ? `(${naoLidas}) Escola 3S` : "Escola 3S"; } catch (e) {}
  }, [naoLidas]);

  // Ficha de cliente (nome e telefone)
  useEffect(() => {
    if (!session) { setFichaCliente(null); return; }
    supabase.from("clientes").select("nome, telefone").eq("user_id", session.user.id).maybeSingle()
      .then(({ data }) => setFichaCliente(data || { nome: "", telefone: "" }));
  }, [session]);

  // Aplica as compras pagas (MB WAY, Multibanco, Payshop): materiais e meses de Comunidade
  const sincronizarCompras = async () => {
    if (!session) return;
    const { data, error } = await supabase
      .from("pagamentos")
      .select("descricao, itens, pago_em, criado_em")
      .eq("user_id", session.user.id)
      .eq("estado", "pago")
      .order("pago_em", { ascending: true });
    if (error) return;
    let ate = null;
    const materiais = {};
    const cursosPagos = {};
    const ciclosComprados = {};
    (data || []).forEach((p) => {
      const d = new Date(p.pago_em || p.criado_em);
      const itens = Array.isArray(p.itens) ? p.itens : [];
      const temComunidade = itens.some((i) => i.tipo === "comunidade") || (!p.itens && /^Comunidade 3S/.test(p.descricao || ""));
      if (temComunidade) {
        const base = ate && ate > d ? ate : d;
        const n = new Date(base);
        n.setMonth(n.getMonth() + 1);
        ate = n;
      }
      itens.forEach((i) => {
        if (i.tipo === "material" && i.materialId != null) materiais[i.materialId] = true;
        if (i.tipo === "material_fisico" && i.materialId != null) materiais[i.materialId + "-fisico"] = true;
        if (i.tipo === "ciclo_sessoes" && i.servicoTipo) ciclosComprados[i.servicoTipo] = (ciclosComprados[i.servicoTipo] || 0) + (Number(i.sessoes) || SESSOES_POR_CICLO);
        if (i.tipo === "curso" && i.cursoId != null) {
          cursosPagos[i.cursoId] = true;
          const c = cursos.find((x) => x.id === i.cursoId);
          if (c) materiaisDoCurso(c).forEach((m) => { materiais[m.id] = true; });
        }
      });
    });
    const { data: usadas } = await supabase.from("marcacoes").select("tipo").eq("user_id", session.user.id).eq("pago_com_ciclo", true).neq("estado", "cancelada");
    const restantes = {};
    Object.entries(ciclosComprados).forEach(([tipo, n]) => {
      restantes[tipo] = Math.max(0, n - (usadas || []).filter((m) => m.tipo === tipo).length);
    });
    setCreditosSessoes(restantes);
    const { data: desc } = await supabase.rpc("meu_desconto_ciclo");
    setDescontoCiclo(Number(desc) || 0);
    setProgresso((p) => {
      const novoAte = ate ? ate.toISOString() : (p.comunidadePagaAte || null);
      const faltaMaterial = Object.keys(materiais).some((k) => !p.materiaisDesbloqueados[k]);
      const faltaCurso = Object.keys(cursosPagos).some((k) => !(p.cursosComprados && p.cursosComprados[k]));
      if (novoAte === (p.comunidadePagaAte || null) && !faltaMaterial && !faltaCurso) return p;
      return { ...p, comunidadePagaAte: novoAte, materiaisDesbloqueados: { ...p.materiaisDesbloqueados, ...materiais }, cursosComprados: { ...(p.cursosComprados || {}), ...cursosPagos } };
    });
  };

  useEffect(() => {
    if (!carregado || !session) return;
    try {
      if (window.localStorage.getItem("escola3s:abrirCarrinho") === "1") {
        window.localStorage.removeItem("escola3s:abrirCarrinho");
        setSecao("carrinho");
      }
      const destino = window.localStorage.getItem("escola3s:abrirDestino");
      if (destino) {
        window.localStorage.removeItem("escola3s:abrirDestino");
        if (destino.startsWith("curso:")) {
          const c = TODOS_CURSOS.find((x) => String(x.id) === destino.split(":")[1]);
          if (c) setCursoAberto(c);
        } else setSecao(destino);
      }
    } catch (e) {}
    sincronizarCompras();
    const aoVoltar = () => { if (document.visibilityState === "visible") sincronizarCompras(); };
    document.addEventListener("visibilitychange", aoVoltar);
    return () => document.removeEventListener("visibilitychange", aoVoltar);
  }, [carregado, session]);

  const carrinho = {
    itens: carrinhoItens,
    descontoCiclo,
    aoAtivarCodigo: () => sincronizarCompras(),
    adicionar: (item) => setCarrinhoItens((l) => (l.some((i) => i.chave === item.chave) ? l : [...l, item])),
    remover: (chave) => setCarrinhoItens((l) => l.filter((i) => i.chave !== chave)),
    limpar: () => setCarrinhoItens([]),
    abrir: () => { setCursoAberto(null); setSecao("carrinho"); },
  };

  // Sessão de autenticação (email + password)
  useEffect(() => {
    let cancelado = false;
    supabase.auth.getSession().then(({ data }) => {
      if (!cancelado) {
        setSession(data.session);
        setSessaoCarregada(true);
      }
    });
    const { data: listener } = supabase.auth.onAuthStateChange((event, novaSessao) => {
      if (event === "PASSWORD_RECOVERY") {
        setModoNovaPassword(true);
      }
      setSession(novaSessao);
      setSessaoCarregada(true);
    });
    return () => {
      cancelado = true;
      listener.subscription.unsubscribe();
    };
  }, []);

  // Carrega o progresso da pessoa a partir da base de dados, assim que há sessão
  useEffect(() => {
    setCarregado(false);
    if (!session) {
      setProgresso(progressoInicial());
      return;
    }
    let cancelado = false;
    (async () => {
      try {
        const { data, error } = await supabase
          .from("user_progress")
          .select("data")
          .eq("user_id", session.user.id)
          .maybeSingle();

        if (error) {
          // Não foi possível ler os dados (rede fraca, por exemplo): NÃO grava nada por cima e tenta outra vez
          if (!cancelado) setTimeout(() => setTentativaCarregar((n) => n + 1), 4000);
          return;
        }
        if (!cancelado) {
          const salvo = (data && data.data) ? data.data : {};
          const base = progressoInicial();
          setProgresso({
            ...base,
            ...salvo,
            disponibilidade: { ...base.disponibilidade, ...(salvo.disponibilidade || {}) },
            reflexoesComunidade: { ...base.reflexoesComunidade, ...(salvo.reflexoesComunidade || {}) },
            papel: salvo.papel || base.papel,
          });
        }

        // Garante que existe ficha de cliente para esta pessoa
        await supabase
          .from("clientes")
          .upsert(
            { user_id: session.user.id, email: session.user.email, atualizado_em: new Date().toISOString() },
            { onConflict: "user_id", ignoreDuplicates: false }
          );

        // Se veio de um login com o código de mentora, cria o pedido (só uma vez)
        let pedirMentora = null;
        try {
          pedirMentora = window.localStorage.getItem("escola3s:pedir-mentora");
          if (pedirMentora) window.localStorage.removeItem("escola3s:pedir-mentora");
        } catch (e) {}

        if (pedirMentora) {
          await supabase
            .from("pedidos_mentora")
            .upsert(
              { user_id: session.user.id, email: session.user.email },
              { onConflict: "user_id", ignoreDuplicates: true }
            );
        }
      } catch (e) {
        // erro inesperado: não marca como carregado, para não apagar dados guardados
        if (!cancelado) setTimeout(() => setTentativaCarregar((n) => n + 1), 4000);
        return;
      }
      if (!cancelado) setCarregado(true);
    })();
    return () => { cancelado = true; };
  }, [session?.user?.id, tentativaCarregar]);

  // Guarda o progresso na base de dados sempre que muda
  useEffect(() => {
    if (!carregado || !session) return;
    supabase
      .from("user_progress")
      .upsert({ user_id: session.user.id, data: progresso, updated_at: new Date().toISOString() })
      .then(() => {})
      .catch(() => {});
  }, [progresso, carregado, session]);

  const toggleInscricao = (id) =>
    setProgresso((p) => ({
      ...p,
      inscricoesWorkshops: { ...p.inscricoesWorkshops, [id]: !p.inscricoesWorkshops[id] },
    }));

  const registarSessao = (sessao) =>
    setProgresso((p) => ({ ...p, sessoesMarcadas: [...p.sessoesMarcadas, sessao] }));

  const desbloquearMaterial = (id) =>
    setProgresso((p) => ({
      ...p,
      materiaisDesbloqueados: { ...p.materiaisDesbloqueados, [id]: true },
    }));

  const toggleConcluido = (id) =>
    setProgresso((p) => ({
      ...p,
      cursosConcluidos: {
        ...p.cursosConcluidos,
        [id]: p.cursosConcluidos[id] ? false : new Date().toISOString(),
      },
    }));

  const desbloquearComunidade = () =>
    setProgresso((p) => ({ ...p, comunidadeDesbloqueada: true }));

  const adicionarDataDisponivel = (data) =>
    setProgresso((p) => {
      if (p.disponibilidade.dias.includes(data)) return p;
      return { ...p, disponibilidade: { ...p.disponibilidade, dias: [...p.disponibilidade.dias, data] } };
    });

  const removerDataDisponivel = (data) =>
    setProgresso((p) => ({
      ...p,
      disponibilidade: { ...p.disponibilidade, dias: p.disponibilidade.dias.filter((d) => d !== data) },
    }));

  const adicionarHora = (hora) =>
    setProgresso((p) => {
      if (p.disponibilidade.horas.includes(hora)) return p;
      return { ...p, disponibilidade: { ...p.disponibilidade, horas: [...p.disponibilidade.horas, hora].sort() } };
    });

  const removerHora = (hora) =>
    setProgresso((p) => ({
      ...p,
      disponibilidade: { ...p.disponibilidade, horas: p.disponibilidade.horas.filter((h) => h !== hora) },
    }));

  const horariosDisponiveis = gerarHorariosComData(progresso.disponibilidade.dias, progresso.disponibilidade.horas);

  // Sempre que a mentora muda a disponibilidade, isso fica visível publicamente
  useEffect(() => {
    if (!carregado || !session || (progresso.papel !== "mentora" && progresso.papel !== "dona")) return;
    supabase
      .from("mentores_disponibilidade")
      .upsert(
        {
          user_id: session.user.id,
          email: session.user.email,
          dias: progresso.disponibilidade.dias,
          horas: progresso.disponibilidade.horas,
          meses: [],
          link_videochamada: progresso.disponibilidade.linkVideochamada || null,
          atualizado_em: new Date().toISOString(),
        },
        { onConflict: "user_id" }
      )
      .then(() => {})
      .catch(() => {});
  }, [progresso.disponibilidade, progresso.papel, carregado, session]);


  // (registo de entrada gratuita agora acontece no envio do formulário FichaEntradaGratisScreen)

  // Descobrir para que cursos esta pessoa tem acesso de formador (se for mentora)
  useEffect(() => {
    if (!session || (progresso.papel !== "mentora" && progresso.papel !== "dona")) {
      setFormadorAcessoCursos([]);
      return;
    }
    supabase
      .from("formador_acesso")
      .select("curso_id")
      .eq("mentor_user_id", session.user.id)
      .then(({ data }) => setFormadorAcessoCursos((data || []).map((r) => r.curso_id)))
      .catch(() => setFormadorAcessoCursos([]));
  }, [session, progresso.papel]);


  const guardarReflexao = (mes, texto) =>
    setProgresso((p) => ({
      ...p,
      reflexoesComunidade: { ...p.reflexoesComunidade, [mes]: texto },
    }));

  const mudarTab = (novaTab) => {
    setTab(novaTab);
    setSecao(null);
    setCursoAberto(null);
    setClienteAberto(null);
    setCertificadoAberto(null);
    setConversaAberta(null);
  };

  const eventoPublico = (() => { try { return new URLSearchParams(window.location.search).get("inscricao"); } catch (e) { return null; } })();
  if (eventoPublico) return <InscricaoEventoPublica eventoId={eventoPublico} />;

  if (!sessaoCarregada) {
    return (
      <>
        <style>{FONTS}</style>
        <style>{`@keyframes abrir{from{opacity:0;transform:scale(.92)}to{opacity:1;transform:scale(1)}}@keyframes subir{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}@keyframes carregar{from{transform:translateX(-100%)}to{transform:translateX(260%)}}`}</style>
        <div
          className="fixed inset-0 flex flex-col items-center justify-center"
          style={{ background: `linear-gradient(160deg, ${palette.navy} 0%, #24436E 100%)`, fontFamily: "Inter, sans-serif" }}
        >
          <img src="/marca-3s.png" alt="" style={{ width: 120, height: "auto", animation: "abrir 1.1s ease-out both" }} />
          <p style={{ margin: "26px 0 0", fontFamily: "'Cormorant Garamond', Georgia, serif", fontWeight: 600, fontSize: 38, lineHeight: 1, color: palette.creamSoft, letterSpacing: "0.02em", animation: "subir 1s .25s ease-out both" }}>Escola <span style={{ color: palette.gold }}>3S</span></p>
          <div style={{ marginTop: 14, width: 56, height: 1, background: palette.gold, animation: "subir 1s .35s ease-out both" }} />
          <p style={{ margin: "14px 0 0", fontSize: 11, fontWeight: 500, letterSpacing: "0.32em", color: palette.goldSoft, animation: "subir 1s .45s ease-out both" }}>SABER · SENTIR · SER</p>
          <div style={{ position: "absolute", bottom: "calc(56px + env(safe-area-inset-bottom, 0px))", display: "flex", flexDirection: "column", alignItems: "center" }}>
            <div style={{ width: 110, height: 2, borderRadius: 2, background: "rgba(220,196,138,0.22)", overflow: "hidden" }}>
              <div style={{ width: "40%", height: "100%", background: palette.gold, animation: "carregar 1.3s ease-in-out infinite" }} />
            </div>
            <p style={{ margin: "14px 0 0", fontSize: 10, letterSpacing: "0.25em", color: "rgba(247,238,221,0.6)" }}>LIDERANÇA · VIDA · DESPORTO</p>
          </div>
        </div>
      </>
    );
  }

  if (modoNovaPassword) {
    return (
      <>
        <style>{FONTS}</style>
        <div style={{ fontFamily: "Inter, sans-serif" }}>
          <style>{`.font-serif { font-family: 'Cormorant Garamond', serif; }`}</style>
          <NovaPasswordScreen onConcluido={() => setModoNovaPassword(false)} />
        </div>
      </>
    );
  }

  if (!session) {
    return (
      <>
        <style>{FONTS}</style>
        <div style={{ fontFamily: "Inter, sans-serif" }}>
          <style>{`.font-serif { font-family: 'Cormorant Garamond', serif; }`}</style>
          {emailEnviado ? (
            <AguardaEmailScreen email={emailEnviado} />
          ) : emailRecuperacao ? (
            <AguardaEmailScreen email={emailRecuperacao} recuperacao />
          ) : ecraPublico === "montra" ? (
            <MontraPublica
              onDestino={(d) => { try { window.localStorage.setItem("escola3s:abrirDestino", d); } catch (e) {} setEcraPublico("criar"); }}
              onCriarConta={() => setEcraPublico("criar")}
              onEntrar={() => setEcraPublico("entrar")}
              onEscolher={(item) => {
                if (item.valor === null || item.valor === undefined) return;
                setCarrinhoItens((l) => (l.some((i) => i.chave === item.chave) ? l : [...l, item]));
                try { window.localStorage.setItem("escola3s:abrirCarrinho", "1"); } catch (e) {}
                setEcraPublico("criar");
              }}
            />
          ) : (
            <>
              <div className="w-full flex justify-center" style={{ backgroundColor: palette.cream }}>
                <div className="w-full max-w-md px-6 pt-4" style={{ backgroundColor: palette.creamSoft }}>
                  <button onClick={() => setEcraPublico("montra")} className="flex items-center gap-1 text-[13px]" style={{ color: palette.navySoft }}>
                    <ChevronLeft size={16} /> Ver cursos e preços
                  </button>
                  {carrinhoItens.length > 0 && (
                    <p className="text-[13px] mt-2 rounded-xl px-3 py-2" style={{ backgroundColor: palette.card, color: palette.navy, border: `1px solid ${palette.gold}` }}>
                      🛒 Guardámos no teu carrinho: {carrinhoItens.map((i) => i.titulo).join(", ")}. Cria a tua conta (ou entra) para finalizar a compra.
                    </p>
                  )}
                </div>
              </div>
              <LoginScreen key={ecraPublico} modoInicial={ecraPublico} onPedirConfirmacaoEmail={setEmailEnviado} onPedidoRecuperacao={setEmailRecuperacao} />
            </>
          )}
        </div>
      </>
    );
  }

  if (consentimentoEmFalta) {
    return <ConsentimentoGate session={session} onAceite={() => setConsentimentoEmFalta(false)} />;
  }

  const temAcessoCurso = (c) =>
    progresso.papel === "dona" ||
    Boolean(c.gratuito) ||
    formadorAcessoCursos.includes(c.id) ||
    Boolean(progresso.cursosComprados && progresso.cursosComprados[c.id]);

  const materiaisAcesso = comunidadeEmDia(progresso)
    ? { ...progresso.materiaisDesbloqueados, ...materiaisIncluidosComunidade() }
    : progresso.materiaisDesbloqueados;

  let content;
  if (certificadoAberto) {
    content = (
      <CertificadoScreen
        curso={certificadoAberto}
        dataConclusao={progresso.cursosConcluidos[certificadoAberto.id]}
        email={session.user.email}
        onBack={() => setCertificadoAberto(null)}
      />
    );
  } else if (clienteAberto) {
    content = (
      <FichaClienteScreen
        cliente={clienteAberto}
        onBack={() => setClienteAberto(null)}
      />
    );
  } else if (secao === "carrinho") {
    content = <CarrinhoScreen onBack={() => setSecao("produtos")} onPagamentoConfirmado={sincronizarCompras} />;
  } else if (leitorAberto) {
    content = <LeitorLivroScreen key={leitorAberto} livroId={Number(leitorAberto.slice(7).split(":")[0])} capInicial={leitorAberto.includes(":") ? Number(leitorAberto.split(":")[1]) : null} onBack={() => setLeitorAberto(null)} />;
  } else if (cursoAberto && !cursoAberto.interativo && !temAcessoCurso(cursoAberto)) {
    content = <CursoVendaScreen curso={cursoAberto} onBack={() => setCursoAberto(null)} />;
  } else if (cursoAberto && cursoAberto.gratuito && progresso.papel !== "dona" && fichaCliente && !(fichaCliente.nome && fichaCliente.telefone)) {
    content = <FichaCursoScreen curso={cursoAberto} session={session} onBack={() => setCursoAberto(null)} onGuardada={setFichaCliente} />;
  } else if (cursoAberto && cursoAberto.interativo) {
    content = (
      <CursoInterativoScreen
        curso={cursoAberto}
        estado={(progresso.cursosInterativos || {})[cursoAberto.id]}
        onGuardar={(fn) => setProgresso((p) => { const todos = p.cursosInterativos || {}; return { ...p, cursosInterativos: { ...todos, [cursoAberto.id]: fn(todos[cursoAberto.id] || {}) } }; })}
        concluidoEm={progresso.cursosConcluidos[cursoAberto.id]}
        onConcluirCurso={() => setProgresso((p) => (p.cursosConcluidos[cursoAberto.id] ? p : { ...p, cursosConcluidos: { ...p.cursosConcluidos, [cursoAberto.id]: new Date().toISOString() } }))}
        onCertificado={() => setCertificadoAberto(cursoAberto)}
        onBack={() => setCursoAberto(null)}
        onAbrirLab={cursoAberto.escolaId === "lideranca" || cursoAberto.escolaId === "desporto" ? () => { const lab = cursoAberto.escolaId === "desporto" ? "lab-desporto" : "lab-lideranca"; setCursoAberto(null); setSecao(lab); } : null}
        semAcesso={!temAcessoCurso(cursoAberto)}
        materiaisDesbloqueados={materiaisAcesso}
        onDesbloquearMaterial={desbloquearMaterial}
        acessoTotal={progresso.papel === "dona"}
        formadorAutorizado={formadorAcessoCursos.includes(cursoAberto.id)}
      />
    );
  } else if (cursoAberto) {
    content = (
      <ConteudoDetalhe
        curso={cursoAberto}
        concluido={Boolean(progresso.cursosConcluidos[cursoAberto.id])}
        onToggleConcluido={() => toggleConcluido(cursoAberto.id)}
        onBack={() => setCursoAberto(null)}
        materiaisDesbloqueados={materiaisAcesso}
        onDesbloquearMaterial={desbloquearMaterial}
        acessoTotal={progresso.papel === "dona"}
        formadorAutorizado={formadorAcessoCursos.includes(cursoAberto.id)}
      />
    );
  } else if (secao === "codigo") {
    content = (
      <div className="pb-28">
        <SectionHeader eyebrow="OFERTA" title="Código de oferta" onBack={() => setSecao(null)} />
        <div className="px-6 space-y-4">
          <p className="text-sm leading-relaxed" style={{ color: palette.ink }}>Escreve o código que recebeste e carrega em Ativar. As ofertas ficam logo na tua conta.</p>
          <ResgatarCodigo onAtivado={() => sincronizarCompras()} />
        </div>
      </div>
    );
  } else if (secao === "formacao-hub") {
    content = (
      <FormacaoHubScreen
        onBack={() => { setTemaFormacao(null); setSecao(null); }}
        onAbrir={setSecao}
        tema={temaFormacao}
        setTema={setTemaFormacao}
        temAcesso={temAcessoCurso}
        onAbrirCurso={setCursoAberto}
        desbloqueados={materiaisAcesso}
        onDesbloquear={desbloquearMaterial}
        acessoTotal={progresso.papel === "dona"}
      />
    );
  } else if (secao === "alunos") {
    content = <CatalogoCursosScreen onBack={() => setSecao("formacao-hub")} temAcesso={temAcessoCurso} onAbrirCurso={setCursoAberto} onAreaAluno={() => setSecao("aluno")} />;
  } else if (secao === "lideranca-3s") {
    content = <EscolaScreen escola="lideranca" onBack={() => setSecao(null)} onOpen={setSecao} temAcesso={temAcessoCurso} onAbrirCurso={setCursoAberto} desbloqueados={materiaisAcesso} acessoTotal={progresso.papel === "dona"} />;
  } else if (secao === "lab-lideranca" || (secao || "").startsWith("lab-lideranca:")) {
    content = (
      <LaboratorioLiderancaScreen
        key={secao}
        inicial={(secao || "").startsWith("lab-lideranca:") ? secao.split(":")[1] : null}
        onBack={() => setSecao("lideranca-3s")}
        resultados={progresso.testesLideranca || {}}
        onGuardar={(chave, valor) => setProgresso((p) => ({ ...p, testesLideranca: { ...(p.testesLideranca || {}), [chave]: valor } }))}
        onMarcar={() => setSecao("marcar:lideranca")}
      />
    );
  } else if (secao === "lab-desporto" || (secao || "").startsWith("lab-desporto:")) {
    content = (
      <LaboratorioScreen
        key={secao}
        cfg={LAB_DESPORTO}
        inicial={(secao || "").startsWith("lab-desporto:") ? secao.split(":")[1] : null}
        onBack={() => setSecao("desporto-3s")}
        resultados={progresso.testesDesporto || {}}
        onGuardar={(chave, valor) => setProgresso((p) => ({ ...p, testesDesporto: { ...(p.testesDesporto || {}), [chave]: valor } }))}
        onMarcar={() => setSecao("marcar:desporto")}
      />
    );
  } else if (secao === "lab-vida" || (secao || "").startsWith("lab-vida:")) {
    content = (
      <LaboratorioScreen
        key={secao}
        cfg={LAB_VIDA}
        inicial={(secao || "").startsWith("lab-vida:") ? secao.split(":")[1] : null}
        onBack={() => setSecao("desenvolvimento-3s")}
        resultados={progresso.testesVida || {}}
        onGuardar={(chave, valor) => setProgresso((p) => ({ ...p, testesVida: { ...(p.testesVida || {}), [chave]: valor } }))}
        onMarcar={() => setSecao("marcar:desenvolvimento")}
      />
    );
  } else if (secao === "desporto-3s") {
    content = <EscolaScreen escola="desporto" onBack={() => setSecao(null)} onOpen={setSecao} temAcesso={temAcessoCurso} onAbrirCurso={setCursoAberto} desbloqueados={materiaisAcesso} acessoTotal={progresso.papel === "dona"} />;
  } else if (secao === "desenvolvimento-3s") {
    content = <EscolaScreen escola="desenvolvimento" onBack={() => setSecao(null)} onOpen={setSecao} temAcesso={temAcessoCurso} onAbrirCurso={setCursoAberto} desbloqueados={materiaisAcesso} acessoTotal={progresso.papel === "dona"} />;
  } else if (secao === "produtos") {
    content = <ProdutosScreen onBack={() => setSecao(null)} onOpen={setSecao} />;
  } else if (secao && secao.startsWith("leitor-")) {
    content = <LeitorLivroScreen key={secao} livroId={Number(secao.slice(7).split(":")[0])} capInicial={secao.includes(":") ? Number(secao.split(":")[1]) : null} onBack={() => setSecao(antesDoLeitor.current || null)} />;
  } else if (secao === "livros") {
    content = <LivrosScreen onBack={() => setSecao("produtos")} materiaisDesbloqueados={materiaisAcesso} />;
  } else if (secao === "aluno") {
    content = (
      <AreaAlunoScreen
        onBack={() => setSecao(null)}
        onOpenCurso={setCursoAberto}
        cursosConcluidos={progresso.cursosConcluidos}
        materiaisDesbloqueados={materiaisAcesso}
        onVerCertificado={setCertificadoAberto}
      />
    );
  } else if (secao === "notificacoes") {
    content = <NotificacoesScreen onBack={() => setSecao(null)} />;
  } else if (secao === "workshops") {
    content = <WorkshopsScreen onBack={() => setSecao(null)} onAbrirCurso={setCursoAberto} />;
  } else if (secao === "podcast") {
    content = <PodcastScreen onBack={() => setSecao(null)} souDona={progresso.papel === "dona"} />;
  } else if (secao === "formacao") {
    content = <FormacaoScreen onBack={() => setSecao(null)} onOpenCurso={setCursoAberto} cursosConcluidos={progresso.cursosConcluidos} />;
  } else if (secao === "escola-lideranca") {
    content = <FormacaoScreen onBack={() => setSecao("lideranca-3s")} onOpenCurso={setCursoAberto} cursosConcluidos={progresso.cursosConcluidos} escolaFixa="lideranca" />;
  } else if (secao === "escola-ser") {
    content = <FormacaoScreen onBack={() => setSecao("desenvolvimento-3s")} onOpenCurso={setCursoAberto} cursosConcluidos={progresso.cursosConcluidos} escolaFixa="ser" />;
  } else if (secao === "material") {
    content = (
      <MaterialDidaticoScreen
        onBack={() => setSecao(null)}
        desbloqueados={materiaisAcesso}
        onDesbloquear={desbloquearMaterial}
        acessoTotal={progresso.papel === "dona" || progresso.papel === "mentora"}
      />
    );
  } else if (secao === "marcar") {
    content = <EscolherAreaSessaoScreen onBack={() => setSecao(null)} onEscolher={(area) => setSecao("marcar:" + area)} />;
  } else if ((secao || "").startsWith("marcar:")) {
    content = (
      <MarcarSessaoScreen
        onBack={() => setSecao(null)}
        onConfirmar={registarSessao}
        creditos={creditosSessoes}
        descontoCiclo={descontoCiclo}
        onUsouCredito={sincronizarCompras}
        area={(secao || "").startsWith("marcar:") ? secao.split(":")[1] : null}
      />
    );
  } else if (secao === "agenda-mentora") {
    content = <AgendaMentoraScreen onBack={() => setSecao(null)} linkVideochamada={progresso.disponibilidade.linkVideochamada} onVista={atualizarNaoLidas} />;
  } else if (secao === "disponibilidade") {
    content = (
      <DisponibilidadeScreen
        onBack={() => setSecao(null)}
        disponibilidade={progresso.disponibilidade}
        onAdicionarData={adicionarDataDisponivel}
        onRemoverData={removerDataDisponivel}
        onAdicionarHora={adicionarHora}
        onRemoverHora={removerHora}
        onGuardarLinkVideochamada={(link) => setProgresso((p) => ({ ...p, disponibilidade: { ...p.disponibilidade, linkVideochamada: link } }))}
        onDefinir={(dias, horas) => setProgresso((p) => ({ ...p, disponibilidade: { ...p.disponibilidade, dias, horas } }))}
      />
    );
  } else if (secao === "painel-mentora") {
    content = (
      <PainelMentoraScreen
        onBack={() => setSecao(null)}
        progresso={progresso}
        onVerDashboard={() => setSecao("dashboard-mentora")}
        onVerAcessoFormadores={() => setSecao("acesso-formadores")}
        onVerArquivo={() => setSecao("arquivo")}
        onVerTestes={() => setSecao("resultados-testes")}
      />
    );
  } else if (secao === "resultados-testes" && progresso.papel === "dona") {
    content = <ResultadosTestesScreen onBack={() => setSecao("painel-mentora")} />;
  } else if (secao === "acesso-formadores") {
    content = <AcessoFormadoresScreen onBack={() => setSecao("painel-mentora")} />;
  } else if (secao === "arquivo") {
    content = <ArquivoEscolaScreen onBack={() => setSecao("painel-mentora")} />;
  } else if (secao === "dashboard-mentora") {
    content = (
      <DashboardMentoraScreen
        onBack={() => setSecao("painel-mentora")}
        onAbrirCliente={(c) => setClienteAberto(c)}
      />
    );
  } else if (tab === "inicio") {
    content = (
      <InicioScreen
        onOpen={setSecao}
        email={session.user.email}
        papel={progresso.papel}
        naoLidas={naoLidas}
        onVerAgenda={() => setSecao("agenda-mentora")}
        onVerPainel={() => setSecao("painel-mentora")}
        onVerNotificacoes={() => setSecao("notificacoes")}
      />
    );
  } else if (tab === "explorar") {
    content = <ExplorarScreen onOpen={setSecao} />;
  } else if (tab === "agenda") {
    content = <AgendaScreen inscricoesWorkshops={progresso.inscricoesWorkshops} sessoesMarcadas={progresso.sessoesMarcadas} />;
  } else if (tab === "perfil") {
    content = (
      <PerfilScreen
        onVerAreaAluno={() => { setTab("inicio"); setSecao("aluno"); }}
        onVerDisponibilidade={() => { setTab("perfil"); setSecao("disponibilidade"); }}
        onVerAgendaMentora={() => { setTab("perfil"); setSecao("agenda-mentora"); }}
        onVerPainelMentora={() => { setTab("perfil"); setSecao("painel-mentora"); }}
        papel={progresso.papel}
        onSair={() => supabase.auth.signOut()}
        email={session.user.email}
      />
    );
  }

  return (
    <>
      <style>{FONTS}</style>
      <style>{`.font-serif { font-family: 'Cormorant Garamond', serif; }`}</style>
      <div className="min-h-screen w-full flex justify-center" style={{ backgroundColor: palette.cream, fontFamily: "Inter, sans-serif" }}>
        <div className="w-full max-w-md relative" style={{ backgroundColor: palette.creamSoft }}>
          <NotificacoesSino onAbrir={() => setSecao("notificacoes")} papel={progresso.papel} />
          <CarrinhoContext.Provider value={carrinho}>
            {content}
            {(progresso.papel === "dona" || progresso.papel === "mentora") && <PopupMarcacoesDoDia papel={progresso.papel} />}
            {secao !== "carrinho" && (!cursoAberto || leitorAberto) && (
              <button
                onClick={carrinho.abrir}
                className="fixed z-40 flex items-center gap-2 rounded-full px-4 py-2.5 text-sm font-medium shadow-lg"
                style={{ bottom: "calc(88px + env(safe-area-inset-bottom, 0px))", right: "max(16px, calc(50vw - 208px))", backgroundColor: palette.gold, color: palette.navy }}
              >
                <ShoppingBag size={16} /> Carrinho ({carrinhoItens.length})
              </button>
            )}
          </CarrinhoContext.Provider>
          {!cursoAberto && <BottomNav active={tab} onChange={mudarTab} />}
        </div>
      </div>
    </>
  );
}
